function StatusBadge({ status, isLive }: { status?: string; isLive?: boolean }) {
  const s = status || '';
  if (s === 'pending')
    return (
      <span className="bg-[#1a1500] text-[#F5C518] px-2.5 py-1 rounded-full text-[11px] font-black">
        Pending
      </span>
    );
  if (s === 'approved' && isLive)
    return (
      <span className="bg-[#0f2010] text-[#22C55E] px-2.5 py-1 rounded-full text-[11px] font-black">
        Live ●
      </span>
    );
  if (s === 'approved' && !isLive)
    return (
      <span className="bg-[#1a1a1a] text-[#888] px-2.5 py-1 rounded-full text-[11px] font-black">
        Approved (offline)
      </span>
    );
  if (s === 'rejected')
    return (
      <span className="bg-[#1a0808] text-[#EF4444] px-2.5 py-1 rounded-full text-[11px] font-black">
        Rejected
      </span>
    );
  if (s === 'suspended')
    return (
      <span className="bg-[#1a1a1a] text-[#888] px-2.5 py-1 rounded-full text-[11px] font-black">
        Suspended
      </span>
    );
  return null;
}

function BookingStatusBadge({ status }: { status?: string }) {
  const s = (status || '').toLowerCase();
  if (s === 'confirmed' || s === 'completed')
    return (
      <span className="bg-[#0f2010] text-[#22C55E] px-2.5 py-1 rounded-full text-[11px] font-black">
        {status}
      </span>
    );
  if (s === 'pending')
    return (
      <span className="bg-[#1a1500] text-[#F5C518] px-2.5 py-1 rounded-full text-[11px] font-black">
        {status}
      </span>
    );
  if (s === 'cancelled')
    return (
      <span className="bg-[#1a0808] text-[#EF4444] px-2.5 py-1 rounded-full text-[11px] font-black">
        {status}
      </span>
    );
  return (
    <span className="bg-[#1a1a1a] text-[#888] px-2.5 py-1 rounded-full text-[11px] font-black">
      {status || '—'}
    </span>
  );
}

function StarRating({ rating }: { rating?: number }) {
  const r = Math.round(rating || 0);
  return (
    <span style={{ color: '#F5C518', fontSize: 13 }}>
      {'★'.repeat(r)}
      {'☆'.repeat(5 - r)}
    </span>
  );
}

function formatDate(ts?: number): string {
  if (!ts) return '—';
  return new Date(ts).toLocaleDateString('en-US', {
    year: 'numeric',
    month: 'short',
    day: 'numeric',
  });
}

function getInitials(first?: string, last?: string): string {
  return `${(first || '?')[0]}${(last || '')[0] || ''}`.toUpperCase();
}

export default function AdminBarberDetailPage({ params }: BarberDetailPageProps) {
  const { id } = use(params);
  const router = useRouter();
  const { user } = useAuth();

  const [profile, setProfile] = useState<ProfessionalProfile | null>(null);
  const [userData, setUserData] = useState<UserData | null>(null);
  const [bookings, setBookings] = useState<BookingItem[]>([]);
  const [reviews, setReviews] = useState<ReviewItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [rejectionReason, setRejectionReason] = useState('');
  const [showRejectForm, setShowRejectForm] = useState(false);
  const [saving, setSaving] = useState(false);

  async function loadData() {
    setLoading(true);
    try {
      const [profileSnap, userSnap, bookingsSnap, reviewsSnap] = await Promise.all([
        getDoc(doc(db, 'professionalProfiles', id)),
        getDoc(doc(db, 'users', id)),
        getDocs(
          query(
            collection(db, 'bookings'),
            where('barberId', '==', id),
            orderBy('createdAt', 'desc'),
            limit(5)
          )
        ),
        getDocs(
          query(
            collection(db, 'reviews'),
            where('providerId', '==', id),
            orderBy('createdAt', 'desc'),
            limit(5)
          )
        ),
      ]);

      if (profileSnap.exists()) {
        setProfile(profileSnap.data() as ProfessionalProfile);
      }
      if (userSnap.exists()) {
        setUserData(userSnap.data() as UserData);
      }
      setBookings(
        bookingsSnap.docs.map((d) => ({
          id: d.id,
          ...(d.data() as Omit<BookingItem, 'id'>),
        }))
      );
      setReviews(
        reviewsSnap.docs.map((d) => ({
          id: d.id,
          ...(d.data() as Omit<ReviewItem, 'id'>),
        }))
      );
    } catch (err) {
      console.error('Barber detail fetch error:', err);
    } finally {
      setLoading(false);
    }
  }

  useEffect(() => {
    loadData();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [id]);

  async function handleApprove() {
    if (!user) return;
    setSaving(true);
    try {
      await updateDoc(doc(db, 'professionalProfiles', id), {
        approvalStatus: 'approved',
        isLive: true,
        approvedAt: Date.now(),
        rejectionReason: null,
      });
      await addDoc(collection(db, 'notifications'), {
        userId: id,
        message:
          "🎉 Your titeZMe profile has been approved. You're now live!",
        read: false,
        linkTo: '/dashboard/barber',
        createdAt: Date.now(),
      });
      await addDoc(collection(db, 'adminLogs'), {
        action: 'approved_barber',
        targetId: id,
        adminId: user.uid,
        timestamp: Date.now(),
      });
      toast.success('Barber approved ✓');
      router.push('/admin/barbers');
    } catch (err) {
      console.error('Approve error:', err);
      toast.error('Failed to approve');
    } finally {
      setSaving(false);
    }
  }

  async function handleReject() {
    if (!user || !rejectionReason.trim()) return;
    setSaving(true);
    try {
      await updateDoc(doc(db, 'professionalProfiles', id), {
        approvalStatus: 'rejected',
        isLive: false,
        rejectionReason: rejectionReason.trim(),
        rejectedAt: Date.now(),
      });
      await addDoc(collection(db, 'notifications'), {
        userId: id,
        message: `Your profile wasn't approved. Reason: ${rejectionReason.trim()}. Please update and resubmit.`,
        read: false,
        linkTo: '/dashboard/barber',
        createdAt: Date.now(),
      });
      await addDoc(collection(db, 'adminLogs'), {
        action: 'rejected_barber',
        targetId: id,
        reason: rejectionReason.trim(),
        adminId: user.uid,
        timestamp: Date.now(),
      });
      toast.success('Barber rejected');
      router.push('/admin/barbers');
    } catch (err) {
      console.error('Reject error:', err);
      toast.error('Failed to reject');
    } finally {
      setSaving(false);
    }
  }

  async function handleSuspend() {
    if (!user) return;
    setSaving(true);
    try {
      await updateDoc(doc(db, 'professionalProfiles', id), {
        approvalStatus: 'suspended',
        isLive: false,
        suspendedAt: Date.now(),
      });
      await Promise.all([
        addDoc(collection(db, 'notifications'), {
          userId: id,
          message: 'Your account has been suspended. Contact support.',
          read: false,
          linkTo: '/dashboard/barber',
          createdAt: Date.now(),
        }),
        addDoc(collection(db, 'adminLogs'), {
          action: 'suspended_barber',
          targetId: id,
          adminId: user.uid,
          timestamp: Date.now(),
        }),
      ]);

      // Notify clients with active bookings.
      // Do NOT auto-cancel — suspension may be
      // temporary. Clients are informed and can
      // contact support or wait for reinstatement.
      try {
        const activeBookings = await getDocs(query(
          collection(db, 'bookings'),
          where('barberId', '==', id),
          where('status', 'in', ['pending', 'confirmed'])
        ));

        if (!activeBookings.empty) {
          const notifBatch = writeBatch(db);
          const now = Date.now();

          for (const bookingDoc of activeBookings.docs) {
            notifBatch.set(
              doc(collection(db, 'notifications')),
              {
                userId: bookingDoc.data().clientId,
                message: `Your upcoming booking on ${bookingDoc.data().date} at ${bookingDoc.data().startTime} may be affected. The barber's account has been suspended. Please contact support.`,
                read: false,
                linkTo: '/dashboard/client',
                createdAt: Date.now(),
              }
            );
          }

          await notifBatch.commit();
        }
      } catch (notifErr) {
        // Notification failure must not roll back
        // the suspension itself
        console.error('Failed to notify clients:', notifErr);
      }

      toast.success('Account suspended');
      await loadData();
    } catch (err) {
      console.error('Suspend error:', err);
      toast.error('Failed to suspend');
    } finally {
      setSaving(false);
    }
  }

  async function handleReactivate() {
    if (!user) return;
    setSaving(true);
    try {
      await updateDoc(doc(db, 'professionalProfiles', id), {
        approvalStatus: 'approved',
        isLive: true,
      });
      await Promise.all([
        addDoc(collection(db, 'notifications'), {
          userId: id,
          message: '🎉 Your titeZMe account has been reactivated. You are now live again!',
          read: false,
          linkTo: '/dashboard/barber',
          createdAt: Date.now(),
        }),
        addDoc(collection(db, 'adminLogs'), {
          action: 'reactivated_barber',
          targetId: id,
          adminId: user.uid,
          timestamp: Date.now(),
        }),
      ]);
      toast.success('Account reactivated');
      await loadData();
    } catch (err) {
      console.error('Reactivate error:', err);
      toast.error('Failed to reactivate');
    } finally {
      setSaving(false);
