function formatDate(ts?: number): string {
  if (!ts) return '—';
  return new Date(ts).toLocaleDateString('en-US', { year: 'numeric', month: 'short', day: 'numeric' });
}

function getTodayStr(): string {
  return new Date().toISOString().split('T')[0];
}

function getMondayStr(): string {
  const d = new Date();
  const day = d.getDay();
  const diff = d.getDate() - day + (day === 0 ? -6 : 1);
  d.setDate(diff);
  return d.toISOString().split('T')[0];
}

function getMonthStartStr(): string {
  const d = new Date();
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-01`;
}

function isToday(dateStr?: string): boolean {
  if (!dateStr) return false;
  return dateStr === getTodayStr();
}

function isThisWeek(dateStr?: string): boolean {
  if (!dateStr) return false;
  const today = getTodayStr();
  const monday = getMondayStr();
  return dateStr >= monday && dateStr <= today;
}

function isThisMonth(dateStr?: string): boolean {
  if (!dateStr) return false;
  const today = getTodayStr();
  const monthStart = getMonthStartStr();
  return dateStr >= monthStart && dateStr <= today;
}

function StatusBadge({ status }: { status?: string }) {
  const s = (status || '').toLowerCase();
  if (s === 'confirmed')
    return <span className="bg-[#0f2010] text-[#22C55E] px-2.5 py-1 rounded-full text-[11px] font-black">Confirmed</span>;
  if (s === 'completed')
    return <span className="bg-[#0a1a0a] text-[#22C55E] px-2.5 py-1 rounded-full text-[11px] font-black">Completed</span>;
  if (s === 'pending')
    return <span className="bg-[#1a1500] text-[#F5C518] px-2.5 py-1 rounded-full text-[11px] font-black">Pending</span>;
  if (s === 'cancelled')
    return <span className="bg-[#1a0808] text-[#EF4444] px-2.5 py-1 rounded-full text-[11px] font-black">Cancelled</span>;
  return <span className="bg-[#1a1a1a] text-[#888] px-2.5 py-1 rounded-full text-[11px] font-black">{status || '—'}</span>;
}

function StatCard({ label, value }: { label: string; value: number }) {
  return (
    <div className="bg-[#111] border border-[#1e1e1e] rounded-2xl" style={{ padding: '16px 20px', flex: 1, minWidth: 140 }}>
      <div style={{ fontSize: 11, color: '#555', fontWeight: 700, textTransform: 'uppercase', letterSpacing: 0.5, marginBottom: 6 }}>
        {label}
      </div>
      <div style={{ fontSize: 28, fontWeight: 900, color: '#fff' }}>{value}</div>
    </div>
  );
}

export default function AdminBookingsPage() {
  const [bookings, setBookings] = useState<BookingRow[]>([]);
  const [loading, setLoading] = useState(true);
  const [statusFilter, setStatusFilter] = useState<StatusFilter>('all');
  const [timeFilter, setTimeFilter] = useState<TimeFilter>('all');
  const [search, setSearch] = useState('');
  const [page, setPage] = useState(1);
  const [cancelConfirmId, setCancelConfirmId] = useState<string | null>(null);
  const [cancelling, setCancelling] = useState(false);

  const debouncedSearch = useDebounce(search, 300);

  useEffect(() => {
    setLoading(true);

    // Real-time listener — new bookings appear immediately without refresh
    const unsub = onSnapshot(
      query(collection(db, 'bookings'), orderBy('createdAt', 'desc'), limit(FETCH_LIMIT)),
      async (snap) => {
        const rawBookings: BookingRow[] = snap.docs.map((d) => ({
          id: d.id,
          ...(d.data() as Omit<BookingRow, 'id'>),
        }));

        // Collect unique user IDs for name enrichment
        const userIds = new Set<string>();
        rawBookings.forEach((b) => {
          if (b.clientId) userIds.add(b.clientId);
          if (b.barberId) userIds.add(b.barberId);
        });

        const userMap: Record<string, string> = {};
        await Promise.all(
          Array.from(userIds).map(async (uid) => {
            try {
              const userSnap = await getDoc(doc(db, 'users', uid));
              if (userSnap.exists()) {
                const u = userSnap.data() as Record<string, unknown>;
                userMap[uid] = `${u.firstName || ''} ${u.lastName || ''}`.trim() || uid;
              }
            } catch { /* skip */ }
          })
        );

        const enriched = rawBookings.map((b) => ({
          ...b,
          clientName: b.clientId ? (userMap[b.clientId] || b.clientName || b.clientId) : '—',
          barberName: b.barberId ? (userMap[b.barberId] || b.barberName || b.barberId) : '—',
        }));

        setBookings(enriched);
        setLoading(false);
      },
      (err) => {
        console.error('Admin bookings listener error:', err);
        setLoading(false);
      }
    );

    return () => unsub();
  }, []);

  const filtered = useMemo(() => {
    let list = bookings;

    if (statusFilter !== 'all') {
      list = list.filter((b) => (b.status || '').toLowerCase() === statusFilter);
    }

    if (timeFilter === 'today') list = list.filter((b) => isToday(b.date));
    else if (timeFilter === 'week') list = list.filter((b) => isThisWeek(b.date));
    else if (timeFilter === 'month') list = list.filter((b) => isThisMonth(b.date));

    if (debouncedSearch.trim()) {
      const q = debouncedSearch.toLowerCase();
      list = list.filter((b) => {
        const client = (b.clientName || '').toLowerCase();
        const barber = (b.barberName || '').toLowerCase();
        const service = (b.serviceNames?.[0] || '').toLowerCase();
        return client.includes(q) || barber.includes(q) || service.includes(q);
      });
    }

    return list;
  }, [bookings, statusFilter, timeFilter, debouncedSearch]);

  const stats = useMemo(() => ({
    today: bookings.filter((b) => isToday(b.date)).length,
    week: bookings.filter((b) => isThisWeek(b.date)).length,
    month: bookings.filter((b) => isThisMonth(b.date)).length,
    total: bookings.length,
  }), [bookings]);

  const totalPages = Math.ceil(filtered.length / PER_PAGE);
  const paginated = filtered.slice((page - 1) * PER_PAGE, page * PER_PAGE);

  async function handleCancel(bookingId: string) {
    setCancelling(true);
    try {
      const booking = bookings.find((b) => b.id === bookingId);

      await updateDoc(doc(db, 'bookings', bookingId), {
        status: 'cancelled',
        updatedAt: Date.now(),
      });

      // Notify both client and barber
      const notifTime = booking?.date && booking?.startTime
        ? `on ${booking.date} at ${booking.startTime}`
        : booking?.date
        ? `on ${booking.date}`
        : '';

      const notifPromises: Promise<unknown>[] = [];

      if (booking?.clientId) {
        notifPromises.push(
          addDoc(collection(db, 'notifications'), {
            userId: booking.clientId,
            message: `Your booking ${notifTime} was cancelled by admin.`,
            read: false,
            linkTo: '/dashboard/client',
            createdAt: Date.now(),
          })
        );
      }

      if (booking?.barberId) {
        notifPromises.push(
          addDoc(collection(db, 'notifications'), {
            userId: booking.barberId,
            message: `A booking ${notifTime} was cancelled by admin.`,
            read: false,
            linkTo: '/dashboard/barber',
            createdAt: Date.now(),
          })
        );
      }

      await Promise.all(notifPromises);

      setBookings((prev) =>
        prev.map((b) => (b.id === bookingId ? { ...b, status: 'cancelled' } : b))
      );
      toast.success('Booking cancelled');
    } catch (err) {
      console.error('Cancel error:', err);
      toast.error('Failed to cancel booking');
    } finally {
      setCancelling(false);
      setCancelConfirmId(null);
    }
  }

  function exportCSV() {
    const headers = ['ID', 'Client', 'Barber', 'Service', 'Date', 'Time', 'Price', 'Status', 'Created'];
    const rows = filtered.map((b) => [
      b.id,
      b.clientName || '',
      b.barberName || '',
      b.serviceNames?.[0] || '',
      b.date || '',
      b.startTime || '',
      b.totalPrice !== undefined ? `${b.totalPrice}` : '',
      b.status || '',
      b.createdAt ? new Date(b.createdAt).toISOString() : '',
    ]);
    const csv = [headers, ...rows].map((r) => r.map((c) => `"${String(c).replace(/"/g, '""')}"`).join(',')).join('\n');
    const blob = new Blob([csv], { type: 'text/csv' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `bookings-${Date.now()}.csv`;
    a.click();
    URL.revokeObjectURL(url);
  }

