        </div>

        {/* Time filter */}
        <select
          value={timeFilter}
          onChange={(e) => { setTimeFilter(e.target.value as TimeFilter); setPage(1); }}
          style={{
            background: '#111',
            border: '1px solid #1e1e1e',
            borderRadius: 8,
            padding: '7px 12px',
            fontSize: 12,
            color: '#888',
            outline: 'none',
