                      style={{
                        background: 'none',
                        border: '1px solid #2a2a2a',
                        borderRadius: 8,
                        padding: '6px 12px',
                        fontSize: 12,
                        fontWeight: 700,
                        color: '#555',
                        cursor: 'pointer',
                      }}
                    >
                      Keep
                    </button>
                    <button
                      onClick={() => handleCancel(b.id)}
                      disabled={cancelling}
                      style={{
                        background: '#EF4444',
                        border: 'none',
                        borderRadius: 8,
                        padding: '6px 14px',
                        fontSize: 12,
                        fontWeight: 800,
                        color: '#fff',
                        cursor: cancelling ? 'not-allowed' : 'pointer',
                        opacity: cancelling ? 0.6 : 1,
                      }}
                    >
                      Confirm Cancel
                    </button>
                  </div>
                )}
              </div>
            );
          })}
        </div>
      )}

      {/* Pagination */}
      {totalPages > 1 && (
        <div style={{ display: 'flex', alignItems: 'center', gap: 12, marginTop: 20 }}>
          <button
            onClick={() => setPage((p) => Math.max(1, p - 1))}
            disabled={page === 1}
            style={{
              background: '#111',
              border: '1px solid #1e1e1e',
              borderRadius: 8,
              padding: '7px 14px',
              fontSize: 13,
              fontWeight: 700,
              color: page === 1 ? '#444' : '#fff',
              cursor: page === 1 ? 'not-allowed' : 'pointer',
            }}
          >
            ← Previous
          </button>
          <span style={{ fontSize: 13, color: '#555' }}>Page {page} of {totalPages}</span>
          <button
            onClick={() => setPage((p) => Math.min(totalPages, p + 1))}
            disabled={page === totalPages}
            style={{
              background: '#111',
              border: '1px solid #1e1e1e',
              borderRadius: 8,
              padding: '7px 14px',
              fontSize: 13,
              fontWeight: 700,
              color: page === totalPages ? '#444' : '#fff',
              cursor: page === totalPages ? 'not-allowed' : 'pointer',
            }}
          >
            Next →
          </button>
        </div>
      )}
    </div>
  );
}

async function handleCancel(bookingId: string) {
    setCancelling(true);
    try {
      const booking = bookings.find((b) => b.id === bookingId);

      await updateDoc(doc(db, 'bookings', bookingId), {
        status: 'cancelled',
        updatedAt: Date.now(),
      });

      // Notify both client and barber
      const notifTime = booking?.date && booking?.startTime
        ? `on ${booking.date} at ${booking.startTime}`
        : booking?.date
        ? `on ${booking.date}`
        : '';

      const notifPromises: Promise<unknown>[] = [];

      if (booking?.clientId) {
        notifPromises.push(
          addDoc(collection(db, 'notifications'), {
            userId: booking.clientId,
            message: `Your booking ${notifTime} was cancelled by admin.`,
            read: false,
            linkTo: '/dashboard/client',
            createdAt: Date.now(),
          })
        );
      }

      if (booking?.barberId) {
        notifPromises.push(
          addDoc(collection(db, 'notifications'), {
            userId: booking.barberId,
            message: `A booking ${notifTime} was cancelled by admin.`,
            read: false,
            linkTo: '/dashboard/barber',
            createdAt: Date.now(),
          })
        );
      }

      await Promise.all(notifPromises);

      setBookings((prev) =>
        prev.map((b) => (b.id === bookingId ? { ...b, status: 'cancelled' } : b))
      );
      toast.success('Booking cancelled');
    } catch (err) {
      console.error('Cancel error:', err);
      toast.error('Failed to cancel booking');
    } finally {
      setCancelling(false);
      setCancelConfirmId(null);
    }
  }

function exportCSV() {
    const headers = ['ID', 'Client', 'Barber', 'Service', 'Date', 'Time', 'Price', 'Status', 'Created'];
    const rows = filtered.map((b) => [
      b.id,
      b.clientName || '',
      b.barberName || '',
      b.serviceNames?.[0] || '',
      b.date || '',
      b.startTime || '',
      b.totalPrice !== undefined ? `${b.totalPrice}` : '',
      b.status || '',
      b.createdAt ? new Date(b.createdAt).toISOString() : '',
    ]);
    const csv = [headers, ...rows].map((r) => r.map((c) => `"${String(c).replace(/"/g, '""')}"`).join(',')).join('\n');
    const blob = new Blob([csv], { type: 'text/csv' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `bookings-${Date.now()}.csv`;
    a.click();
    URL.revokeObjectURL(url);
  }

