      };
    });
  }

async function checkExpiry(currentBarbers: FeaturedBarber[], currentShops: FeaturedShop[]) {
    const now = Date.now();
    const expiredBarbers = currentBarbers.filter((b) => b.featuredUntil && b.featuredUntil < now);
    const expiredShops = currentShops.filter((s) => s.featuredUntil && s.featuredUntil < now);
    if (expiredBarbers.length === 0 && expiredShops.length === 0) return;

    const batch = writeBatch(db);
    expiredBarbers.forEach((b) => {
      batch.update(doc(db, 'professionalProfiles', b.id), { isFeatured: false, featuredUntil: null });
    });
    expiredShops.forEach((s) => {
      batch.update(doc(db, 'businesses', s.id), { isFeatured: false, featuredUntil: null });
    });
    await batch.commit();

    const totalExpired = expiredBarbers.length + expiredShops.length;
    toast.success(`${totalExpired} expired featured spot${totalExpired !== 1 ? 's' : ''} removed`);

    // Refresh lists to remove expired entries
    const [freshBarbers, freshShops] = await Promise.all([
      loadFeaturedBarbers(),
      loadFeaturedShops(),
    ]);
    setFeaturedBarbers(freshBarbers);
    setFeaturedShops(freshShops);
  }

async function loadAll() {
      setLoading(true);
      try {
        const [fb, allBarbersSnap, fs, allShopsSnap] = await Promise.all([
          loadFeaturedBarbers(),
          getDocs(query(collection(db, 'professionalProfiles'), where('isLive', '==', true))),
          loadFeaturedShops(),
          getDocs(query(collection(db, 'businesses'), where('status', '==', 'active'))),
        ]);

        setFeaturedBarbers(fb);
        setFeaturedShops(fs);

        // Auto-remove any entries whose featuredUntil has passed
        await checkExpiry(fb, fs);

        // Enrich all live barbers with user names
        const allB: FeaturedBarber[] = await Promise.all(
          allBarbersSnap.docs.map(async (d) => {
            const data = d.data() as Record<string, unknown>;
            let firstName: string | undefined;
            let lastName: string | undefined;
            try {
              const userSnap = await getDoc(doc(db, 'users', d.id));
              if (userSnap.exists()) {
                const u = userSnap.data() as Record<string, unknown>;
                firstName = u.firstName as string | undefined;
                lastName = u.lastName as string | undefined;
              }
            } catch {
              // skip
            }
            return {
              id: d.id,
              firstName,
              lastName,
              profilePhotoUrl: data.profilePhotoUrl as string | undefined,
              city: data.city as string | undefined,
              isFeatured: Boolean(data.isFeatured),
            };
          })
        );
        setAllBarbers(allB);

        const allS: FeaturedShop[] = allShopsSnap.docs.map((d) => {
          const data = d.data() as Record<string, unknown>;
          return {
            id: d.id,
            name: data.name as string | undefined,
            coverPhotoUrl: data.coverPhotoUrl as string | undefined,
            city: data.city as string | undefined,
            isFeatured: Boolean(data.isFeatured),
          };
        });
        setAllShops(allS);
      } catch (err) {
        console.error('Featured load error:', err);
      } finally {
        setLoading(false);
      }
    }

