async function migrateApprovalStatus() {
  const FLAG = 'tzm_migrated_approval_status_v1';
  if (typeof window !== 'undefined' && localStorage.getItem(FLAG)) return;
  try {
    const snap = await getDocs(collection(db, 'professionalProfiles'));
    const batch = writeBatch(db);
    let count = 0;
    snap.docs.forEach((d) => {
      const data = d.data();
      if (!data.approvalStatus) {
        // Live barbers are already approved; offline ones need review
        const status = data.isLive ? 'approved' : 'pending';
        batch.update(doc(db, 'professionalProfiles', d.id), { approvalStatus: status });
        count++;
      }
    });
    if (count > 0) await batch.commit();
    if (typeof window !== 'undefined') localStorage.setItem(FLAG, 'true');
  } catch (err) {
    console.error('Migration migrateApprovalStatus failed:', err);
    // Non-critical — don't block dashboard load
  }
}

function StatusBadge({ status }: { status?: string }) {
  if (!status) return null;
  const s = status.toLowerCase();
  if (s === 'confirmed' || s === 'completed')
    return (
      <span className="bg-[#0f2010] text-[#22C55E] px-2.5 py-1 rounded-full text-[11px] font-black">
        {status}
      </span>
    );
  if (s === 'pending')
    return (
      <span className="bg-[#1a1500] text-[#F5C518] px-2.5 py-1 rounded-full text-[11px] font-black">
        {status}
      </span>
    );
  if (s === 'cancelled' || s === 'rejected')
    return (
      <span className="bg-[#1a0808] text-[#EF4444] px-2.5 py-1 rounded-full text-[11px] font-black">
        {status}
      </span>
    );
  return (
    <span className="bg-[#1a1a1a] text-[#888] px-2.5 py-1 rounded-full text-[11px] font-black">
      {status}
    </span>
  );
}

function formatDateNice(dateStr: string): string {
  try {
    const [year, month, day] = dateStr.split('-').map(Number);
    const d = new Date(year, month - 1, day);
    return d.toLocaleDateString('en-US', {
      weekday: 'long',
      year: 'numeric',
      month: 'long',
      day: 'numeric',
    });
  } catch {
    return dateStr;
  }
}

