export default function BarberProfileLayout({ children }: { children: ReactNode }) {
  return (
    <ErrorBoundary>
      {children}
    </ErrorBoundary>
  );
}

export async function generateStaticParams() {
  try {
    const snap = await adminDb
      .collection('professionalProfiles')
      .where('isLive', '==', true)
      .orderBy('rating', 'desc')
      .limit(20)
      .get();
    return snap.docs.map(doc => ({ barberId: doc.id }));
  } catch {
    return [];
  }
}

export async function generateMetadata({
  params,
}: {
  params: Promise<{ barberId: string }>;
}) {
  try {
    const { barberId } = await params;
    const [profileDoc, userDoc] = await Promise.all([
      adminDb.collection('professionalProfiles').doc(barberId).get(),
      adminDb.collection('users').doc(barberId).get(),
    ]);

    if (!profileDoc.exists) return { title: 'Barber not found' };

    const p = profileDoc.data() || {};
    const u = userDoc.data() || {};
    const name = `${(p as any).firstName || (u as any).firstName || ''} ${(p as any).lastName || (u as any).lastName || ''}`.trim() || 'Barber';
    const city = (u as any).city || '';
    const spec = ((p as any).specialties || [])[0] || 'Barber';

    return {
      title: name,
      description: `Book ${name} in ${city}. ${spec}. Real availability. Book instantly on titeZMe.`,
      openGraph: {
        title: `${name} — titeZMe`,
        description: `Book ${name} in ${city}. ${spec}.`,
        images: (p as any).profilePhotoUrl ? [(p as any).profilePhotoUrl] : ['/wordmark.png'],
      },
    };
  } catch {
    return { title: 'Barber Profile' };
  }
}

export default async function BarberProfilePage({
  params,
}: {
  params: Promise<{ barberId: string }>;
}) {
  const { barberId } = await params;

  if (barberId.startsWith('fake_')) {
    const { fakeBarbersUI } = await import('@/lib/fakeUIData');
    const fake = fakeBarbersUI.find(f => f.userId === barberId);
    if (!fake) notFound();

    const initialData: BarberProfileInitialData = {
      profile: {
        id: barberId,
        userId: barberId,
        isFake: true,
        firstName: fake.firstName,
        lastName: fake.lastName,
        bio: fake.bio,
        city: fake.city,
        country: fake.country,
        languages: fake.languages,
        specialties: fake.specialties,
        rating: fake.rating,
        reviewCount: fake.reviewCount,
        totalReviews: fake.reviewCount,
        totalCuts: fake.totalCuts,
        currency: fake.currency,
        photoUrl: fake.photoUrl,
        profilePhotoUrl: fake.profilePhotoUrl,
        experienceStartYear: fake.experienceStartYear,
        isLive: true,
        isSolo: true,
        isOnboarded: true,
        approvalStatus: 'approved',
        location: fake.location,
        createdAt: fake.createdAt,
      } as any,
      userProfile: {
        uid: barberId,
        firstName: fake.firstName,
        lastName: fake.lastName,
        photoUrl: fake.photoUrl,
        city: fake.city,
        country: fake.country,
      } as any,
      shop: null,
      services: fake.services.map((s, i) => ({
        id: `${fake.userId}_service_${i}`,
        name: s.name,
        price: s.price,
        durationMinutes: s.duration,
        isActive: true,
        providerId: barberId,
        providerType: 'barber',
      })) as any[],
      reviews: fake.reviews.map((r, i) => ({
        id: `${fake.userId}_review_${i}`,
        rating: r.rating,
        comment: r.comment,
        clientName: r.clientName,
        createdAt: r.createdAt,
        providerId: barberId,
      })) as any[],
      schedule: {
        availableSlots: {},
        weeklyHours: fake.weeklyHours,
      } as any,
    };

    return <BarberProfileClient barberId={barberId} initialData={initialData} />;
  }

  try {
    const [profileDoc, userDoc, scheduleDoc] = await Promise.all([
      adminDb.collection('professionalProfiles').doc(barberId).get(),
      adminDb.collection('users').doc(barberId).get(),
      adminDb.collection('schedules').doc(getScheduleDocId(barberId)).get(),
    ]);

    if (!profileDoc.exists) {
      notFound();
    }

    const profileData = profileDoc.data() || {};
    const userData = userDoc.exists ? userDoc.data() || {} : {};
    const pData = profileData as any;
    const uData = userData as any;

    // Heal: if professionalProfiles is missing public display fields, copy them
    // from users doc automatically. Fixes existing barbers who completed
    // onboarding before the security migration.
    if (!pData.firstName && uData.firstName) {
      const healData: Record<string, any> = {};
      if (!pData.firstName && uData.firstName) healData.firstName = uData.firstName;
      if (!pData.lastName  && uData.lastName)  healData.lastName  = uData.lastName;
      if (!pData.photoUrl  && uData.photoUrl)  healData.photoUrl  = uData.photoUrl;
      if (!pData.createdAt && uData.createdAt) healData.createdAt = uData.createdAt;
      if (!pData.city      && uData.city)      healData.city      = uData.city;
      if (!pData.country   && uData.country)   healData.country   = uData.country;

      if (Object.keys(healData).length > 0) {
        try {
          await adminDb
            .collection('professionalProfiles')
            .doc(barberId)
            .update(healData);
          Object.assign(pData, healData);
          console.log('[heal] professionalProfiles healed for:', barberId, healData);
        } catch (healErr) {
          console.error('[heal] FAILED for:', barberId, healErr);
          // Apply in memory even if Firestore write failed so the name
          // shows correctly on this page load regardless.
          Object.assign(pData, healData);
        }
      }
    }

    const mergedUserProfile = {
      ...userData,
      firstName: pData.firstName || uData.firstName,
      lastName: pData.lastName || uData.lastName,
    };

    // Fetch shop if barber belongs to one
    let shopData: any = null;
    if ((profileData as any).businessId) {
      const shopDoc = await adminDb.collection('businesses').doc((profileData as any).businessId).get();
      if (shopDoc.exists) shopData = { id: shopDoc.id, ...shopDoc.data() };
    }

    // Fetch services + reviews in parallel
    const [servicesSnap, reviewsSnap] = await Promise.all([
      adminDb.collection('services')
        .where('providerId', '==', barberId)
        .where('isActive', '==', true)
        .get(),
      adminDb.collection('reviews')
        .where('providerId', '==', barberId)
        .orderBy('createdAt', 'desc')
        .limit(20)
        .get(),
    ]);

    const services = servicesSnap.docs.map(d => ({ id: d.id, ...d.data() }));

    // Enrich reviews with client names server-side
    const reviews = await Promise.all(
      reviewsSnap.docs.map(async d => {
        const rev: any = { id: d.id, ...d.data() };
        if (rev.clientId) {
          try {
            const clientDoc = await adminDb.collection('users').doc(rev.clientId).get();
            if (clientDoc.exists) rev.user = clientDoc.data();
          } catch {
            // Non-critical
          }
        }
        return rev;
      })
    );

    const scheduleData = scheduleDoc.exists
      ? (scheduleDoc.data() as { availableSlots?: Record<string, string[]> })
      : null;

    const initialData: BarberProfileInitialData = {
      profile: { id: barberId, ...profileData } as any,
      userProfile: mergedUserProfile as any,
      shop: shopData,
      services: services as any[],
      reviews: reviews as any[],
      schedule: scheduleData,
    };

    return <BarberProfileClient barberId={barberId} initialData={initialData} />;
  } catch (err) {
    console.error('BarberProfilePage server error:', err);
    // Fall back to client-side fetching on error
    return <BarberProfileClient barberId={barberId} />;
  }
}

function computeOpenStatus(
  weeklyDays: string[],
  opensAt: string,
  closesAt: string
) {
  if (!weeklyDays || weeklyDays.length === 0) {
    return {
      isOpenNow:   false,
      openColor:   '',
      hasSchedule: false,
    };
  }
  const now = new Date();
  const dayName = now.toLocaleDateString(
    'en-US', { weekday: 'short' }
  );
  const currentTime = [
    now.getHours().toString().padStart(2, '0'),
    now.getMinutes().toString().padStart(2, '0'),
  ].join(':');
  const isOpenNow =
    weeklyDays.includes(dayName) &&
    currentTime >= (opensAt  || '00:00') &&
    currentTime <= (closesAt || '23:59');
  return {
    isOpenNow,
    openColor:   isOpenNow ? 'green' : 'gray',
    hasSchedule: true,
  };
}

async function fetchBarbers(): Promise<BarberCardItem[]> {
  const [response, featuredSnap] = await Promise.all([
    algoliaClient.search({
      requests: [{
        indexName: 'professionals',
        query:     '',
        filters:
          'isLive:true AND ' +
          'approvalStatus:approved AND ' +
          'isSolo:true',
        hitsPerPage: 1000,
      }],
    }),
    getDocs(firestoreQuery(
      collection(db, 'professionalProfiles'),
      where('isFeatured', '==', true),
      limit(50),
    )),
  ]);

  const featuredIds = new Set<string>(featuredSnap.docs.map(d => d.id));

  const hits =
    ((response.results[0] as any).hits as any[])
      .filter((hit: any) => hit.isFake !== true || hit.isVisible !== false);

  return hits.map((hit: any) => ({
    id:             hit.objectID,
    firstName:      hit.firstName      || '',
    lastName:       hit.lastName       || '',
    profilePhotoUrl: hit.photoUrl      || '',
    photoUrl:       hit.photoUrl       || '',
    city:           hit.city           || '',
    country:        hit.country        || '',
    state:          hit.state          || '',
    languages:      hit.languages      || [],
    vibes:          hit.vibes          || [],
    currency:       hit.currency       || 'EUR',
    barberCode:     hit.professionalCode || '',
    street:         '',
    minPrice:       hit.minPrice       || 0,
    isFeatured:     featuredIds.has(hit.objectID),
    ...computeOpenStatus(
      hit.weeklyDays || [],
      hit.opensAt    || '09:00',
      hit.closesAt   || '18:00'
    ),
  }));
}

function fisherYates<T>(arr: T[]): T[] {
  const a = [...arr];
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}

function currencySymbol(c?: string): string {
  switch ((c ?? '').toUpperCase()) {
    case 'GBP': return '£';
    case 'USD': return '$';
    case 'MAD': return 'MAD ';
    default: return '€';
  }
}

function Pagination({ page, total, onChange }: {
  page: number; total: number; onChange: (p: number) => void;
}) {
  const { t } = useLang();
  const totalPages = Math.ceil(total / PER_PAGE);
  if (totalPages <= 1) return null;
  let start = Math.max(1, page - 2);
  const end = Math.min(totalPages, start + 4);
  if (end - start < 4) start = Math.max(1, end - 4);
  const pages = Array.from({ length: end - start + 1 }, (_, i) => start + i);

  return (
    <div className="flex items-center justify-center gap-1 mt-10">
      <button onClick={() => onChange(page - 1)} disabled={page === 1}
        className="px-3 py-2 text-sm font-bold text-[#888] hover:text-white disabled:opacity-30 disabled:cursor-not-allowed transition-colors">
        {t('buttons.prev')}
      </button>
      {start > 1 && <>
        <button onClick={() => onChange(1)} className="w-11 h-11 rounded-lg text-sm font-bold text-[#888] hover:text-white">1</button>
        {start > 2 && <span className="text-[#555]">…</span>}
      </>}
      {pages.map(p => (
        <button key={p} onClick={() => onChange(p)}
          className={`w-11 h-11 rounded-lg text-sm font-bold transition-colors ${p === page ? 'bg-brand-yellow text-[#0a0a0a]' : 'text-[#888] hover:text-white'}`}>
          {p}
        </button>
      ))}
      {end < totalPages && <>
        {end < totalPages - 1 && <span className="text-[#555]">…</span>}
        <button onClick={() => onChange(totalPages)} className="w-11 h-11 rounded-lg text-sm font-bold text-[#888] hover:text-white">{totalPages}</button>
      </>}
      <button onClick={() => onChange(page + 1)} disabled={page === totalPages}
        className="px-3 py-2 text-sm font-bold text-[#888] hover:text-white disabled:opacity-30 disabled:cursor-not-allowed transition-colors">
        {t('buttons.next')}
      </button>
    </div>
  );
}

export default function BarbersClient({ initialBarbers }: BarbersClientProps = {}) {
  const router = useRouter();
  const { user, authLoading } = useAuth();
  const shouldBlur = !authLoading && !user;
  const showFakes = useShowFakeUIData();
  const [countryCode, setCountryCode] = useState('');
  const [countryName, setCountryName] = useState('');
  const [selectedState, setSelectedState] = useState('');
  const [selectedCity, setSelectedCity] = useState('');
  // country = ISO code (e.g. "ES") to match barberProfiles storage format.
  // countryDisplay = full name for the UI badge (e.g. "Spain").
  const [activeFilter, setActiveFilter] = useState<{ city: string; state: string; country: string; countryDisplay?: string } | null>(null);
  const [geoCity, setGeoCity] = useState('');
  const [geoCountry, setGeoCountry] = useState('');
  const [geoApplied, setGeoApplied] = useState(false);
  const [csc, setCsc] = useState<any>(null);

  useEffect(() => { import('country-state-city').then(m => setCsc(m)); }, []);

  // Auto-detect user location and pre-populate filters
  useEffect(() => {
    if (!navigator.geolocation) return;
    navigator.geolocation.getCurrentPosition(
      async (position) => {
        const { latitude, longitude } = position.coords;
        try {
          const res = await fetch(
            `https://nominatim.openstreetmap.org/reverse?format=json&lat=${latitude}&lon=${longitude}`,
            { headers: { 'Accept-Language': 'en' } }
          );
          const data = await res.json();
          const city =
            data.address?.city ||
            data.address?.town ||
            data.address?.village ||
            data.address?.county || '';
          const country = data.address?.country || '';
          if (city && country) {
            setGeoCity(city);
            setGeoCountry(country);
            // Only auto-apply if user hasn't already set filters manually
            const { Country: CountryLib } = await import('country-state-city');
            const found = CountryLib.getAllCountries().find(
              (c: any) => c.name.toLowerCase() === country.toLowerCase()
            );
            if (found) {
              setCountryCode(found.isoCode);
              setCountryName(found.name);
              setSelectedCity(city);
              // Use ISO code for filter (matches barberProfiles.country format)
              setActiveFilter({ city, state: '', country: found.isoCode, countryDisplay: found.name });
              setGeoApplied(true);
            }
          }
        } catch {
          // Silent fail — geolocation reverse-geocode is best-effort
        }
      },
      () => { /* User denied or unavailable — silent fail */ },
      { timeout: 5000, maximumAge: 300000 }
    );
  }, []);

  // Use server-provided initialBarbers if available, otherwise fetch client-side.
  const { data: allBarbers = [], isLoading } = useQuery({
    queryKey: ['barbersListV2'],
    queryFn: fetchBarbers,
    // If server already supplied barbers, use them as initial data (no fetch on load).
    // If server returned empty (e.g. Admin SDK not configured), fetch client-side.
    initialData: initialBarbers && initialBarbers.length > 0 ? initialBarbers : undefined,
    staleTime: 5 * 60 * 1000,
    refetchOnWindowFocus: false,
    refetchOnMount: false,
  });
  const [nameSearch, setNameSearch] = useState('');
  const debouncedNameSearch = useDebounce(nameSearch, 300);
  const [page, setPage] = useState(1);
  const [copied, setCopied] = useState(false);
  const { t } = useLang();

  const countries = useMemo(() => csc ? csc.Country.getAllCountries() : [], [csc]);
  const states = useMemo(() => {
    if (!csc || !countryCode) return [];
    return csc.State.getStatesOfCountry(countryCode) ?? [];
  }, [csc, countryCode]);
  const cities = useMemo(() => {
    if (!csc || !countryCode) return [];
    return csc.City.getCitiesOfCountry(countryCode) ?? [];
  }, [csc, countryCode]);

  const mergedList = useMemo<BarberCardItem[]>(() => {
    const realBarbers = allBarbers;
    const TARGET_TOTAL = 100;
    const visibleFakeCount = showFakes
      ? Math.max(0, TARGET_TOTAL - realBarbers.length)
      : 0;
    const fakesAsCards: BarberCardItem[] = fakeBarbersUI
      .slice(0, visibleFakeCount)
      .map(fakeToBarberCard);
    return [...realBarbers, ...fakesAsCards];
  }, [allBarbers, showFakes]);

  const filtered = useMemo(() => {
    let list = [...mergedList];

    if (activeFilter) {
      list = list.filter(b => {
        // City: skip city filter when not selected; bi-directional partial match otherwise
        const cityMatch = !activeFilter.city || locationsMatch(b.city, activeFilter.city);
        // Country: exact ISO-code comparison ("ES" === "ES")
        const countryMatch =
          !activeFilter.country ||
          b.country.toLowerCase() === activeFilter.country.toLowerCase();
        // State/Region: exact ISO-code comparison ("CT" === "CT") — controlled list, not free text
        const stateMatch =
          !activeFilter.state ||
          (b.state || '').toLowerCase() === activeFilter.state.toLowerCase();
        return cityMatch && countryMatch && stateMatch;
      });
    }

    if (debouncedNameSearch.trim()) {
      const q = debouncedNameSearch.trim().toLowerCase();
      list = list.filter(b =>
        `${b.firstName} ${b.lastName}`.toLowerCase().includes(q) ||
        b.barberCode.toLowerCase().includes(q)
      );
    }

    const featured = list.filter(b => b.isFeatured);
    const nonFeatured = list.filter(b => !b.isFeatured);
    const openNow = fisherYates(nonFeatured.filter(b => b.isOpenNow));
    const closed = fisherYates(nonFeatured.filter(b => !b.isOpenNow));
    return [...featured, ...openNow, ...closed];
  }, [mergedList, activeFilter, debouncedNameSearch]);

  const paged = filtered.slice((page - 1) * PER_PAGE, page * PER_PAGE);

  const handleSearch = () => {
    setActiveFilter(
      countryCode || selectedState || selectedCity
        ? { city: selectedCity, state: selectedState, country: countryCode, countryDisplay: countryName }
        : null
    );
    setPage(1);
  };

  const clearAll = () => {
    setActiveFilter(null);
    setSelectedCity('');
    setSelectedState('');
    setCountryCode('');
    setCountryName('');
    setNameSearch('');
    setGeoApplied(false);
    setPage(1);
  };

  const handleShare = () => {
    navigator.clipboard.writeText(window.location.href);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  return (
    <div className="bg-[#0a0a0a] text-white min-h-screen">

      <div className="max-w-[1400px] mx-auto px-6 pt-12 pb-8">
        <h1 className="text-4xl md:text-5xl font-black mb-2">{t('forms.findYourBarber')}</h1>
        <p className="text-[#888] font-bold text-lg mb-4">
          {t('forms.browseBarbersCity')}
        </p>

        {/* Geolocation banner */}
        {geoApplied && geoCity && (
          <div className="flex items-center gap-2 mb-5 bg-[#111] border border-[#1e1e1e] rounded-full px-4 py-2 w-fit text-sm font-bold text-[#888]">
            <span>📍</span>
            <span>{t('status.showingNear')} <span className="text-white">{geoCity}</span></span>
            <button
              onClick={clearAll}
              className="ml-1 text-[#555] hover:text-white transition-colors text-xs"
            >
              {t('status.changeLocation')}
            </button>
          </div>
        )}

        <div className="flex flex-col gap-3 mb-4">
          <div className="flex flex-col sm:flex-row gap-3">
            <select value={countryCode} onChange={e => {
              const c = countries.find((c: any) => c.isoCode === e.target.value);
              setCountryCode(e.target.value);
              setCountryName(c?.name || '');
              setSelectedState('');
              setSelectedCity('');
            }}
              className="flex-1 bg-[#111] border border-[#2a2a2a] text-white rounded-xl px-4 py-3 text-sm font-bold outline-none focus:border-brand-yellow transition-colors"
            >
              <option value="">{t('forms.chooseCountry')}</option>
              {countries.map((c: any) => <option key={c.isoCode} value={c.isoCode}>{c.name}</option>)}
            </select>

            <select value={selectedState} onChange={e => setSelectedState(e.target.value)}
              disabled={!countryCode}
              className="flex-1 bg-[#111] border border-[#2a2a2a] text-white rounded-xl px-4 py-3 text-sm font-bold outline-none focus:border-brand-yellow transition-colors disabled:opacity-40 disabled:cursor-not-allowed"
            >
              <option value="">Choose a region</option>
              {states.map((s: any) => <option key={s.isoCode} value={s.isoCode}>{s.name}</option>)}
            </select>

            <select value={selectedCity} onChange={e => setSelectedCity(e.target.value)}
              disabled={!countryCode}
              className="flex-1 bg-[#111] border border-[#2a2a2a] text-white rounded-xl px-4 py-3 text-sm font-bold outline-none focus:border-brand-yellow transition-colors disabled:opacity-40 disabled:cursor-not-allowed"
            >
              <option value="">{t('forms.chooseCity')}</option>
              {cities.map((c: any) => <option key={c.name} value={c.name}>{c.name}</option>)}
            </select>

            <button onClick={handleSearch} disabled={false}
              className="bg-brand-yellow text-[#0a0a0a] font-black px-6 py-3 rounded-xl text-sm hover:opacity-90 transition-opacity whitespace-nowrap">
              {t('buttons.searchBarbers')}
            </button>
          </div>

          <input value={nameSearch} onChange={e => { setNameSearch(e.target.value); setPage(1); }}
            placeholder={t('forms.searchByBarberName')}
            className="w-full sm:max-w-sm bg-[#111] border border-[#2a2a2a] text-white rounded-xl px-4 py-3 text-sm font-bold outline-none focus:border-brand-yellow transition-colors placeholder:text-[#444]"
          />
        </div>

        {(activeFilter || nameSearch) && (
          <div className="flex items-center gap-2 mb-2 flex-wrap">
            {activeFilter && (
              <span className="bg-[#1a1a1a] border border-[#2a2a2a] text-white text-xs font-bold px-3 py-1 rounded-full">
                {activeFilter.city
                  ? `${activeFilter.city}, ${activeFilter.countryDisplay || activeFilter.country}`
                  : activeFilter.countryDisplay || activeFilter.country}
              </span>
            )}
            {nameSearch && (
              <span className="bg-[#1a1a1a] border border-[#2a2a2a] text-white text-xs font-bold px-3 py-1 rounded-full">
                &quot;{nameSearch}&quot;
              </span>
            )}
            <button onClick={clearAll} className="text-xs text-[#555] hover:text-white transition-colors">
              {t('buttons.clearAll')} ✕
            </button>
          </div>
        )}
      </div>

      <div className="max-w-[1400px] mx-auto px-6 pb-16">
        <div className="h-px bg-[#1e1e1e] mb-5" />
        {isLoading ? (
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-3 w-full items-stretch">
            {Array.from({ length: 6 }).map((_, i) => (
              <div key={i} className="bg-[#141414] border border-[#222] rounded-[12px] h-[160px] animate-pulse" />
            ))}
          </div>
        ) : filtered.length === 0 ? (
          <div className="text-center py-24">
            <div className="text-5xl mb-4">💈</div>
            <h3 className="text-xl font-black mb-2">
              {activeFilter
                ? activeFilter.city
                  ? t('emptyStates.noBarbersCity').replace('{city}', activeFilter.city)
                  : t('emptyStates.noBarbersCountry').replace('{country}', activeFilter.countryDisplay || activeFilter.country)
                : t('emptyStates.noBarbersFound')}
            </h3>
            <p className="text-[#555] text-sm mb-6">
              {activeFilter ? t('emptyStates.shareWithBarber') : t('emptyStates.checkBackSoon')}
            </p>
            {activeFilter && (
              <button onClick={handleShare}
                className="bg-[#1a1a1a] border border-[#2a2a2a] text-white font-bold px-6 py-3 rounded-full text-sm hover:border-[#444] transition-colors">
                {copied ? t('buttons.copied') : t('buttons.shareApp')}
              </button>
            )}
          </div>
        ) : (
          <>
            <div className="text-xs font-bold text-[#555] mb-4">
              {filtered.length === 1 ? `1 ${t('status.barbersFound')}` : `${filtered.length} ${t('status.barbersFoundPlural')}`}
            </div>
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-3 w-full items-stretch">
              {(() => {
                const firstBlurredIndex = paged.findIndex(
                  bb => shouldBlur && !bb.isFeatured
                );
                return paged.map(b => {
                const isFeaturedCard = b.isFeatured === true;
                const applyBlur = shouldBlur && !isFeaturedCard;
                const showOverlay = applyBlur && paged.indexOf(b) === firstBlurredIndex;
                const name = `${b.firstName} ${b.lastName}`.trim() || t('misc.barberFallback');
                const photo = b.profilePhotoUrl || b.photoUrl;
                const sym = currencySymbol(b.currency);
                const displayLangs = b.languages.slice(0, 2);
                const extraLangs = b.languages.length > 2 ? b.languages.length - 2 : 0;

                return (
                  <div key={b.id} className="relative h-full">
                    <div
                      className="h-full"
                      style={{
                        filter: applyBlur ? 'blur(5px)' : 'none',
                        pointerEvents: applyBlur ? 'none' : 'auto',
                        userSelect: applyBlur ? 'none' : 'auto',
                        transition: 'filter 0.2s',
                      }}
                    >
                      <Link href={`/barber/${b.id}`}
                        prefetch={false}
                        onMouseEnter={() => router.prefetch(`/barber/${b.id}`)}
                        className="bg-[#141414] border border-[#222] rounded-[12px] p-[14px] cursor-pointer flex flex-col h-full">

                        <div className="flex items-start gap-[10px]">
                          <div className="relative w-11 h-11 rounded-[10px] overflow-hidden bg-[#E8491D] shrink-0 flex items-center justify-center">
                            {photo ? (
                              <Image src={photo} alt={name} fill className="object-cover" referrerPolicy="no-referrer" />
                            ) : (
                              <span className="text-[20px] font-black text-white leading-none">{name[0]?.toUpperCase()}</span>
                            )}
                          </div>

                          <div className="flex-1 min-w-0">
                            <div className="flex items-center justify-between gap-1">
                              <span className="font-extrabold text-[13px] text-white truncate">{name}</span>
                              <span className="text-[10px] text-[#555] font-semibold whitespace-nowrap shrink-0">{t('status.newBadge')}</span>
                            </div>
                            {b.city && (
                              <div className="text-[11px] text-[#666] mt-[3px]">📍 {b.city}</div>
                            )}
                          </div>
                        </div>

                        <div className="h-px bg-[#1e1e1e] my-[10px]" />

                        {b.hasSchedule && (
                          <div className={`text-[10px] font-bold mb-[8px] ${b.openColor}`}>
                            {b.isOpenNow ? t('status.openNow') : t('status.closed')}
                          </div>
                        )}

                        {b.languages.length > 0 && (
                          <div className="flex items-center gap-1.5 flex-wrap mb-[10px]">
                            {displayLangs.map((lang: string, i: number) => (
                              <span key={lang} className="flex items-center gap-1 text-[11px] text-[#888]">
                                {i > 0 && <span className="text-[#444]">·</span>}
                                <span className="w-1.5 h-1.5 rounded-full bg-[#60a5fa] inline-block shrink-0" />
                                {lang}
                              </span>
                            ))}
                            {extraLangs > 0 && (
                              <span className="text-[11px] text-[#555]">+{extraLangs}</span>
                            )}
                          </div>
                        )}

                        <div className="flex justify-between items-center mt-auto">
                          <span className="text-[13px] font-bold text-white">
                            {b.minPrice !== null ? `${t('status.fromPrice')} ${sym}${b.minPrice}` : t('buttons.onRequest')}
                          </span>
                          <span className="text-[12px] font-bold text-[#E8491D]">
                            {t('buttons.viewProfile')}
                          </span>
                        </div>
                      </Link>
                    </div>
                    {showOverlay && (
                      <div style={{
                        position: 'absolute',
                        inset: 0,
                        display: 'flex',
                        flexDirection: 'column',
                        alignItems: 'center',
                        justifyContent: 'center',
                        gap: 10,
                        zIndex: 10,
                        borderRadius: 12,
                        background: 'rgba(10,10,10,0.5)',
                        padding: 16,
                      }}>
                        <div style={{ fontSize: 13, fontWeight: 900, color: '#fff', textAlign: 'center' }}>
                          {t('headings.signUpToSeeBarbers')}
                        </div>
                        <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap', justifyContent: 'center' }}>
                          <a href="/signup" style={{
                            background: '#F5C518', color: '#0a0a0a', fontWeight: 900, fontSize: 12,
                            padding: '8px 16px', borderRadius: 8, textDecoration: 'none',
                          }}>{t('buttons.createAccount')}</a>
                          <a href="/login" style={{
                            background: '#1a1a1a', color: '#fff', fontWeight: 900, fontSize: 12,
                            padding: '8px 16px', borderRadius: 8, border: '1px solid #333', textDecoration: 'none',
                          }}>{t('nav.login')}</a>
                        </div>
                      </div>
                    )}
                  </div>
                );
                });
              })()}
            </div>
            <Pagination page={page} total={filtered.length} onChange={setPage} />
          </>
        )}
      </div>
    </div>
  );
}

export default function BarbersPage() {
  // Data is fetched client-side inside BarbersClient using the Firebase
  // client SDK. This keeps the page working without Firebase Admin creds.
  return <BarbersClient />;
}

function calcEndTime(startTime: string, durationMins: number): string {
  const [h, m] = startTime.split(':').map(Number);
  const total = h * 60 + m + durationMins;
  return `${String(Math.floor(total / 60)).padStart(2, '0')}:${String(total % 60).padStart(2, '0')}`;
}

function formatFullDate(dateStr: string, locale: string): string {
  if (!dateStr) return '';
  const [y, mo, d] = dateStr.split('-').map(Number);
  return new Date(y, mo - 1, d).toLocaleDateString(locale, {
    weekday: 'long', year: 'numeric', month: 'long', day: 'numeric',
  });
}

export default function ShopBookingPage() {
  const params = useParams();
  const shopId = params.shopId as string;
  const searchParams = useSearchParams();
  const initialServiceId = searchParams.get('serviceId') ?? '';

  const { user, appUser } = useAuth();
  const { t, lang } = useLang();
  const dateLocale = lang === 'fr' ? 'fr-FR' : lang === 'es' ? 'es-ES' : 'en-US';
  const router = useRouter();
  const { data: challengeConfig } = useChallengeConfig();
  const isChallengeModeOn = challengeConfig?.challengeMode ?? false;
  const challengeModeEndDate = challengeConfig?.challengeModeEndDate ?? '';

  const [step, setStep] = useState<1 | 2 | 3 | 4>(1);

  const [shop, setShop] = useState<ShopData | null>(null);
  const [barbers, setBarbers] = useState<BarberData[]>([]);
  const [services, setServices] = useState<ServiceData[]>([]);
  const [loading, setLoading] = useState(true);

  const [selectedServiceIds, setSelectedServiceIds] = useState<string[]>([]);
  const [selectedDate, setSelectedDate] = useState<string>('');
  const [selectedTime, setSelectedTime] = useState<string>('');
  const [selectedEndTime, setSelectedEndTime] = useState<string>('');
  const [availableBarberIds, setAvailableBarberIds] = useState<string[]>([]);
  const [selectedBarberId, setSelectedBarberId] = useState<string>('');

  const [confirming, setConfirming] = useState(false);
  const [bookingError, setBookingError] = useState<string>('');
  const [honeypot, setHoneypot] = useState('');

  // ── Auth guard ───────────────────────────────────────────────────────────────
  useEffect(() => {
    if (!user) {
      router.replace(`/login?redirect=/book/shop/${shopId}`);
      return;
    }
    if (appUser?.role === 'admin') {
      toast.error(t('profile.adminCannotBook'));
      router.replace('/');
      return;
    }
    if (appUser && !appUser.isOnboarded) {
      router.replace(appUser?.role === 'professional' ? '/onboarding/professional' : '/onboarding/client');
    }
  }, [user, appUser, router, shopId]);

  // ── Load shop + barbers + services ───────────────────────────────────────────
  useEffect(() => {
    if (!shopId || !user) return;

    let cancelled = false;

    (async () => {
      setLoading(true);
      try {
        // 1. Shop
        const shopSnap = await getDoc(doc(db, 'businesses', shopId));
        const shopData: ShopData | null = shopSnap.exists()
          ? ({ id: shopSnap.id, ...(shopSnap.data() as any) })
          : null;

        // 2. Live team barbers
        const barberSnap = await getDocs(query(
          collection(db, 'professionalProfiles'),
          where('businessId', '==', shopId),
          where('isLive', '==', true),
        ));
        const rawBarbers = barberSnap.docs.map(d => ({ id: d.id, ...(d.data() as any) }));

        // Enrich with user data (firstName, lastName, photoUrl)
        const userSnaps = await Promise.all(
          rawBarbers.map(b => getDoc(doc(db, 'users', b.id)))
        );
        const enrichedBarbers: BarberData[] = rawBarbers.map((b, i) => {
          const u = userSnaps[i].exists() ? (userSnaps[i].data() as any) : {};
          return {
            id: b.id,
            firstName: u.firstName,
            lastName: u.lastName,
            profilePhotoUrl: b.profilePhotoUrl ?? u.photoUrl,
            rating: b.rating,
            reviewCount: b.reviewCount,
            specialties: b.specialties,
            languages: b.languages,
            experienceStartYear: b.experienceStartYear,
            experienceVerified: b.experienceVerified,
            totalCuts: b.totalCuts,
            isLive: b.isLive,
          };
        });

        // 3. Shop services
        const svcSnap = await getDocs(query(
          collection(db, 'services'),
          where('providerId', '==', shopId),
          where('providerType', '==', 'shop'),
        ));
        const shopServices: ServiceData[] = svcSnap.docs.map(d => {
          const data = d.data() as any;
          return {
            id: d.id,
            name: data.name,
            price: data.price,
            durationMinutes: data.durationMinutes ?? data.duration,
            currency: data.currency,
            providerType: data.providerType,
          };
        });

        // Prepend titeZMe Cut if shop has it
        const allServices: ServiceData[] = [];
        if (shopData?.titeZMeCut) {
          allServices.push({
            id: 'titeZMeCut',
            name: 'titeZMe Cut',
            price: shopData.titeZMeCut.price ?? 20,
            durationMinutes: shopData.titeZMeCut.durationMinutes ?? 45,
            currency: shopData.titeZMeCut.currency ?? '€',
            isTitz: true,
          });
        }
        allServices.push(...shopServices);

        if (cancelled) return;

        setShop(shopData);
        setBarbers(enrichedBarbers);
        setServices(allServices);

        // Pre-select if URL has serviceId
        if (initialServiceId) {
          const match = allServices.find(s => s.id === initialServiceId);
          if (match) {
            setSelectedServiceIds([match.id]);
            setStep(2);
          }
        }
      } catch (err) {
        console.error('Shop booking load error:', err);
      } finally {
        if (!cancelled) setLoading(false);
      }
    })();

    return () => { cancelled = true; };
  }, [shopId, user, initialServiceId]);

  // ── Derived ──────────────────────────────────────────────────────────────────
  const selectedService = services.find(s => s.id === selectedServiceIds[0]);
  const selectedDuration = selectedService?.durationMinutes ?? 30;
  const selectedPrice = selectedService?.price ?? 0;
  const currency = selectedService?.currency ?? shop?.titeZMeCut?.currency ?? '€';
  const selectedBarber = barbers.find(b => b.id === selectedBarberId);

  // ── Confirm booking ─────────────────────────────────────────────────────────
  const handleConfirm = async () => {
    if (honeypot) {
      console.log('Bot detected in shop booking');
      return;
    }
    if (!user || !appUser) return;
    if (!selectedService || !selectedBarberId || !selectedDate || !selectedTime) return;
    if (confirming) return;

    setConfirming(true);
    setBookingError('');

    try {
      // Rate limit: max 5 per hour
      const oneHourAgo = Date.now() - 60 * 60 * 1000;
      const recentSnap = await getDocs(query(
        collection(db, 'bookings'),
        where('clientId', '==', user.uid),
        where('createdAt', '>', oneHourAgo),
      ));
      if (recentSnap.size >= 5) {
        setBookingError(t('errors.tooManyBookingAttempts'));
        setConfirming(false);
        return;
      }

      // Offline check
      if (typeof navigator !== 'undefined' && !navigator.onLine) {
        setBookingError(t('booking.noInternetBooking'));
        setConfirming(false);
        return;
      }

      // Duplicate check
      const dupSnap = await getDocs(query(
        collection(db, 'bookings'),
        where('clientId', '==', user.uid),
        where('barberId', '==', selectedBarberId),
        where('date', '==', selectedDate),
        where('startTime', '==', selectedTime),
        where('status', 'in', ['pending', 'confirmed']),
      ));
      if (!dupSnap.empty) {
        setBookingError(t('booking.alreadyHaveBooking'));
        setConfirming(false);
        return;
      }

      const lockDocRef = doc(db, 'bookingLocks', `${selectedBarberId}_${selectedDate}`);
      const newBookingId = doc(collection(db, 'bookings')).id;

      const reqStart = new Date(`${selectedDate}T${selectedTime}`).getTime();
      const reqEnd = reqStart + selectedDuration * 60 * 1000;

      const clientFirst = appUser?.firstName || '';
      const clientLast = appUser?.lastName || '';
      const clientName = clientLast
        ? `${clientFirst} ${clientLast.charAt(0)}.`
        : clientFirst || 'Client';
      const barberName = `${selectedBarber?.firstName ?? ''} ${selectedBarber?.lastName ?? ''}`.trim() || null;
      const endTime = selectedEndTime || calcEndTime(selectedTime, selectedDuration);

      await runTransaction(db, async (tx) => {
        const lockDoc = await tx.get(lockDocRef);
        const bookedSlots = lockDoc.exists() ? (lockDoc.data() as any).slots || [] : [];

        let overlap = false;
        for (const slot of bookedSlots) {
          if (Math.max(reqStart, slot.start) < Math.min(reqEnd, slot.end)) {
            overlap = true;
            break;
          }
        }
        if (overlap) throw new Error('OVERLAP');

        tx.set(lockDocRef, {
          slots: [...bookedSlots, { start: reqStart, end: reqEnd, bookingId: newBookingId }],
        }, { merge: true });

        const bookingRef = doc(db, 'bookings', newBookingId);
        tx.set(bookingRef, {
          clientId: user.uid,
          clientName,
          barberId: selectedBarberId,
          barberName,
          shopId,
          bookingContext: 'shop',
          serviceIds: [selectedService.id],
          serviceNames: [selectedService.name ?? ''],
          totalDuration: selectedDuration,
          date: selectedDate,
          startTime: selectedTime,
          appointmentTimestamp: reqStart,
          endTime,
          status: 'pending',
          paymentMethod: 'cash',
          price: selectedPrice,
          createdAt: Date.now(),
          updatedAt: Date.now(),
        });
      });

      // Best-effort post-write notifications
      try {
        await addDoc(collection(db, 'notifications'), notificationSchema.parse({
          userId: selectedBarberId,
          message: `New booking request for ${selectedDate} at ${selectedTime}.`,
          read: false,
          linkTo: '/dashboard/barber',
          createdAt: Date.now(),
        }));
        updateDoc(doc(db, 'users', selectedBarberId), { unreadCount: increment(1) }).catch(console.error);

        await addDoc(collection(db, 'notifications'), notificationSchema.parse({
          userId: user.uid,
          message: `Your booking for ${selectedDate} at ${selectedTime} is pending confirmation.`,
          read: false,
          linkTo: '/dashboard/client',
          createdAt: Date.now(),
        }));
        updateDoc(doc(db, 'users', user.uid), { unreadCount: increment(1) }).catch(console.error);
      } catch (notifErr) {
        console.error('Post-booking notifications failed:', notifErr);
      }

      toast.success(t('booking.bookingSuccess'));
      await new Promise(r => setTimeout(r, 800));
      router.push(appUser?.role === 'professional' ? '/dashboard/barber/bookings' : '/dashboard/client');
    } catch (e: any) {
      console.error(e);
      if (e?.message === 'OVERLAP') {
        setBookingError(t('booking.slotTaken'));
        setSelectedTime('');
        setSelectedEndTime('');
        setStep(2);
      } else {
        setBookingError(t('booking.bookingFailed'));
      }
      setConfirming(false);
    }
  };

  // ─── Loading ────────────────────────────────────────────────────────────────
  if (loading || !user) {
    return (
      <div className="min-h-screen bg-[#0A0A0A] flex items-center justify-center">
        <div className="text-[#666] text-sm font-bold animate-pulse">{t('booking.loadingShop')}</div>
      </div>
    );
  }

  if (!shop) {
    return (
      <div className="min-h-screen bg-[#0A0A0A] flex items-center justify-center text-white">
        <div className="text-center">
          <div className="text-5xl mb-3">🏪</div>
          <div className="font-black text-lg mb-1">{t('booking.shopNotFound')}</div>
          <div className="text-[#666] text-sm">{t('booking.shopNotFoundDesc')}</div>
        </div>
      </div>
    );
  }

  const filteredAvailableBarbers = barbers.filter(b => availableBarberIds.includes(b.id));
  const currentYear = new Date().getFullYear();

  // ─── Render ─────────────────────────────────────────────────────────────────
  if (isChallengeModeOn) {
    return (
      <div className="min-h-screen flex items-center justify-center px-4">
        <div className="max-w-md w-full">
          <SuspendedBookingBanner endDate={challengeModeEndDate} />
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-[#0A0A0A] text-white">
      <div className="max-w-[600px] mx-auto px-6 py-10 md:py-16">

        {/* Progress bar */}
        <div className="flex gap-2 mb-8">
          {[1, 2, 3, 4].map(i => (
            <div key={i} className="h-2 flex-1 rounded-full bg-[#1a1a1a] overflow-hidden">
              <div
                className="h-full transition-all duration-300"
                style={{
                  width: i <= step ? '100%' : '0%',
                  background: i < step ? '#F5C518' : i === step ? '#E8491D' : '#1e1e1e',
                }}
              />
            </div>
          ))}
        </div>

        {/* ── STEP 1 — Service selection ────────────────────────────────────── */}
        {step === 1 && (
          <div className="animate-fadeUp">
            <h1 className="text-3xl font-black mb-1">{t('booking.chooseService')}</h1>
            <p className="text-[#888] text-sm font-bold mb-6">{shop.name}</p>

            {services.length === 0 ? (
              <div className="border-2 border-dashed border-[#2a2a2a] rounded-2xl p-8 text-center">
                <div className="text-[#555] text-sm font-bold">{t('emptyStates.noServicesAdded')}</div>
              </div>
            ) : (
              <div className="flex flex-col gap-3 mb-8">
                {services.map(svc => {
                  const isSelected = selectedServiceIds[0] === svc.id;
                  return (
                    <button
                      key={svc.id}
                      onClick={() => setSelectedServiceIds([svc.id])}
                      className={`flex items-center justify-between p-4 rounded-2xl border-2 transition-all text-left ${isSelected ? 'border-[#E8491D] bg-[#1a0a00]' : 'border-[#2a2a2a] bg-[#141414] hover:border-[#444]'} ${svc.isTitz ? '!border-l-4 !border-l-brand-yellow' : ''}`}
                    >
                      <div className="flex items-center gap-4">
                        <div className={`w-6 h-6 shrink-0 rounded-full border-2 flex items-center justify-center transition-colors ${isSelected ? 'border-[#E8491D] bg-[#E8491D]' : 'border-[#444]'}`}>
                          {isSelected && <span className="text-[#0a0a0a] text-xs font-black">✓</span>}
                        </div>
                        <div>
                          <div className={`font-black flex items-center gap-1.5 ${isSelected ? 'text-[#E8491D]' : 'text-white'}`}>
                            {svc.isTitz && <span>⚡</span>} {svc.name}
                          </div>
                          <div className="text-xs text-[#888] font-bold">{svc.durationMinutes} {t('misc.minShort')}</div>
                        </div>
                      </div>
                      <div className="font-black text-lg">{currency}{svc.price}</div>
                    </button>
                  );
                })}
              </div>
            )}

            <div className="flex justify-end">
              <button
                onClick={() => setStep(2)}
                disabled={selectedServiceIds.length === 0}
                className="bg-brand-yellow text-[#0a0a0a] px-8 py-3.5 rounded-full font-black text-sm transition-all hover:opacity-90 disabled:opacity-50"
              >
                {t('booking.next')}
              </button>
            </div>
          </div>
        )}

        {/* ── STEP 2 — Date & Time ──────────────────────────────────────────── */}
        {step === 2 && (
          <div className="animate-fadeUp">
            <h1 className="text-3xl font-black mb-2">{t('booking.chooseDateTime')}</h1>
            <p className="text-[#888] text-sm font-bold mb-6">
              {selectedDuration} {t('misc.minShort')} · {shop.name}
            </p>

            <ShopTimePicker
              barberIds={barbers.map(b => b.id)}
              totalDuration={selectedDuration}
              selectedDate={selectedDate}
              selectedTime={selectedTime}
              onSelect={(date, time, endTime, availIds) => {
                setSelectedDate(date);
                setSelectedTime(time);
                setSelectedEndTime(endTime);
                setAvailableBarberIds(availIds);
                // If barber was previously chosen but is no longer free in this slot, clear it
                if (selectedBarberId && !availIds.includes(selectedBarberId)) {
                  setSelectedBarberId('');
                }
              }}
            />

            {selectedDate && selectedTime && (
              <div className="mt-5 flex items-center gap-3 bg-[#1a0a00] border border-[#E8491D]/40 rounded-xl px-4 py-3">
                <span style={{ color: '#E8491D', fontSize: 16 }}>✓</span>
                <span style={{ fontSize: 13, fontWeight: 700, color: '#E8491D' }}>
                  {selectedDate} · {selectedTime} → {selectedEndTime || calcEndTime(selectedTime, selectedDuration)}
                </span>
                <button
                  onClick={() => { setSelectedDate(''); setSelectedTime(''); setSelectedEndTime(''); setAvailableBarberIds([]); setSelectedBarberId(''); }}
                  style={{ marginLeft: 'auto', fontSize: 11, color: '#555', fontWeight: 700, background: 'none', border: 'none', cursor: 'pointer' }}
                >
                  {t('booking.clearSlot')}
                </button>
              </div>
            )}

            <div className="flex justify-between mt-8">
              <button onClick={() => setStep(1)} className="text-[#888] font-bold text-sm hover:text-white transition-colors">
                {t('booking.back')}
              </button>
              <button
                onClick={() => setStep(3)}
                disabled={!selectedDate || !selectedTime}
                className="bg-brand-yellow text-[#0a0a0a] px-8 py-3.5 rounded-full font-black text-sm transition-all hover:opacity-90 disabled:opacity-50"
              >
                {t('booking.next')}
              </button>
            </div>
          </div>
        )}

        {/* ── STEP 3 — Choose barber ────────────────────────────────────────── */}
        {step === 3 && (
          <div className="animate-fadeUp">
            <h1 className="text-3xl font-black mb-2">{t('booking.chooseBarber')}</h1>
            <p className="text-[#888] text-sm font-bold mb-6">
              {t('booking.availableAt').replace('{time}', selectedTime).replace('{date}', formatFullDate(selectedDate, dateLocale))}
            </p>

            {filteredAvailableBarbers.length === 0 ? (
              <div className="border-2 border-dashed border-[#2a2a2a] rounded-2xl p-8 text-center">
                <div className="text-[#555] text-sm font-bold">{t('booking.noBarbersSlot')}</div>
                <button onClick={() => setStep(2)} className="mt-3 text-[#E8491D] text-xs font-black hover:underline">
                  {t('booking.pickDifferentTime')}
                </button>
              </div>
            ) : (
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-3 mb-8">
                {filteredAvailableBarbers.map(b => {
                  const isSelected = selectedBarberId === b.id;
                  const name = `${b.firstName ?? ''} ${b.lastName ?? ''}`.trim() || t('misc.barberFallback');
                  const yrs = b.experienceStartYear ? currentYear - b.experienceStartYear : null;
                  return (
                    <button
                      key={b.id}
                      onClick={() => setSelectedBarberId(b.id)}
                      className={`text-left p-4 rounded-2xl border-2 transition-all ${isSelected ? 'border-[#E8491D] bg-[#1a0a00]' : 'border-[#2a2a2a] bg-[#141414] hover:border-[#444]'}`}
                    >
                      <div className="flex items-center gap-3 mb-3">
                        <div className="relative w-[52px] h-[52px] rounded-[14px] overflow-hidden shrink-0 border border-[#2a2a2a] bg-[#1a1a1a]">
                          {b.profilePhotoUrl ? (
                            <Image src={b.profilePhotoUrl} alt={name} fill className="object-cover" referrerPolicy="no-referrer" />
                          ) : (
                            <div className="w-full h-full flex items-center justify-center font-black text-xl text-[#0a0a0a]" style={{ background: '#E8491D' }}>
                              {name[0]}
                            </div>
                          )}
                        </div>
                        <div className="min-w-0">
                          <div className={`font-black text-sm truncate ${isSelected ? 'text-[#E8491D]' : 'text-white'}`}>{name}</div>
                          <div className="text-xs font-bold mt-0.5">
                            {(b.reviewCount ?? 0) > 0 ? (
                              <span className="text-brand-yellow">
                                {'★'.repeat(Math.round(b.rating ?? 0))} {b.rating?.toFixed(1)} ({b.reviewCount})
                              </span>
                            ) : (
                              <span className="text-[#555]">{t('status.newBadge')}</span>
                            )}
                          </div>
                        </div>
                      </div>

                      {b.specialties && b.specialties.length > 0 && (
                        <div className="flex flex-wrap gap-1 mb-2">
                          {b.specialties.slice(0, 3).map(s => (
                            <span key={s} className="bg-brand-yellow/10 text-brand-yellow text-[10px] font-black px-1.5 py-0.5 rounded border border-brand-yellow/20">
                              {s}
                            </span>
                          ))}
                        </div>
                      )}

                      {b.languages && b.languages.length > 0 && (
                        <div className="text-[11px] text-[#555] font-bold mb-2">
                          {b.languages.join(' · ')}
                        </div>
                      )}

                      {yrs !== null && (
                        <div className="flex items-center gap-1.5 text-[11px] font-bold text-[#888]">
                          <span>{yrs} {t('misc.yearsExp')}</span>
                          {b.experienceVerified && (
                            <span title="Verified" style={{ width: 6, height: 6, borderRadius: '50%', background: '#22C55E', display: 'inline-block' }} />
                          )}
                        </div>
                      )}
                    </button>
                  );
                })}
              </div>
            )}

            <div className="flex justify-between mt-2">
              <button onClick={() => setStep(2)} className="text-[#888] font-bold text-sm hover:text-white transition-colors">
                {t('booking.back')}
              </button>
              <button
                onClick={() => setStep(4)}
                disabled={!selectedBarberId}
                className="bg-brand-yellow text-[#0a0a0a] px-8 py-3.5 rounded-full font-black text-sm transition-all hover:opacity-90 disabled:opacity-50"
              >
                {t('booking.next')}
              </button>
            </div>
          </div>
        )}

        {/* ── STEP 4 — Review & confirm ─────────────────────────────────────── */}
        {step === 4 && (
          <div className="animate-fadeUp">
            <input
              type="text"
              name="website"
              value={honeypot}
              onChange={e => setHoneypot(e.target.value)}
              style={{ position: 'absolute', left: '-9999px', width: '1px', height: '1px', opacity: 0, pointerEvents: 'none' }}
              tabIndex={-1}
              autoComplete="off"
              aria-hidden="true"
            />

            <h1 className="text-3xl font-black mb-8">{t('booking.reviewYourBooking')}</h1>

            <div className="bg-[#111] border border-[#1e1e1e] rounded-2xl overflow-hidden mb-6">

              {/* Shop */}
              <div className="flex items-center gap-4 p-5 border-b border-[#1e1e1e]">
                <div className="relative w-11 h-11 rounded-xl bg-[#1a1a1a] border border-[#2a2a2a] overflow-hidden shrink-0 flex items-center justify-center">
                  {shop.logoUrl ? (
                    <Image src={shop.logoUrl} alt={shop.name ?? ''} fill className="object-cover" referrerPolicy="no-referrer" />
                  ) : (
                    <span className="text-xl">🏪</span>
                  )}
                </div>
                <div>
                  <div className="font-black text-white text-[15px]">{shop.name}</div>
                  <div className="text-xs font-bold text-[#555] mt-0.5">{t('booking.bookingViaShopLabel')}</div>
                </div>
              </div>

              {/* Barber */}
              <div className="flex items-center gap-4 p-5 border-b border-[#1e1e1e]">
                <div className="relative w-11 h-11 rounded-xl bg-[#1a1a1a] border border-[#2a2a2a] overflow-hidden shrink-0 flex items-center justify-center">
                  {selectedBarber?.profilePhotoUrl ? (
                    <Image src={selectedBarber.profilePhotoUrl} alt="" fill className="object-cover" referrerPolicy="no-referrer" />
                  ) : (
                    <span className="text-xl">✂️</span>
                  )}
                </div>
                <div>
                  <div className="font-black text-white text-[15px]">
                    {selectedBarber ? `${selectedBarber.firstName ?? ''} ${selectedBarber.lastName ?? ''}`.trim() : t('misc.barberFallback')}
                  </div>
                  <div className="text-xs font-bold text-[#555] mt-0.5">{t('booking.yourBarber')}</div>
                </div>
              </div>

              {/* Service */}
              <div className="p-5 border-b border-[#1e1e1e]">
                <div className="text-[10px] font-extrabold text-[#555] tracking-widest uppercase mb-3">{t('booking.serviceLabel')}</div>
                <div className="flex items-center justify-between">
                  <div>
                    <div className="text-sm font-bold text-white">{selectedService?.name}</div>
                    <div className="text-[11px] text-[#555]">⏱ {selectedDuration} {t('misc.minShort')}</div>
                  </div>
                  <div className="font-black text-[#F5C518] text-sm">{currency}{selectedPrice}</div>
                </div>
              </div>

              {/* Date & time */}
              <div className="p-5 border-b border-[#1e1e1e]">
                <div className="text-[10px] font-extrabold text-[#555] tracking-widest uppercase mb-3">{t('booking.dateAndTime')}</div>
                <div className="flex items-center gap-2 mb-1.5">
                  <span style={{ fontSize: 15 }}>📅</span>
                  <span className="font-bold text-white text-sm">{formatFullDate(selectedDate, dateLocale)}</span>
                </div>
                <div className="flex items-center gap-2">
                  <span style={{ fontSize: 15 }}>⏰</span>
                  <span className="font-bold text-white text-sm">
                    {selectedTime} → {selectedEndTime || calcEndTime(selectedTime, selectedDuration)}
                  </span>
                  <span className="text-[11px] text-[#555]">({selectedDuration} {t('misc.minShort')})</span>
                </div>
              </div>

              {/* Payment */}
              <div className="p-5">
                <div className="text-[10px] font-extrabold text-[#555] tracking-widest uppercase mb-3">{t('booking.payment')}</div>
                <div className="flex items-start gap-3">
                  <span style={{ fontSize: 15 }}>💵</span>
                  <div>
                    <div className="font-black text-[#F5C518] text-lg">{currency}{selectedPrice}</div>
                    <div className="text-xs font-bold text-[#555] mt-0.5">{t('booking.cashOnlyShort')}</div>
                    <div className="text-xs text-[#444] mt-0.5">{t('booking.payDirectly')}</div>
                  </div>
                </div>
              </div>
            </div>

            <button
              onClick={handleConfirm}
              disabled={confirming}
              className="w-full bg-brand-yellow text-[#0a0a0a] py-4 rounded-full font-black text-[15px] transition-all hover:opacity-90 disabled:opacity-50"
            >
              {confirming ? t('booking.confirming') : t('booking.confirmBooking')}
            </button>

            {bookingError && (
              <div className="mt-4 p-3 rounded-xl bg-[#1a0808] border border-[#EF4444]/40 text-[#EF4444] text-xs font-bold text-center">
                {bookingError}
              </div>
            )}

            <button
              disabled={confirming}
              onClick={() => setStep(3)}
              className="w-full mt-4 text-[#888] font-bold text-sm hover:text-white transition-colors disabled:opacity-50"
            >
              {t('booking.changeBarber')}
            </button>
          </div>
        )}

      </div>
    </div>
  );
}

export default function BookLayout({ children }: { children: ReactNode }) {
  return (
    <ErrorBoundary>
      {children}
    </ErrorBoundary>
  );
}

function calcEndTime(startTime: string, durationMins: number): string {
  const [h, m] = startTime.split(':').map(Number);
  const total = h * 60 + m + durationMins;
  return `${String(Math.floor(total / 60)).padStart(2, '0')}:${String(total % 60).padStart(2, '0')}`;
}

function formatFullDate(dateStr: string, locale: string): string {
  if (!dateStr) return '';
  const [y, mo, d] = dateStr.split('-').map(Number);
  return new Date(y, mo - 1, d).toLocaleDateString(locale, {
    weekday: 'long', year: 'numeric', month: 'long', day: 'numeric',
  });
}

export default function BookingPage({ params }: { params: Promise<{ barberId: string }> }) {
  const resolvedParams = use(params);
  const barberId = resolvedParams.barberId;
  const { user, appUser } = useAuth();
  const router = useRouter();

  const { t, lang } = useLang();
  const dateLocale = lang === 'fr' ? 'fr-FR' : lang === 'es' ? 'es-ES' : 'en-US';
  const { data: challengeConfig } = useChallengeConfig();
  const isChallengeModeOn = challengeConfig?.challengeMode ?? false;
  const challengeModeEndDate = challengeConfig?.challengeModeEndDate ?? '';
  const [step, setStep] = useState(1);
  const [bookingContext, setBookingContext] = useState<'solo'|'shop'>('solo');
  const [selectedServices, setSelectedServices] = useState<any[]>([]);
  const [selectedDate, setSelectedDate] = useState<string>('');
  const [selectedTime, setSelectedTime] = useState<string>('');
  const [selectedEndTime, setSelectedEndTime] = useState<string>('');
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [honeypot, setHoneypot] = useState('');

  const { data: profile, isLoading: loadingProfile } = useQuery({
    queryKey: ['bookProfile', barberId],
    queryFn: async () => {
      const pSnap = await getDoc(doc(db, 'professionalProfiles', barberId));
      if (!pSnap.exists()) return null;
      const pData = pSnap.data() as any;
      const uSnap = await getDoc(doc(db, 'users', barberId));
      return { id: pSnap.id, ...pData, user: uSnap.exists() ? uSnap.data() : null };
    },
    enabled: !!user
  });

  useEffect(() => {
    if (loadingProfile) return;
    if (
      !profile ||
      !profile.isLive ||
      profile.approvalStatus !== 'approved'
    ) {
      router.replace('/barbers');
    }
  }, [profile, loadingProfile]);

  useEffect(() => {
    if (profile && step === 1) {
      if (!(!profile.businessId && profile.businessId)) {
        setBookingContext(profile.businessId && !(!profile.businessId) ? 'shop' : 'solo');
        setStep(2);
      }
    }
  }, [profile, step]);

  useEffect(() => {
    if (!user) {
      router.replace('/login');
    }
  }, [user, router]);

const { data: services = [], isLoading: loadingServices } = useQuery({
    queryKey: ['bookServices', barberId, bookingContext, profile?.businessId],
    queryFn: async () => {
      if (!profile) return [];
      const providerId = bookingContext === 'shop' && profile.businessId ? profile.businessId : barberId;
      const pType = bookingContext === 'shop' ? 'shop' : 'barber';
      
      const qSvc = query(collection(db, 'services'), where('providerId', '==', providerId), where('providerType', '==', pType));
      const snap = await getDocs(qSvc);
      const fetchedServices = snap.docs.map(d => ({id: d.id, ...d.data()} as any));
      
      const titzCut = {
        id: 'titezme-cut',
        name: 'titeZMe Cut',
        description: t('booking.titeZMeCutDesc'),
        duration: profile?.titeZMeCut?.durationMinutes || 45,
        price: profile?.titeZMeCut?.price || 20,
        isTitz: true
      };
      
      return [titzCut, ...fetchedServices];
    },
    enabled: !!profile && step >= 2
  });

  const loading = loadingProfile || (step >= 2 && loadingServices);

  const totalPrice = selectedServices.reduce((sum, s) => sum + s.price, 0);
  const totalDuration = selectedServices.reduce((sum, s) => sum + s.duration, 0);



  const toggleService = (svc: any) => {
    setSelectedServices(prev => {
      const isSelected = prev.some(s => s.id === svc.id);
      if (isSelected) return prev.filter(s => s.id !== svc.id);
      return [...prev, svc];
    });
  }

  const handleConfirm = async () => {
    if (honeypot) {
      console.log('Bot detected in booking');
      return;
    }
    if (!user || !selectedDate || !selectedTime || selectedServices.length === 0) return;
    if (isSubmitting) return;
    if (user.uid === barberId) {
      toast.error(t('errors.cannotBookOwn'));
      return;
    }
    setIsSubmitting(true);

    try {
      // ── Rate limiting: max 5 bookings per hour ──────────────────────────────
      const oneHourAgo = Date.now() - (60 * 60 * 1000);
      const recentBookingsQuery = query(
        collection(db, 'bookings'),
        where('clientId', '==', user.uid),
        where('createdAt', '>', oneHourAgo)
      );
      const recentBookings = await getDocs(recentBookingsQuery);
      if (recentBookings.size >= 5) {
        toast.error(t('errors.tooManyBookingAttempts'));
        setIsSubmitting(false);
        return;
      }

      // ── Offline check ────────────────────────────────────────────────────────
      if (!navigator.onLine) {
        toast.error(t('booking.noInternetBooking'));
        setIsSubmitting(false);
        return;
      }

      // ── Duplicate booking check ──────────────────────────────────────────────
      const existingQuery = query(
        collection(db, 'bookings'),
        where('clientId', '==', user.uid),
        where('barberId', '==', barberId),
        where('date', '==', selectedDate),
        where('startTime', '==', selectedTime),
        where('status', 'in', ['pending', 'confirmed'])
      );
      const existing = await getDocs(existingQuery);
      if (!existing.empty) {
        toast.error(t('booking.alreadyHaveBooking'));
        setIsSubmitting(false);
        return;
      }

      // Cross-barber overlap check
      // Catches: client books barber A at 14:00 for 60min
      // then books barber B at 14:30 — the existing check
      // misses this because barberId differs.
      const clientDaySnap = await getDocs(query(
        collection(db, 'bookings'),
        where('clientId', '==', user.uid),
        where('date',     '==', selectedDate),
        where('status',   'in', ['pending', 'confirmed'])
      ));

      if (!clientDaySnap.empty) {
        const reqStart = new Date(
          `${selectedDate}T${selectedTime}`
        ).getTime();
        const reqEnd = reqStart + (totalDuration * 60 * 1000);

        for (const b of clientDaySnap.docs) {
          const bd = b.data();
          const bStart = bd.appointmentTimestamp
            || new Date(`${bd.date}T${bd.startTime}`).getTime();
          const bEnd = bd.endTime
            ? new Date(`${bd.date}T${bd.endTime}`).getTime()
            : bStart + ((bd.totalDuration || 30) * 60 * 1000);

          if (Math.max(reqStart, bStart) < Math.min(reqEnd, bEnd)) {
            toast.error(t('booking.bookingOverlap'));
            setIsSubmitting(false);
            return;
          }
        }
      }

      const lockDocRef = doc(db, 'bookingLocks', `${barberId}_${selectedDate}`);
      const newBookingId = doc(collection(db, 'bookings')).id; 

      await runTransaction(db, async (t) => {
        const lockDoc = await t.get(lockDocRef);
        const bookedSlots = lockDoc.exists() ? lockDoc.data().slots || [] : [];
        
        const reqStart = new Date(`${selectedDate}T${selectedTime}`).getTime();
        const reqEnd = reqStart + (totalDuration * 60 * 1000);

        // Double Booking check against the lock document
        let overlap = false;
        for (const slot of bookedSlots) {
          if (Math.max(reqStart, slot.start) < Math.min(reqEnd, slot.end)) {
             overlap = true;
             break;
          }
        }

        if (overlap) {
           throw new Error("OVERLAP");
        }

        // It's free! Add to lock document
        t.set(lockDocRef, {
           slots: [...bookedSlots, { start: reqStart, end: reqEnd, bookingId: newBookingId }]
        }, { merge: true });

        // Create the booking document
        const bookingRef = doc(db, 'bookings', newBookingId);
        const clientFirst = appUser?.firstName || '';
        const clientLast = appUser?.lastName || '';
        const clientName = clientLast
          ? `${clientFirst} ${clientLast.charAt(0)}.`
          : clientFirst || 'Client';
        t.set(bookingRef, {
          clientId: user.uid,
          clientName,
          barberId: barberId,
          barberName: `${profile?.user?.firstName || ''} ${profile?.user?.lastName || ''}`.trim() || null,
          shopId: profile.businessId || null,
          bookingContext,
          serviceIds: selectedServices.map(s => s.id),
          serviceNames: selectedServices.map(s => s.name),
          totalDuration,
          date: selectedDate,
          startTime: selectedTime,
          appointmentTimestamp: new Date(
            `${selectedDate}T${selectedTime}`
          ).getTime(),
          endTime: selectedEndTime || new Date(reqEnd).toLocaleTimeString(dateLocale, {hour12:false, hour:'2-digit', minute:'2-digit'}),
          status: 'pending',
          paymentMethod: 'cash',
          price: totalPrice,
          createdAt: Date.now(),
          updatedAt: Date.now()
        });
      });

    } catch (e: any) {
      console.error(e);
      if (e.message === "OVERLAP") {
         toast.error(t('booking.slotTaken'));
         setSelectedTime('');
         setSelectedEndTime('');
         setStep(3); // Go back to slots
      } else {
         const getBookingError = (err: any): string => {
           const code = err?.code || '';
           const msg = (err?.message || '').toLowerCase();
           if (code === 'permission-denied' || msg.includes('permission')) {
             return t('booking.unableToBook');
           }
           if (msg.includes('overlap') || msg.includes('taken') || msg.includes('slot')) {
             return t('booking.slotTaken');
           }
           if (code === 'unavailable' || msg.includes('network')) {
             return t('errors.connectionError');
           }
           return t('booking.bookingFailed');
         };
         toast.error(getBookingError(e));
      }
      setIsSubmitting(false);
      return;
    }

    // Booking exists — secondary writes
    try {
      await addDoc(collection(db, 'notifications'), notificationSchema.parse({
              userId: barberId,
              message: `New booking request for ${selectedDate} at ${selectedTime}.`,
              read: false,
              linkTo: '/dashboard/barber',
              createdAt: Date.now()
            }));
      updateDoc(doc(db, 'users', barberId), { unreadCount: increment(1) }).catch(console.error);

      await addDoc(collection(db, 'notifications'), notificationSchema.parse({
              userId: user.uid,
              message: `Your booking for ${selectedDate} at ${selectedTime} is pending confirmation.`,
              read: false,
              linkTo: '/dashboard/client',
              createdAt: Date.now()
            }));
      updateDoc(doc(db, 'users', user.uid), { unreadCount: increment(1) }).catch(console.error);
    } catch (notifErr) {
      // Booking was created — do not surface this error
      console.error('Post-booking notifications failed:', notifErr);
    }

    toast.success(t('booking.bookingSuccess'));
    await new Promise(resolve => setTimeout(resolve, 1000));
    router.push('/dashboard/client');
    setIsSubmitting(false);
  }

  if (loading) return <BarberProfileSkeleton />;

  if (user && !user.emailVerified) {
    return (
      <div style={{
        minHeight: '100vh',
        background: '#0A0A0A',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        fontFamily: 'Nunito, sans-serif',
        padding: '20px'
      }}>
        <div style={{
          background: '#111',
          border: '1px solid #F5C51833',
          borderRadius: '20px',
          padding: '40px',
          maxWidth: '380px',
          width: '100%',
          textAlign: 'center'
        }}>
          <div style={{ fontSize: '40px', marginBottom: '16px' }}>✉️</div>
          <div style={{ fontSize: '18px', fontWeight: 900, color: '#fff', marginBottom: '8px' }}>
            {t('booking.verifyEmailFirst')}
          </div>
          <div style={{ fontSize: '12px', color: '#666', lineHeight: '1.7', marginBottom: '20px' }}>
            {t('booking.verifyEmailDesc')}
          </div>
          <button
            onClick={async () => {
              await sendEmailVerification(user);
              toast.success(t('booking.verificationEmailSent'));
            }}
            style={{
              background: '#F5C518',
              color: '#0a0a0a',
              border: 'none',
              borderRadius: '99px',
              padding: '12px',
              fontSize: '13px',
              fontWeight: 900,
              cursor: 'pointer',
              fontFamily: 'inherit',
              width: '100%',
              marginBottom: '12px'
            }}
          >
            {t('buttons.resendVerification')}
          </button>
          <Link
            href="/dashboard/client"
            style={{ color: '#555', fontSize: '11px', textDecoration: 'none' }}
          >
            {t('booking.backToDashboard')}
          </Link>
        </div>
      </div>
    );
  }

  if (user && appUser) {
    const createdAt = Number(appUser.createdAt) || 0;
    const fiveMinutes = 5 * 60 * 1000;
    const accountAge = Date.now() - createdAt;
    if (accountAge < fiveMinutes) {
      const waitSeconds = Math.ceil((fiveMinutes - accountAge) / 1000);
      const waitMinutes = Math.ceil(waitSeconds / 60);
      return (
        <div style={{
          minHeight: '100vh',
          background: '#0A0A0A',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          fontFamily: 'Nunito, sans-serif',
          padding: '20px'
        }}>
          <div style={{
            background: '#111',
            border: '1px solid #1e1e1e',
            borderRadius: '20px',
            padding: '40px',
            maxWidth: '380px',
            textAlign: 'center'
          }}>
            <div style={{ fontSize: '40px', marginBottom: '16px' }}>⏳</div>
            <div style={{ fontSize: '18px', fontWeight: 900, color: '#fff', marginBottom: '8px' }}>
              {t('booking.almostReady')}
            </div>
            <div style={{ fontSize: '12px', color: '#666', lineHeight: '1.7' }}>
              {t('booking.newAccountWait')
                .replace('{minutes}', String(waitMinutes))
                .replace('{plural}', waitMinutes === 1 ? '' : 's')}
            </div>
          </div>
        </div>
      );
    }
  }

  if (isChallengeModeOn) {
    return (
      <div className="min-h-screen flex items-center justify-center px-4">
        <div className="max-w-md w-full">
          <SuspendedBookingBanner endDate={challengeModeEndDate} />
        </div>
      </div>
    );
  }

  return (
    <div className="max-w-[600px] mx-auto px-6 py-10 md:py-16">

       <div className="flex gap-2 mb-8">
         {[1,2,3,4].map((i) => (
           <div key={i} className={`h-2 flex-1 rounded-full bg-[#1a1a1a] overflow-hidden`}>
             <div className={`h-full bg-brand-yellow transition-all duration-300 ${i <= step ? 'w-full' : 'w-0'}`} />
           </div>
         ))}
       </div>

       {step === 1 && (
         <div className="animate-fadeUp">
           <h1 className="text-3xl font-black mb-6">{t('booking.howToBook')}</h1>
           <div className="flex flex-col gap-4">
             <button onClick={() => {setBookingContext('solo'); setStep(2)}} className="bg-brand-surface border border-brand-border hover:border-brand-yellow p-6 rounded-2xl text-left transition-all group">
               <div className="font-black text-xl mb-1 group-hover:text-brand-yellow transition-colors">{t('booking.bookDirectly').replace('{name}', profile?.user?.firstName || '')}</div>
               <div className="text-brand-text-secondary text-sm font-bold">{t('booking.independentBooking')}</div>
             </button>
             <button onClick={() => {setBookingContext('shop'); setStep(2)}} className="bg-brand-surface border border-brand-border hover:border-brand-yellow p-6 rounded-2xl text-left transition-all group">
               <div className="font-black text-xl mb-1 group-hover:text-brand-yellow transition-colors">{t('booking.bookViaShop')}</div>
               <div className="text-brand-text-secondary text-sm font-bold">{t('booking.shopBookingDesc')}</div>
             </button>
           </div>
         </div>
       )}

       {step === 2 && (
         <div className="animate-fadeUp">
           <h1 className="text-3xl font-black mb-2">{t('booking.selectServices')}</h1>
           <p className="text-brand-text-secondary text-sm mb-6 font-bold">{bookingContext === 'solo' ? t('booking.directServices').replace('{name}', profile?.user?.firstName || '') : t('booking.shopServices')}</p>
           
           <div className="flex flex-col gap-3 mb-8">
             {services.map((svc: any) => {
               const isSelected = selectedServices.some(s => s.id === svc.id);
               return (
                 <label key={svc.id} onClick={() => toggleService(svc)} className={`flex items-center justify-between p-4 rounded-2xl border-2 transition-all cursor-pointer ${isSelected ? 'border-brand-yellow bg-[#1a1500]' : 'border-[#2a2a2a] bg-[#141414] hover:border-[#444]'} ${svc.isTitz ? '!border-l-4 !border-l-brand-yellow' : ''}`}>
                    <div className="flex items-center gap-4">
                       <div className={`w-6 h-6 shrink-0 rounded-full border-2 flex items-center justify-center transition-colors ${isSelected ? 'border-brand-yellow bg-brand-yellow' : 'border-[#444]'}`}>
                         {isSelected && <span className="text-[#0a0a0a] text-xs font-black">✓</span>}
                       </div>
                       <div>
                         <div className={`font-black flex items-center gap-1.5 ${isSelected ? 'text-brand-yellow' : 'text-white'}`}>{svc.isTitz && <span>⚡</span>} {svc.name}</div>
                         <div className="text-xs text-brand-text-secondary font-bold">{svc.duration} {t('misc.minsShort')}</div>
                         {svc.description && <div className="text-[11px] text-[#888] mt-1 pr-2 leading-tight">{svc.description}</div>}
                       </div>
                    </div>
                    <div className="font-black text-lg self-center">€{svc.price}</div>
                 </label>
               )
             })}
           </div>
           
           <div className="flex justify-between items-center border-t border-[#2a2a2a] pt-6">
             <div>
               <div className="text-[11px] font-extrabold text-brand-text-secondary tracking-widest uppercase mb-1">{t('booking.total')}</div>
               <div className="text-2xl font-black text-white">€{totalPrice} <span className="text-sm text-[#666] font-extrabold">/ {totalDuration} {t('misc.minShort')}</span></div>
             </div>
             <button 
               onClick={() => setStep(3)}
               disabled={selectedServices.length === 0}
               className="bg-brand-yellow text-[#0a0a0a] px-8 py-3.5 rounded-full font-black text-sm transition-all hover:opacity-90 disabled:opacity-50"
             >
               {t('booking.next')}
             </button>
           </div>
         </div>
       )}

       {step === 3 && (
         <div className="animate-fadeUp w-full">
           <h1 className="text-3xl font-black mb-2">{t('booking.chooseDatetime')}</h1>
           <p className="text-brand-text-secondary text-sm font-bold mb-6">
             {totalDuration} {t('misc.minShort')} · {profile?.user?.firstName}
           </p>

           <SmartTimePicker
             barberId={barberId}
             totalDuration={totalDuration}
             selectedDate={selectedDate}
             selectedTime={selectedTime}
             onSelect={(date, time, endTime) => {
               setSelectedDate(date);
               setSelectedTime(time);
               setSelectedEndTime(endTime);
             }}
           />

           {/* Selected slot confirmation banner */}
           {selectedDate && selectedTime && (
             <div
               className="mt-5 flex items-center gap-3 bg-[#1a0a00] border border-[#E8491D]/40 rounded-xl px-4 py-3"
             >
               <span style={{ color: '#E8491D', fontSize: 16 }}>✓</span>
               <span style={{ fontSize: 13, fontWeight: 700, color: '#E8491D' }}>
                 {selectedDate} · {selectedTime} → {selectedEndTime || calcEndTime(selectedTime, totalDuration)}
               </span>
               <button
                 onClick={() => { setSelectedDate(''); setSelectedTime(''); setSelectedEndTime(''); }}
                 style={{ marginLeft: 'auto', fontSize: 11, color: '#555', fontWeight: 700, background: 'none', border: 'none', cursor: 'pointer' }}
               >
                 {t('booking.clearSlot')}
               </button>
             </div>
           )}

           <div className="flex justify-between mt-8">
             <button onClick={() => setStep(2)} className="text-[#888] font-bold text-sm hover:text-white transition-colors">
               {t('booking.back')}
             </button>
             <button
               onClick={() => setStep(4)}
               disabled={!selectedDate || !selectedTime}
               className="bg-brand-yellow text-[#0a0a0a] px-8 py-3.5 rounded-full font-black text-sm transition-all hover:opacity-90 disabled:opacity-50 disabled:cursor-not-allowed"
             >
               {t('booking.reviewBookingBtn')}
             </button>
           </div>
         </div>
       )}

       {step === 4 && (
         <div className="animate-fadeUp">
           <input
             type="text"
             name="website"
             value={honeypot}
             onChange={e => setHoneypot(e.target.value)}
             style={{
               position: 'absolute',
               left: '-9999px',
               width: '1px',
               height: '1px',
               opacity: 0,
               pointerEvents: 'none'
             }}
             tabIndex={-1}
             autoComplete="off"
             aria-hidden="true"
           />
           <h1 className="text-3xl font-black mb-8">{t('booking.reviewYourBooking')}</h1>

           <div className="bg-[#111] border border-[#1e1e1e] rounded-2xl overflow-hidden mb-6">

             {/* Section 1 — Barber */}
             <div className="flex items-center gap-4 p-5 border-b border-[#1e1e1e]">
               <div className="w-11 h-11 rounded-xl bg-[#1a1a1a] border border-[#2a2a2a] flex items-center justify-center text-xl shrink-0">✂️</div>
               <div>
                 <div className="font-black text-white text-[15px]">{profile?.user?.firstName} {profile?.user?.lastName}</div>
                 <div className="text-xs font-bold text-[#555] mt-0.5">{bookingContext === 'solo' ? t('booking.independentBookingLabel') : t('booking.shopBookingLabel')}</div>
               </div>
             </div>

             {/* Section 2 — Services */}
             <div className="p-5 border-b border-[#1e1e1e]">
               <div className="text-[10px] font-extrabold text-[#555] tracking-widest uppercase mb-3">{t('booking.services')}</div>
               <div className="flex flex-col gap-2">
                 {selectedServices.map(s => (
                   <div key={s.id} className="flex items-center justify-between">
                     <div>
                       <div className="text-sm font-bold text-white">{s.name}</div>
                       <div className="text-[11px] text-[#555]">⏱ {s.duration} {t('misc.minShort')}</div>
                     </div>
                     <div className="font-black text-[#F5C518] text-sm">€{s.price}</div>
                   </div>
                 ))}
               </div>
               {selectedServices.length > 1 && (
                 <div className="mt-3 pt-3 border-t border-[#1e1e1e] flex justify-between items-center">
                   <span className="text-xs font-bold text-[#555]">{totalDuration} {t('misc.minTotal')}</span>
                   <span className="font-black text-white">€{totalPrice}</span>
                 </div>
               )}
             </div>

             {/* Section 3 — Date & Time */}
             <div className="p-5 border-b border-[#1e1e1e]">
               <div className="text-[10px] font-extrabold text-[#555] tracking-widest uppercase mb-3">{t('booking.dateAndTime')}</div>
               <div className="flex items-center gap-2 mb-1.5">
                 <span style={{ fontSize: 15 }}>📅</span>
                 <span className="font-bold text-white text-sm">{formatFullDate(selectedDate, dateLocale)}</span>
               </div>
               <div className="flex items-center gap-2">
                 <span style={{ fontSize: 15 }}>⏰</span>
                 <span className="font-bold text-white text-sm">
                   {selectedTime} → {calcEndTime(selectedTime, totalDuration)}
                 </span>
                 <span className="text-[11px] text-[#555]">({totalDuration} {t('misc.minShort')})</span>
               </div>
             </div>

             {/* Section 4 — Payment */}
             <div className="p-5">
               <div className="text-[10px] font-extrabold text-[#555] tracking-widest uppercase mb-3">{t('booking.payment')}</div>
               <div className="flex items-start gap-3">
                 <span style={{ fontSize: 15 }}>💵</span>
                 <div>
                   <div className="font-black text-[#F5C518] text-lg">€{totalPrice}</div>
                   <div className="text-xs font-bold text-[#555] mt-0.5">{t('booking.cashOnly')}</div>
                   <div className="text-xs text-[#444] mt-0.5">{t('booking.payDirectly')}</div>
                 </div>
               </div>
             </div>
           </div>

           <button
             onClick={handleConfirm}
             disabled={isSubmitting}
             className="w-full bg-brand-yellow text-[#0a0a0a] py-4 rounded-full font-black text-[15px] transition-all hover:opacity-90 disabled:opacity-50"
           >
             {isSubmitting ? t('booking.confirming') : t('booking.confirmBooking')}
           </button>
           <button
             disabled={isSubmitting}
             onClick={() => setStep(3)}
             className="w-full mt-4 text-[#888] font-bold text-sm hover:text-white transition-colors"
           >
             {t('booking.changeTime')}
           </button>
         </div>
       )}

    </div>
  );
}

imports.text:
import {
  doc, getDoc, setDoc,
  collection, query, where, orderBy, limit, getDocs,
} from 'firebase/firestore';

funcs.text:
export default function ChallengePage() {
  const { user, appUser } = useAuth();
  const router = useRouter();
  const { t, lang } = useLang();

  const { data: settings, isLoading: settingsLoading } = useQuery({
    queryKey: ['challenge_settings'],
    queryFn: async () => {
      const snap = await getDoc(doc(db, 'siteConfig', 'challenge'));
      return snap.exists() ? (snap.data() as ChallengeSettings) : null;
    },
    staleTime: 5 * 60 * 1000,
  });

  const [barberHits, setBarberHits] = useState<any[]>([]);
  const [shopHits, setShopHits] = useState<any[]>([]);
  const [searching, setSearching] = useState(false);

  const [nameSearch, setNameSearch] = useState('');
  const debouncedSearch = useDebounce(nameSearch, 300);

  const [justVotedBarber, setJustVotedBarber] = useState<string | null>(null);
  const [justVotedShop, setJustVotedShop] = useState<string | null>(null);
  const [voting, setVoting] = useState<string | null>(null);

  const [verifyingEmail, setVerifyingEmail] = useState(false);
  // Re-render after auth.currentUser.reload() — context user ref doesn't change.
  const [verifiedTick, setVerifiedTick] = useState(0);

  // Algolia search (on debounced query change)
  useEffect(() => {
    let cancelled = false;
    (async () => {
      setSearching(true);
      try {
        const { results } = await algoliaClient.search({
          requests: [
            { indexName: 'challenge_barbers', query: '', hitsPerPage: 100 },
            { indexName: 'challenge_shops', query: '', hitsPerPage: 100 },
          ],
        });
        if (cancelled) return;

        const barberRaw = ((results[0] as any).hits as any[]) || [];
        const shopRaw = ((results[1] as any).hits as any[]) || [];

        const q = debouncedSearch.trim().toLowerCase();
        const filt = (h: any) =>
          !q || (h.submitterName || '').toLowerCase().includes(q);

        setBarberHits(barberRaw.filter(filt));
        setShopHits(shopRaw.filter(filt));
      } catch {
        if (!cancelled) {
          setBarberHits([]);
          setShopHits([]);
        }
      } finally {
        if (!cancelled) setSearching(false);
      }
    })();
    return () => {
      cancelled = true;
    };
  }, [debouncedSearch]);

  const now = Date.now();
  const phase =
    !settings
      ? 'loading'
      : !settings.votingOpenAt || !settings.votingCloseAt
      ? 'misconfigured'
      : now < settings.submissionsOpenAt
      ? 'preOpen'
      : now < settings.submissionsCloseAt
      ? 'entry'
      : now < settings.votingOpenAt
      ? 'gap'
      : now < settings.votingCloseAt
      ? 'voting'
      : 'closed';

  const leaderboardEnabled =
    phase === 'voting' && !!settings?.publicLeaderboardEnabled;

  const { data: barberLeaderboard = [], isLoading: lbBarberLoading } = useQuery({
    queryKey: ['challenge_leaderboard', 'barber'],
    queryFn: async () => {
      const q = query(
        collection(db, 'challengeSubmissions'),
        where('type', '==', 'barber'),
        where('status', '==', 'approved'),
        orderBy('voteCount', 'desc'),
        limit(20),
      );
      const snap = await getDocs(q);
      return snap.docs.map(d => ({ id: d.id, ...(d.data() as ChallengeSubmission) }));
    },
    staleTime: 5 * 60 * 1000,
    enabled: leaderboardEnabled,
  });

  const { data: shopLeaderboard = [], isLoading: lbShopLoading } = useQuery({
    queryKey: ['challenge_leaderboard', 'shop'],
    queryFn: async () => {
      const q = query(
        collection(db, 'challengeSubmissions'),
        where('type', '==', 'shop'),
        where('status', '==', 'approved'),
        orderBy('voteCount', 'desc'),
        limit(20),
      );
      const snap = await getDocs(q);
      return snap.docs.map(d => ({ id: d.id, ...(d.data() as ChallengeSubmission) }));
    },
    staleTime: 5 * 60 * 1000,
    enabled: leaderboardEnabled,
  });

  const handleShare = useCallback(() => {
    navigator.clipboard.writeText('https://titezme.com/challenge');
    toast.success(t('challenge.public.toastShareCopied'));
  }, [t]);

  const handleResendVerification = useCallback(async () => {
    if (!auth.currentUser) return;
    try {
      await sendEmailVerification(auth.currentUser);
      toast.success(t('challenge.public.toastVerifySent'));
    } catch {
      toast.error(t('challenge.public.toastVerifySendFail'));
    }
  }, [t]);

  const handleVerifyRefresh = useCallback(async () => {
    if (!auth.currentUser) return;
    setVerifyingEmail(true);
    try {
      await auth.currentUser.reload();
      await auth.currentUser.getIdToken(true);
      setVerifiedTick(prev => prev + 1);
      if (auth.currentUser?.emailVerified) {
        toast.success(t('challenge.public.toastVerifyOk'));
      } else {
        toast.error(t('challenge.public.toastVerifyStill'));
      }
    } catch {
      toast.error(t('challenge.public.toastVerifyRefreshFail'));
    } finally {
      setVerifyingEmail(false);
    }
  }, [t]);

  async function handleVote(hit: any, type: 'barber' | 'shop') {
    if (!user) {
      router.push('/signup?next=/challenge');
      return;
    }
    const verifiedNow = auth.currentUser?.emailVerified ?? user.emailVerified;
    if (!verifiedNow) {
      toast.error(t('challenge.public.toastNeedVerify'));
      return;
    }
    if (phase !== 'voting') {
      toast.error(t('challenge.public.toastNotOpen'));
      return;
    }
    setVoting(hit.objectID);
    try {
      await setDoc(doc(db, 'challengeVotes', `${user.uid}_${type}`), {
        voterUid: user.uid,
        type,
        submissionId: hit.objectID,
        votedAt: Date.now(),
      });
      if (type === 'barber') setJustVotedBarber(hit.objectID);
      else setJustVotedShop(hit.objectID);
      toast.success(t('challenge.public.toastVoteOk'));
    } catch (e: any) {
      if (e?.code === 'permission-denied') {
        toast.error(t('challenge.public.toastVoteClosedOrDup'));
      } else {
        toast.error(t('challenge.public.toastVoteFail'));
      }
    } finally {
      setVoting(null);
    }
  }

  // ─── Render branches ─────────────────────────────────────────────────────

  if (settingsLoading || phase === 'loading') {
    return (
      <div className="min-h-[50vh] flex items-center justify-center text-[#666] text-sm">
        {t('challenge.public.loading')}
      </div>
    );
  }

  if (phase === 'misconfigured') {
    return (
      <SimpleMessage
        title={t('challenge.public.misconfTitle')}
        body={t('challenge.public.misconfBody')}
      />
    );
  }

  if (phase === 'preOpen' || phase === 'entry' || phase === 'gap') {
    return <PreVotingScreen settings={settings!} phase={phase} />;
  }

  if (phase === 'closed') {
    const formattedEventDate = settings?.eventDate
      ? new Date(settings.eventDate).toLocaleDateString(
          lang === 'fr' ? 'fr-FR' : lang === 'es' ? 'es-ES' : 'en-GB',
          { day: 'numeric', month: 'long', year: 'numeric' }
        )
      : '17 September 2026';
    return (
      <SimpleMessage
        title={t('challenge.eventClosedTitle')}
        body={`${t('challenge.eventClosedBody')} ${formattedEventDate}.`}
      />
    );
  }

  // ─── phase === 'voting' ──────────────────────────────────────────────────

  const emailVerifiedNow =
    (auth.currentUser?.emailVerified ?? user?.emailVerified) === true;
  // Note: verifiedTick referenced to keep eslint quiet about its purpose.
  void verifiedTick;

  return (
    <div className="bg-[#0a0a0a] text-white min-h-screen">
      <div className="max-w-[1400px] mx-auto px-6 pt-12 pb-16">
        {/* Header */}
        <div className="mb-8">
          <div className="inline-block text-[10px] font-black tracking-[3px] text-brand-orange uppercase mb-4">
            🏆 {t('challenge.public.eyebrow')}
          </div>
          <h1 className="text-3xl md:text-5xl font-black mb-3">
            {t('challenge.public.headerTitle')}
          </h1>
          <p className="text-[#888] text-sm md:text-base">
            {t('challenge.public.votingClosesIn')}{' '}
            <CountdownTimer
              targetMs={settings!.votingCloseAt}
              className="text-brand-yellow font-bold"
            />
          </p>
        </div>

        {/* Share button (visible to all states) */}
        <div className="mb-6">
          <button
            onClick={handleShare}
            className="bg-[#1a1a1a] border border-[#2a2a2a] text-white font-bold text-xs px-4 py-2 rounded-full hover:border-[#444] transition-colors"
          >
            {t('challenge.public.shareBtn')}
          </button>
        </div>

        {/* Auth / verify gate */}
        {!user ? (
          <div className="bg-[#111] border border-[#1e1e1e] rounded-[16px] p-6 mb-8">
            <h2 className="text-lg font-black mb-2">{t('challenge.public.signupTitle')}</h2>
            <p className="text-[#888] text-sm mb-4">
              {t('challenge.public.signupBody')}
            </p>
            <Link
              href="/signup"
              className="inline-block bg-brand-yellow text-[#0a0a0a] font-black text-sm px-5 py-3 rounded-xl hover:bg-brand-yellow/90 transition-colors"
            >
              {t('challenge.public.signupBtn')}
            </Link>
          </div>
        ) : !emailVerifiedNow ? (
          <div className="bg-[#111] border border-[#1e1e1e] rounded-[16px] p-6 mb-8">
            <h2 className="text-lg font-black mb-2">{t('challenge.public.verifyTitle')}</h2>
            <p className="text-[#888] text-sm mb-4">
              {t('challenge.public.verifyBody')
                .split('{email}')
                .flatMap((part, i, arr) =>
                  i < arr.length - 1
                    ? [part, <span key={i} className="text-white font-bold">{user.email}</span>]
                    : [part]
                )}
            </p>
            <div className="flex flex-wrap gap-3">
              <button
                onClick={handleResendVerification}
                className="bg-[#1a1a1a] border border-[#2a2a2a] text-white font-bold text-sm px-4 py-2.5 rounded-xl hover:border-[#444] transition-colors"
              >
                {t('challenge.public.resendBtn')}
              </button>
              <button
                onClick={handleVerifyRefresh}
                disabled={verifyingEmail}
                className="bg-brand-yellow text-[#0a0a0a] font-black text-sm px-4 py-2.5 rounded-xl hover:bg-brand-yellow/90 disabled:opacity-50"
              >
                {verifyingEmail ? t('challenge.public.checkingBtn') : t('challenge.public.refreshBtn')}
              </button>
            </div>
          </div>
        ) : (
          // Signed in + verified → search bar
          <div className="mb-8">
            <input
              value={nameSearch}
              onChange={e => setNameSearch(e.target.value)}
              placeholder={t('challenge.public.searchPlaceholder')}
              className="w-full sm:max-w-md bg-[#111] border border-[#2a2a2a] text-white rounded-xl px-4 py-3 text-sm font-bold outline-none focus:border-brand-yellow transition-colors placeholder:text-[#444]"
            />
            <div className="text-xs text-[#666] mt-2">
              {t('challenge.public.showingCount')
                .replace('{b}', String(barberHits.length))
                .replace('{s}', String(shopHits.length))}
            </div>
          </div>
        )}

        {leaderboardEnabled && !debouncedSearch.trim() ? (
          <>
            <Leaderboard
              title={t('challenge.public.topBarbers')}
              data={barberLeaderboard}
              loading={lbBarberLoading}
              type="barber"
              appUser={appUser}
              justVotedBarber={justVotedBarber}
              justVotedShop={justVotedShop}
              voting={voting}
              canVote={!!user && emailVerifiedNow}
              onVote={handleVote}
            />
            <Leaderboard
              title={t('challenge.public.topShops')}
              data={shopLeaderboard}
              loading={lbShopLoading}
              type="shop"
              appUser={appUser}
              justVotedBarber={justVotedBarber}
              justVotedShop={justVotedShop}
              voting={voting}
              canVote={!!user && emailVerifiedNow}
              onVote={handleVote}
            />
          </>
        ) : (
          <>
            {/* Section: Barbers */}
            <section className="mb-12">
              <h2 className="text-xl font-black mb-4">
                {t('challenge.public.sectionBarbers').replace('{n}', String(barberHits.length))}
              </h2>
              <SubmissionGrid
                hits={barberHits}
                type="barber"
                searching={searching}
                appUser={appUser}
                justVotedBarber={justVotedBarber}
                justVotedShop={justVotedShop}
                voting={voting}
                canVote={!!user && emailVerifiedNow}
                onVote={handleVote}
              />
            </section>

            {/* Section: Barbershops */}
            <section className="mb-12">
              <h2 className="text-xl font-black mb-4">
                {t('challenge.public.sectionShops').replace('{n}', String(shopHits.length))}
              </h2>
              <SubmissionGrid
                hits={shopHits}
                type="shop"
                searching={searching}
                appUser={appUser}
                justVotedBarber={justVotedBarber}
                justVotedShop={justVotedShop}
                voting={voting}
                canVote={!!user && emailVerifiedNow}
                onVote={handleVote}
              />
            </section>
          </>
        )}
      </div>
    </div>
  );
}

async function handleVote(hit: any, type: 'barber' | 'shop') {
    if (!user) {
      router.push('/signup?next=/challenge');
      return;
    }
    const verifiedNow = auth.currentUser?.emailVerified ?? user.emailVerified;
    if (!verifiedNow) {
      toast.error(t('challenge.public.toastNeedVerify'));
      return;
    }
    if (phase !== 'voting') {
      toast.error(t('challenge.public.toastNotOpen'));
      return;
    }
    setVoting(hit.objectID);
    try {
      await setDoc(doc(db, 'challengeVotes', `${user.uid}_${type}`), {
        voterUid: user.uid,
        type,
        submissionId: hit.objectID,
        votedAt: Date.now(),
      });
      if (type === 'barber') setJustVotedBarber(hit.objectID);
      else setJustVotedShop(hit.objectID);
      toast.success(t('challenge.public.toastVoteOk'));
    } catch (e: any) {
      if (e?.code === 'permission-denied') {
        toast.error(t('challenge.public.toastVoteClosedOrDup'));
      } else {
        toast.error(t('challenge.public.toastVoteFail'));
      }
    } finally {
      setVoting(null);
    }
  }

function SimpleMessage({ title, body }: { title: string; body: string }) {
  const { t } = useLang();
  return (
    <div className="min-h-[60vh] flex items-center justify-center px-6 py-20">
      <div className="max-w-[640px] text-center">
        <div className="inline-block text-[10px] font-black tracking-[3px] text-brand-orange uppercase mb-4">
          🏆 {t('challenge.public.eyebrow')}
        </div>
        <h1 className="text-3xl md:text-4xl font-black mb-4">{title}</h1>
        <p className="text-[#888] text-sm mb-8">{body}</p>
        <Link
          href="/"
          className="inline-block bg-brand-yellow text-[#0a0a0a] font-black text-sm px-6 py-3 rounded-xl"
        >
          {t('challenge.public.backHome')}
        </Link>
      </div>
    </div>
  );
}

function SubmissionGrid({
  hits,
  type,
  searching,
  appUser,
  justVotedBarber,
  justVotedShop,
  voting,
  canVote,
  onVote,
}: {
  hits: any[];
  type: 'barber' | 'shop';
  searching: boolean;
  appUser: any;
  justVotedBarber: string | null;
  justVotedShop: string | null;
  voting: string | null;
  canVote: boolean;
  onVote: (hit: any, type: 'barber' | 'shop') => void;
}) {
  const { t } = useLang();
  if (searching && hits.length === 0) {
    return (
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-3">
        {Array.from({ length: 6 }).map((_, i) => (
          <div
            key={i}
            className="bg-[#141414] border border-[#222] rounded-[12px] h-[280px] animate-pulse"
          />
        ))}
      </div>
    );
  }

  if (hits.length === 0) {
    return (
      <div className="bg-[#111] border border-[#1e1e1e] rounded-[12px] p-8 text-center">
        <p className="text-[#666] text-sm">
          {type === 'barber'
            ? t('challenge.public.emptyBarbers')
            : t('challenge.public.emptyShops')}
        </p>
      </div>
    );
  }

  return (
    <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-3">
      {hits.map(hit => {
        const hitType: 'barber' | 'shop' = (hit.type as 'barber' | 'shop') || type;
        const alreadyVotedFromContext =
          hitType === 'barber'
            ? appUser?.challengeVotedForBarber
            : appUser?.challengeVotedForShop;
        const alreadyVotedJust =
          hitType === 'barber' ? justVotedBarber : justVotedShop;
        const userVotedForThis =
          alreadyVotedFromContext === hit.objectID ||
          alreadyVotedJust === hit.objectID;
        const userVotedForOther =
          (!!alreadyVotedFromContext && alreadyVotedFromContext !== hit.objectID) ||
          (!!alreadyVotedJust && alreadyVotedJust !== hit.objectID);

        const baseVoteCount = hit.voteCount || 0;
        const displayVoteCount =
          baseVoteCount + (alreadyVotedJust === hit.objectID ? 1 : 0);

        return (
          <div
            key={hit.objectID}
            className="bg-[#141414] border border-[#222] rounded-[12px] p-[14px] flex flex-col gap-3"
          >
            <div className="flex items-center gap-3">
              {hit.submitterAvatarUrl ? (
                <Image
                  src={hit.submitterAvatarUrl}
                  alt="Barber avatar"
                  width={44}
                  height={44}
                  className="w-11 h-11 rounded-full object-cover bg-[#222]"
                />
              ) : (
                <div className="w-11 h-11 rounded-full bg-[#222] flex items-center justify-center text-[#666] text-sm font-bold">
                  {hit.submitterName?.[0]?.toUpperCase() || '?'}
                </div>
              )}
              <div className="flex-1 min-w-0">
                <div className="font-bold text-white truncate">
                  {hit.submitterName || t('challenge.public.unnamed')}
                </div>
                {hit.submitterCity && (
                  <div className="text-[#888] text-xs truncate">
                    {hit.submitterCity}
                  </div>
                )}
              </div>
            </div>

            {hit.photos?.[0] && (
              <div className="relative w-full aspect-square">
                <Image
                  src={hit.photos[0]}
                  alt="Submission photo"
                  fill
                  className="object-cover rounded-[10px] bg-[#0a0a0a]"
                  sizes="(max-width: 640px) 50vw, (max-width: 1024px) 33vw, 25vw"
                />
              </div>
            )}

            <div className="flex items-center justify-between gap-2 mt-1">
              <div className="text-[#888] text-xs">
                {t('challenge.public.votesCount').replace('{n}', String(displayVoteCount))}
              </div>

              {userVotedForThis ? (
                <span className="text-brand-yellow text-xs font-bold">
                  {t('challenge.public.youVoted')}
                </span>
              ) : userVotedForOther ? (
                <span className="text-[#555] text-xs">{t('challenge.public.alreadyVoted')}</span>
              ) : (
                <button
                  onClick={() => onVote(hit, hitType)}
                  disabled={!canVote || voting === hit.objectID}
                  className="bg-brand-yellow text-[#0a0a0a] font-black text-xs px-3 py-1.5 rounded-lg hover:bg-brand-yellow/90 disabled:opacity-50 disabled:cursor-not-allowed"
                >
                  {voting === hit.objectID ? t('challenge.public.votingBtn') : t('challenge.public.voteBtn')}
                </button>
              )}
            </div>
          </div>
        );
      })}
    </div>
  );
}

function Leaderboard({
  title,
  data,
  loading,
  type,
  appUser,
  justVotedBarber,
  justVotedShop,
  voting,
  canVote,
  onVote,
}: {
  title: string;
  data: LeaderboardItem[];
  loading: boolean;
  type: 'barber' | 'shop';
  appUser: any;
  justVotedBarber: string | null;
  justVotedShop: string | null;
  voting: string | null;
  canVote: boolean;
  onVote: (hit: any, type: 'barber' | 'shop') => void;
}) {
  const { t } = useLang();
  return (
    <section className="mb-12">
      <div className="flex items-center justify-between mb-5">
        <h2 className="text-xl md:text-2xl font-black">{title}</h2>
        <div className="text-[#666] text-xs">
          {t('challenge.public.topN').replace('{n}', String(data.length))}
        </div>
      </div>

      {loading && (
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-3">
          {Array.from({ length: 6 }).map((_, i) => (
            <div
              key={i}
              className="bg-[#141414] border border-[#222] rounded-[12px] h-[280px] animate-pulse"
            />
          ))}
        </div>
      )}

      {!loading && data.length === 0 && (
        <div className="text-[#666] text-sm text-center py-12">
          {type === 'barber' ? t('challenge.public.emptyBarbers') : t('challenge.public.emptyShops')}
        </div>
      )}

      {!loading && data.length > 0 && (
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-3">
          {data.map((sub, idx) => (
            <LeaderboardCard
              key={sub.id}
              submission={sub}
              rank={idx + 1}
              type={type}
              appUser={appUser}
              justVotedBarber={justVotedBarber}
              justVotedShop={justVotedShop}
              voting={voting}
              canVote={canVote}
              onVote={onVote}
            />
          ))}
        </div>
      )}
    </section>
  );
}

function LeaderboardCard({
  submission,
  rank,
  type,
  appUser,
  justVotedBarber,
  justVotedShop,
  voting,
  canVote,
  onVote,
}: {
  submission: LeaderboardItem;
  rank: number;
  type: 'barber' | 'shop';
  appUser: any;
  justVotedBarber: string | null;
  justVotedShop: string | null;
  voting: string | null;
  canVote: boolean;
  onVote: (hit: any, type: 'barber' | 'shop') => void;
}) {
  const { t } = useLang();
  const alreadyVotedFromContext =
    type === 'barber'
      ? appUser?.challengeVotedForBarber
      : appUser?.challengeVotedForShop;
  const alreadyVotedJust =
    type === 'barber' ? justVotedBarber : justVotedShop;
  const userVotedForThis =
    alreadyVotedFromContext === submission.id ||
    alreadyVotedJust === submission.id;
  const userVotedForOther =
    (!!alreadyVotedFromContext && alreadyVotedFromContext !== submission.id) ||
    (!!alreadyVotedJust && alreadyVotedJust !== submission.id);

  const baseVoteCount = submission.voteCount || 0;
  const displayVoteCount =
    baseVoteCount + (alreadyVotedJust === submission.id ? 1 : 0);

  // onVote expects an Algolia-shaped hit (uses hit.objectID). Provide a shim.
  const voteShim = { ...submission, objectID: submission.id };

  return (
    <div className="relative bg-[#141414] border border-[#222] rounded-[12px] p-[14px] flex flex-col gap-3">
      <div className="absolute top-2 left-2 z-10">
        {rank === 1 && <span className="text-2xl">🥇</span>}
        {rank === 2 && <span className="text-2xl">🥈</span>}
        {rank === 3 && <span className="text-2xl">🥉</span>}
        {rank > 3 && (
          <span className="bg-[#1a1a1a] border border-[#2a2a2a] text-[#888] text-xs font-bold px-2 py-1 rounded-md">
            #{rank}
          </span>
        )}
      </div>

      <div className="flex items-center gap-3 pl-10">
        {submission.submitterAvatarUrl ? (
          <Image
            src={submission.submitterAvatarUrl}
            alt="Barber avatar"
            width={44}
            height={44}
            className="w-11 h-11 rounded-full object-cover bg-[#222]"
          />
        ) : (
          <div className="w-11 h-11 rounded-full bg-[#222] flex items-center justify-center text-[#666] text-sm font-bold">
            {submission.submitterName?.[0]?.toUpperCase() || '?'}
          </div>
        )}
        <div className="flex-1 min-w-0">
          <div className="font-bold text-white truncate">
            {submission.submitterName || t('challenge.public.unnamed')}
          </div>
          {submission.submitterCity && (
            <div className="text-[#888] text-xs truncate">
              {submission.submitterCity}
            </div>
          )}
        </div>
      </div>

      {submission.photos?.[0] && (
        <div className="relative w-full aspect-square">
          <Image
            src={submission.photos[0]}
            alt="Submission photo"
            fill
            className="object-cover rounded-[10px] bg-[#0a0a0a]"
            sizes="(max-width: 640px) 50vw, (max-width: 1024px) 33vw, 25vw"
          />
        </div>
      )}

      <div className="flex items-center justify-between gap-2 mt-1">
        <div className="text-brand-orange text-sm font-bold">
          {t('challenge.public.votesCount').replace('{n}', String(displayVoteCount))}
        </div>

        {userVotedForThis ? (
          <span className="text-brand-yellow text-xs font-bold">
            {t('challenge.public.youVoted')}
          </span>
        ) : userVotedForOther ? (
          <span className="text-[#555] text-xs">{t('challenge.public.alreadyVoted')}</span>
        ) : (
          <button
            onClick={() => onVote(voteShim, type)}
            disabled={!canVote || voting === submission.id}
            className="bg-brand-yellow text-[#0a0a0a] font-black text-xs px-3 py-1.5 rounded-lg hover:bg-brand-yellow/90 disabled:opacity-50 disabled:cursor-not-allowed"
          >
            {voting === submission.id ? t('challenge.public.votingBtn') : t('challenge.public.voteBtn')}
          </button>
        )}
      </div>
    </div>
  );
}

