              LIVE NOW
            </div>
            <div style={{
              display: 'grid',
              gridTemplateColumns: 'repeat(auto-fill, minmax(220px, 1fr))',
              gap: '16px',
              marginBottom: '48px'
            }}>
              {liveCities.map((city: any, index: number) => (
                <Link
                  key={city.city}
