  const [form, setForm] = useState(INITIAL_FORM);
  const [prefilled, setPrefilled] = useState(false);

  useEffect(() => {
    if (prefilled) return;
    if (!appUser && !user) return;
    const fullName = [appUser?.firstName, appUser?.lastName].filter(Boolean).join(' ').trim();
    const email = appUser?.email || user?.email || '';
    if (!fullName && !email) return;
    setForm(f => ({
      ...f,
      name: f.name || fullName,
      email: f.email || email,
      role: f.role === 'client' && appUser?.role === 'professional' ? 'professional' : f.role,
    }));
    setPrefilled(true);
  }, [user, appUser, prefilled]);
  const [isSubmitted, setIsSubmitted] = useState(false);
  const [isSending, setIsSending] = useState(false);
  const [error, setError] = useState('');

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (form.honeypot) return;
    if (!form.name.trim() || !form.email.trim() || !form.message.trim()) return;
    setIsSending(true);
    setError('');
    try {
      await addDoc(collection(db, 'contactMessages'), {
        name: form.name.trim().slice(0, 100),
        email: form.email.trim().slice(0, 200),
        role: form.role,
        subject: form.subject,
        message: form.message.trim().slice(0, 2000),
        type: user ? 'support' : 'public',
        createdAt: serverTimestamp(),
        read: false,
      });
      setIsSubmitted(true);
