export default function CreateShopPage() {
  const router = useRouter();
  const { user, appUser, loading } = useAuth();
  const { t } = useLang();
  
  const [name, setName] = useState('');
  
  const [phoneCode, setPhoneCode] = useState<any>(null);
  const [phoneNumberInput, setPhoneNumberInput] = useState("");

  const [selectedCountry, setSelectedCountry] = useState<any>(null);
  const [selectedState, setSelectedState] = useState<any>(null);
  const [selectedCityOption, setSelectedCityOption] = useState<any>(null);

  const [street, setStreet] = useState('');
  const [buildingNumber, setBuildingNumber] = useState('');
  const [postalCode, setPostalCode] = useState('');
  const [floor, setFloor] = useState('');

  const [description, setDescription] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [errorStatus, setErrorStatus] = useState('');
  const [csc, setCsc] = useState<any>(null);

  useEffect(() => { import('country-state-city').then(m => setCsc(m)); }, []);

  const countryOptions = useMemo(() => {
    if (!csc) return [];
    return csc.Country.getAllCountries().map((c: any) => ({ value: c.isoCode, label: `${c.flag} ${c.name}` }));
  }, [csc]);

  const phoneCodeOptions = useMemo(() => {
    if (!csc) return [];
    return csc.Country.getAllCountries().map((c: any) => ({ value: c.phonecode, label: `${c.flag} ${c.name} (+${c.phonecode})` }));
  }, [csc]);

  const selectStyles = {
    control: (base: any, state: any) => ({
      ...base,
      background: '#0a0a0a',
      borderColor: state.isFocused ? '#FFD700' : '#2a2a2a',
      borderRadius: '0.75rem',
      padding: '2px',
      color: 'white',
      boxShadow: 'none',
      '&:hover': {
        borderColor: state.isFocused ? '#FFD700' : '#2a2a2a',
      }
    }),
    menu: (base: any) => ({
      ...base,
      background: '#141414',
      border: '1.5px solid #2a2a2a',
      borderRadius: '0.75rem',
      overflow: 'hidden',
      zIndex: 50
    }),
    option: (base: any, state: any) => ({
      ...base,
      backgroundColor: state.isFocused ? '#2a2a2a' : '#141414',
      color: 'white',
      cursor: 'pointer',
      '&:hover': {
        backgroundColor: '#2a2a2a'
      }
    }),
    singleValue: (base: any) => ({
      ...base,
      color: 'white'
    }),
    input: (base: any) => ({
      ...base,
      color: 'white'
    }),
    placeholder: (base: any) => ({
      ...base,
      color: '#444'
    }),
  };

  const googleMapsUrl = useMemo(() => {
    if (!street || !buildingNumber || !postalCode || !selectedCityOption || !selectedCountry) return '';
    const query = `${street} ${buildingNumber} ${postalCode} ${selectedCityOption.value} ${selectedCountry.label.replace(/[\uD800-\uDBFF][\uDC00-\uDFFF]\s*/g, '')}`;
    return `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(query)}`;
  }, [street, buildingNumber, postalCode, selectedCityOption, selectedCountry]);

  if (loading) return null;

  if (!user || appUser?.role !== 'professional') {
    router.replace('/');
    return null;
  }

  if (appUser?.ownsShop) {
    router.replace('/dashboard/shop');
    return null;
  }

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!name || !phoneCode || !phoneNumberInput || !selectedCountry || !selectedCityOption || !street || !buildingNumber || !postalCode) {
      setErrorStatus(t('errors.fillRequiredFields'));
      return;
    }

    setIsSubmitting(true);
    setErrorStatus('');

    try {
      const shopRef = doc(db, 'businesses', user.uid);
      await setDoc(shopRef, businessSchema.parse({
              ownerId: user.uid,
              type: 'barbershop',
              name: sanitizeText(name, 100),
              contactPhone: `+${phoneCode.value} ${phoneNumberInput}`,
              address: {
                street: street,
                buildingNumber: buildingNumber,
                postalCode: postalCode,
                floor: floor || '',
                city: selectedCityOption.value,
                ...(selectedState ? { state: selectedState.value } : {}),
                country: selectedCountry.value
              },
              googleMapsUrl: sanitizeUrl(googleMapsUrl),
              description: sanitizeText(description, 2000),
              photos: [],
              videos: [],
              amenities: [],
              currency: 'EUR',
              status: 'inactive',
              createdAt: Date.now()
            }));

      const userRef = doc(db, 'users', user.uid);
      await updateDoc(userRef, userUpdateSchema.parse({
              ownsShop: true
            }));

      const profileRef = doc(db, 'professionalProfiles', user.uid);
      await updateDoc(profileRef, professionalProfileUpdateSchema.parse({
              ownsBusiness: true,
              businessId: user.uid
            }));

      router.push('/dashboard/shop');
    } catch (err: any) {
      console.error("Error creating shop", err);
      setErrorStatus(err.message || t('errors.failedCreateShop'));
      setIsSubmitting(false);
    }
  };

  return (
    <div className="min-h-[calc(100vh-53px)] bg-[#0a0a0a] flex items-center justify-center p-6 pb-20">
      <div className="w-full max-w-lg bg-[#141414] border border-[#2a2a2a] rounded-3xl p-8 shadow-2xl relative overflow-hidden">
        
        {/* Decorative Blob */}
        <div className="absolute top-0 right-0 w-64 h-64 bg-brand-yellow/10 rounded-full blur-3xl -translate-y-1/2 translate-x-1/3 pointer-events-none" />

        <div className="flex items-center gap-4 mb-8">
          <Link href="/dashboard/barber" className="w-10 h-10 rounded-full bg-[#1a1a1a] flex items-center justify-center text-[#888] hover:text-white transition-colors">
            ←
          </Link>
          <div>
            <h1 className="text-2xl font-black text-white leading-tight">{t('barberLayout.createShopProfile')}</h1>
            <p className="text-[#888] text-sm mt-1">{t('forms.createShopSubtitle')}</p>
          </div>
        </div>

        <form onSubmit={handleSubmit} className="flex flex-col gap-5 relative z-10">
          <div>
            <label className="text-[11px] font-extrabold text-brand-text-secondary block mb-1.5">{t('forms.shopName')} <span className="text-brand-red">*</span></label>
            <input
              required
              value={name} onChange={e => setName(e.target.value)}
              maxLength={100}
              className="w-full bg-[#0a0a0a] border border-[#2a2a2a] rounded-xl px-4 py-3 text-white text-sm outline-none transition-colors focus:border-brand-yellow"
              placeholder={t('forms.shopNamePlaceholder')}
            />
          </div>

          <div>
            <label className="text-[11px] font-extrabold text-brand-text-secondary block mb-1.5">{t('forms.contactPhone')} <span className="text-brand-red">*</span></label>
            <div className="flex gap-2">
              <div className="flex-none w-1/3">
                <Select 
                  options={phoneCodeOptions} 
                  value={phoneCode}
                  onChange={setPhoneCode}
                  styles={selectStyles}
                  placeholder={t('forms.codePlaceholder')}
                />
              </div>
              <div className="flex-1">
                <input 
                  type="text"
                  inputMode="numeric"
                  value={phoneNumberInput}
