function timeAgo(ts: number, t: (k: string) => string): string {
  const diff = Date.now() - ts;
  const days = Math.floor(diff / 86400000);
  if (days === 0) return t('buttons.today');
  if (days === 1) return t('settings.yesterday');
  if (days < 30) return t('misc.daysAgo').replace('{n}', String(days));
  const months = Math.floor(days / 30);
  if (months < 12) return t('shopDash.monthsAgo').replace('{n}', String(months));
  return t('shopDash.yearsAgo').replace('{n}', String(Math.floor(months / 12)));
}

export default function ClientReviews() {
  const { user } = useAuth();
  const { t } = useLang();
  const [visibleCount, setVisibleCount] = useState(10);

  const { data: reviews = [], isLoading } = useQuery<EnrichedReview[]>({
    queryKey: ['clientReviews', user?.uid],
    queryFn: async () => {
      if (!user) return [];
      const snap = await getDocs(query(
        collection(db, 'reviews'),
        where('clientId', '==', user.uid)
      ));
      const raw = snap.docs.map(d => ({ id: d.id, ...(d.data() as any) })) as EnrichedReview[];

      const enriched = await Promise.all(raw.map(async (r) => {
        try {
          if (r.providerType === 'shop') {
            const s = await getDoc(doc(db, 'businesses', r.providerId));
            if (!s.exists()) return { ...r, providerMissing: true };
            const data = s.data() as any;
            return {
              ...r,
              providerName: data.name,
              providerPhoto: data.logoUrl || data.coverPhotoUrl,
            };
          } else {
            const p = await getDoc(doc(db, 'professionalProfiles', r.providerId));
            if (!p.exists()) return { ...r, providerMissing: true };
            const data = p.data() as any;
            const name = `${data.firstName || ''} ${data.lastName || ''}`.trim();
            return {
              ...r,
              providerName: name || undefined,
              providerPhoto: data.profilePhotoUrl || data.photoUrl,
            };
          }
        } catch {
          return { ...r, providerMissing: true };
        }
      }));

      enriched.sort((a, b) => (b.createdAt || 0) - (a.createdAt || 0));
      return enriched;
    },
    enabled: !!user,
  });

  if (isLoading) {
    return <div className="p-10 text-center animate-pulse text-brand-text-secondary">{t('misc.loading')}</div>;
  }

  return (
    <div className="animate-fadeUp p-6 md:p-8 md:px-10 max-w-[800px]">
      <h2 className="text-2xl font-black mb-6">{t('clientDash.reviewsTitle')}</h2>

      {reviews.length === 0 ? (
        <div className="bg-brand-surface border border-brand-border rounded-2xl p-8 text-center">
          <div className="text-lg font-black text-white mb-2">{t('clientDash.noReviewsWrittenYet')}</div>
          <div className="text-sm font-bold text-brand-text-secondary">{t('clientDash.bookToWriteReview')}</div>
        </div>
      ) : (
        <>
          <div className="flex flex-col gap-3">
            {reviews.slice(0, visibleCount).map(r => {
              const fallbackLabel = r.providerType === 'shop'
                ? t('clientDash.shopNoLongerAvailable')
                : t('clientDash.barberNoLongerAvailable');
              const displayName = r.providerMissing || !r.providerName ? fallbackLabel : r.providerName;
              const initial = (r.providerName || '?')[0]?.toUpperCase() || '?';

              return (
                <div key={r.id} className="bg-brand-surface border border-brand-border rounded-2xl p-4">
                  <div className="flex items-start gap-3 mb-2">
                    {r.providerPhoto ? (
                      <Image
                        src={r.providerPhoto}
                        alt={displayName}
                        width={36}
                        height={36}
                        className="w-9 h-9 rounded-xl object-cover shrink-0"
                        style={{ objectFit: 'cover' }}
                        referrerPolicy="no-referrer"
                      />
                    ) : (
                      <div className="w-9 h-9 rounded-xl bg-[#1a1a1a] border border-[#2a2a2a] flex items-center justify-center font-black text-sm text-white shrink-0">
                        {initial}
                      </div>
                    )}
                    <div className="flex-1 min-w-0">
                      <div className={`font-extrabold text-[14px] truncate ${r.providerMissing ? 'text-[#666]' : 'text-white'}`}>
                        {t('clientDash.reviewFor').replace('{name}', displayName)}
                      </div>
                      <div className="flex items-center gap-2 mt-0.5">
                        <span className="text-brand-yellow text-xs">{'★'.repeat(r.rating || 0)}</span>
                        <span className="text-[10px] text-[#555]">{timeAgo(r.createdAt, t)}</span>
                      </div>
                    </div>
                  </div>
                  {r.comment && (
                    <p className="text-[13px] text-[#aaa] italic leading-relaxed pl-12">&ldquo;{r.comment}&rdquo;</p>
                  )}
                </div>
              );
            })}
          </div>

          {reviews.length > visibleCount && (
            <div className="text-center mt-5">
              <button
                onClick={() => setVisibleCount(v => v + 10)}
                className="text-[13px] font-bold text-brand-yellow border border-brand-yellow/40 hover:bg-[#1a1500] px-6 py-2.5 rounded-full transition-colors"
              >
                {t('profile.loadMoreReviews')}
              </button>
            </div>
          )}
        </>
      )}
    </div>
  );
}

export default function ClientSettings() {
  const { user, appUser, loading, refreshUser } = useAuth();
  const { t } = useLang();

  const [firstName, setFirstName] = useState('');
  const [lastName, setLastName] = useState('');
  const [selectedCountry, setSelectedCountry] = useState<any>(null);
  const [selectedState, setSelectedState] = useState<any>(null);
  const [selectedCityOption, setSelectedCityOption] = useState<any>(null);
  const [phoneCode, setPhoneCode] = useState<any>(null);
  const [phoneNumberInput, setPhoneNumberInput] = useState('');
  const [selectedLanguages, setSelectedLanguages] = useState<any>([]);

  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isUploading, setIsUploading] = useState(false);
  const [errorMsg, setErrorMsg] = useState('');
  const [csc, setCsc] = useState<any>(null);
  const [languageOptions, setLanguageOptions] = useState<{value: string; label: string}[]>([]);

  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (appUser) {
      setFirstName(appUser.firstName || '');
      setLastName(appUser.lastName || '');

      if (appUser.phoneCountryCode) {
        setPhoneCode({ value: appUser.phoneCountryCode, label: `+${appUser.phoneCountryCode}` });
      }
      if (appUser.phone) {
        // Strip the country code prefix to get the raw input
        const codeLen = appUser.phoneCountryCode ? appUser.phoneCountryCode.length + 2 : 0;
        const rawPhone = appUser.phone.slice(codeLen).trim();
        setPhoneNumberInput(rawPhone);
      }

      if (appUser.country) {
        // Pre-populate on next tick after csc loads
        import('country-state-city').then(({ Country: C }) => {
          const c = C.getCountryByCode(appUser.country!);
          if (c) setSelectedCountry({ value: c.isoCode, label: `${c.flag} ${c.name}` });
        });
      }
      if (appUser.city) {
        setSelectedCityOption({ value: appUser.city, label: appUser.city });
      }
      if (appUser.languages && appUser.languages.length > 0) {
        setSelectedLanguages(appUser.languages.map((l: string) => ({ value: l, label: l })));
      }
    }
  }, [appUser]);

  useEffect(() => { import('country-state-city').then(m => setCsc(m)); }, []);
  useEffect(() => { getLanguageOptions().then(setLanguageOptions); }, []);

  const countryOptions = useMemo(() => {
    if (!csc) return [];
    return csc.Country.getAllCountries().map((c: any) => ({ value: c.isoCode, label: `${c.flag} ${c.name}` }));
  }, [csc]);

  const phoneCodeOptions = useMemo(() => {
    if (!csc) return [];
    return csc.Country.getAllCountries().map((c: any) => ({ value: c.phonecode, label: `${c.flag} ${c.name} (+${c.phonecode})` }));
  }, [csc]);


  const selectStyles = {
    control: (base: any, state: any) => ({
      ...base,
      background: '#141414',
      borderColor: state.isFocused ? '#FFD700' : '#2a2a2a',
      borderRadius: '0.75rem',
      padding: '2px',
      color: 'white',
      boxShadow: 'none',
      '&:hover': {
        borderColor: state.isFocused ? '#FFD700' : '#2a2a2a',
      }
    }),
    menu: (base: any) => ({
      ...base,
      background: '#141414',
      border: '1.5px solid #2a2a2a',
      borderRadius: '0.75rem',
      overflow: 'hidden',
      zIndex: 50
    }),
    option: (base: any, state: any) => ({
      ...base,
      backgroundColor: state.isFocused ? '#2a2a2a' : '#141414',
      color: 'white',
      cursor: 'pointer',
      '&:hover': {
        backgroundColor: '#2a2a2a'
      }
    }),
    singleValue: (base: any) => ({
      ...base,
      color: 'white'
    }),
    multiValue: (base: any) => ({
      ...base,
      backgroundColor: '#2a2a2a',
      borderRadius: '6px'
    }),
    multiValueLabel: (base: any) => ({
      ...base,
      color: 'white'
    }),
    multiValueRemove: (base: any) => ({
      ...base,
      color: '#888',
      cursor: 'pointer',
      '&:hover': {
        color: '#FFD700',
        backgroundColor: 'transparent'
      }
    }),
    input: (base: any) => ({
      ...base,
      color: 'white'
    }),
    placeholder: (base: any) => ({
      ...base,
      color: '#444'
    }),
  };

  const handleSave = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!user || !appUser) return;

    if (!firstName.trim() || !lastName.trim()) {
      setErrorMsg(t('settings.firstLastRequired'));
      return;
    }

    setIsSubmitting(true);
    setErrorMsg('');

    try {
      const updateData: any = {
        firstName: sanitizeText(firstName.trim(), 100),
        lastName: sanitizeText(lastName.trim(), 100)
      };

      if (phoneCode && phoneNumberInput) {
        updateData.phone = `+${phoneCode.value} ${phoneNumberInput}`;
        updateData.phoneCountryCode = phoneCode.value;
      }
      if (selectedCountry) updateData.country = selectedCountry.value;
      if (selectedState) updateData.state = selectedState.value;
      if (selectedCityOption) updateData.city = selectedCityOption.value;
      if (selectedLanguages.length > 0) {
        updateData.languages = selectedLanguages.map((l: any) => l.value);
      }

      await updateDoc(doc(db, 'users', user.uid), userUpdateSchema.parse(updateData));
      await refreshUser();
      toast.success(t('settings.profileUpdated'));
    } catch (err: any) {
      console.error(err);
      toast.error(t('settings.failedToSave'));
    } finally {
      setIsSubmitting(false);
    }
  };

  const handlePhotoUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file || !user) return;

    const validTypes = ['image/jpeg', 'image/png', 'image/webp'];
    if (!validTypes.includes(file.type)) {
      toast.error(t('settings.invalidImageClient'));
      return;
    }
    if (file.size > 5 * 1024 * 1024) {
      toast.error(t('settings.fileSizeLimit'));
      return;
    }

    setIsUploading(true);
    const toastId = toast.loading(t('settings.uploadingPhoto'));

    try {
      const storage = getStorage();
      const photoRef = ref(storage, `profile-photos/${user.uid}/profile.jpg`);
      await uploadBytes(photoRef, file);
      const url = await getDownloadURL(photoRef);

      await updateDoc(doc(db, 'users', user.uid), userUpdateSchema.parse({ photoUrl: url }));
      await refreshUser();
      toast.success(t('settings.photoUploaded'), { id: toastId });
    } catch (err) {
      console.error(err);
      toast.error(t('errors.uploadFailed'), { id: toastId });
    } finally {
      setIsUploading(false);
    }
  };

  if (loading) return <div className="p-10 text-center animate-pulse text-brand-text-secondary">{t('misc.loading')}</div>;

  return (
    <div className="p-6 md:p-8 md:px-10">
      <div className="animate-fadeUp max-w-[700px]">
          <h2 className="text-2xl font-black mb-6">{t('clientDash.settings')}</h2>

          <div className="bg-brand-surface border border-brand-border rounded-2xl p-6 mb-8">
            <h3 className="font-bold text-lg mb-4">{t('forms.profilePhoto')}</h3>
            <div className="flex items-center gap-6">
              {appUser?.photoUrl ? (
                <Image 
                  src={appUser.photoUrl} 
                  alt="Profile" 
                  width={80} 
                  height={80} 
                  className="w-20 h-20 rounded-full object-cover border-2 border-[#2a2a2a]" 
                  style={{ objectFit: 'contain' }} 
                />
              ) : (
                <div className="w-20 h-20 rounded-full bg-gradient-to-br from-[#2a2a2a] to-[#111] flex items-center justify-center font-black text-2xl text-white border-2 border-[#2a2a2a]">
                  {appUser?.firstName?.[0] || "C"}
                </div>
              )}
              <div>
                <input 
                  type="file" 
                  accept="image/jpeg, image/png, image/webp" 
                  className="hidden" 
                  ref={fileInputRef}
                  onChange={handlePhotoUpload}
                />
                <div className="flex items-center gap-2 px-4 py-2 rounded-xl text-sm font-bold bg-[#1a1a1a] border border-[#2a2a2a] text-[#555] cursor-not-allowed select-none">
                  {t('status.comingSoon')}
                </div>
                <div className="text-xs text-[#888] mt-2 font-bold">{t('settings.fileTypeHint')}</div>
              </div>
            </div>
          </div>

          <form onSubmit={handleSave} className="bg-brand-surface border border-brand-border rounded-2xl p-6 mb-8 flex flex-col gap-5">
            <h3 className="font-bold text-lg mb-2">{t('headings.personalInfo')}</h3>

            <div className="grid grid-cols-2 gap-3">
              <div>
                <label className="text-[11px] font-extrabold text-brand-text-secondary block mb-1.5">{t('forms.firstName').toUpperCase()} <span className="text-brand-red">*</span></label>
                <input 
                  type="text"
                  value={firstName}
                  onChange={e => setFirstName(e.target.value)}
                  maxLength={100}
                  className="w-full bg-[#141414] border-[1.5px] border-[#2a2a2a] rounded-xl px-4 py-3 text-white text-sm outline-none transition-colors focus:border-brand-yellow placeholder:text-[#444] h-[52px]" 
                />
              </div>
              <div>
                <label className="text-[11px] font-extrabold text-brand-text-secondary block mb-1.5">{t('forms.lastName').toUpperCase()} <span className="text-brand-red">*</span></label>
                <input 
                  type="text"
                  value={lastName}
                  onChange={e => setLastName(e.target.value)}
                  maxLength={100}
                  className="w-full bg-[#141414] border-[1.5px] border-[#2a2a2a] rounded-xl px-4 py-3 text-white text-sm outline-none transition-colors focus:border-brand-yellow placeholder:text-[#444] h-[52px]" 
                />
              </div>
            </div>

            <div>
              <label className="text-[11px] font-extrabold text-brand-text-secondary block mb-1.5">{t('forms.phone').toUpperCase()}</label>
              <div className="flex gap-2">
                <div className="flex-none w-[120px]">
                  <Select 
                    options={phoneCodeOptions} 
                    value={phoneCode}
                    onChange={setPhoneCode}
                    styles={{
                      ...selectStyles, 
                      control: (base: any, state: any) => ({
                        ...base,
                        background: '#141414',
                        borderColor: state.isFocused ? '#FFD700' : '#2a2a2a',
                        borderRadius: '0.75rem',
                        padding: '2px',
                        color: 'white',
                        boxShadow: 'none',
                        minHeight: '52px'
                      })
                    }}
                    placeholder={t('forms.codePlaceholder')}
                  />
                </div>
                <div className="flex-1">
                  <input 
                    type="text"
                    inputMode="numeric"
                    value={phoneNumberInput}
                    onChange={e => setPhoneNumberInput(e.target.value.replace(/\D/g, ''))}
                    maxLength={20}
                    className="w-full bg-[#141414] border-[1.5px] border-[#2a2a2a] rounded-xl px-4 py-3 text-white text-sm outline-none transition-colors focus:border-brand-yellow placeholder:text-[#444] h-[52px]"
                    placeholder={t('forms.phonePlaceholder')}
                  />
                </div>
              </div>
            </div>

            <div>
              <label className="text-[11px] font-extrabold text-brand-text-secondary block mb-1.5">{t('onboarding.location')}</label>
              <div className="grid grid-cols-3 gap-3">
                <div>
                  <Select
                    options={countryOptions}
                    value={selectedCountry}
                    onChange={(option: any) => {
                      setSelectedCountry(option);
                      setSelectedState(null);
                      setSelectedCityOption(null);
                    }}
                    styles={{
                      ...selectStyles,
                      control: (base: any, state: any) => ({
                        ...base,
                        background: '#141414',
                        borderColor: state.isFocused ? '#FFD700' : '#2a2a2a',
                        borderRadius: '0.75rem',
                        padding: '8px',
                        color: 'white',
                        boxShadow: 'none',
                      })
                    }}
                    placeholder={t('forms.countryPlaceholder')}
                  />
                </div>
                <div>
                  <Select
                    options={selectedCountry && csc ?
                      (csc.State.getStatesOfCountry(selectedCountry.value) ?? []).map((s: any) => ({
                        value: s.isoCode,
                        label: s.name
                      }))
                      : []
                    }
                    value={selectedState}
                    onChange={(option: any) => {
                      setSelectedState(option);
                      setSelectedCityOption(null);
                    }}
                    isDisabled={!selectedCountry || !csc}
                    isLoading={!csc}
                    styles={{
                      ...selectStyles,
                      control: (base: any, state: any) => ({
                        ...base,
                        background: '#141414',
                        borderColor: state.isFocused ? '#FFD700' : '#2a2a2a',
                        borderRadius: '0.75rem',
                        padding: '8px',
                        color: 'white',
                        boxShadow: 'none',
                      })
                    }}
                    placeholder="Region..."
                  />
                </div>
                <div>
                  <Select
                    options={selectedCountry && csc ?
                      (csc.City.getCitiesOfCountry(selectedCountry.value) ?? []).map((c: any) => ({
                        value: c.name,
                        label: c.name
                      })) || [] 
                      : []
                    } 
                    value={selectedCityOption}
                    onChange={setSelectedCityOption}
                    isDisabled={!selectedCountry}
                    styles={{
                      ...selectStyles,
                      control: (base: any, state: any) => ({
                        ...base,
                        background: '#141414',
                        borderColor: state.isFocused ? '#FFD700' : '#2a2a2a',
                        borderRadius: '0.75rem',
                        padding: '8px',
                        color: 'white',
                        boxShadow: 'none',
                      })
                    }}
                    placeholder={t('forms.cityPlaceholder')}
                  />
                </div>
              </div>
            </div>

            <div>
               <label className="text-[11px] font-extrabold text-brand-text-secondary block mb-1.5">{t('onboarding.languagesSpoken')}</label>
               <Select 
                  isMulti
                  options={languageOptions} 
                  value={selectedLanguages}
                  onChange={setSelectedLanguages}
                  styles={{
                    ...selectStyles,
                    control: (base: any, state: any) => ({
                      ...base,
                      background: '#141414',
                      borderColor: state.isFocused ? '#FFD700' : '#2a2a2a',
                      borderRadius: '0.75rem',
                      padding: '8px',
                      color: 'white',
                      boxShadow: 'none',
                    })
                  }}
                  placeholder={t('misc.selectLanguages')}
               />
            </div>

            {errorMsg && (
              <div className="bg-[#1a0808] border border-[#3b1a1a] text-brand-red rounded-xl px-4 py-3 text-xs font-bold leading-tight">
                {errorMsg}
              </div>
            )}

            <button 
              type="submit" 
              disabled={isSubmitting}
              className="bg-brand-yellow text-black mt-2 px-7 py-3.5 rounded-full font-black text-sm transition-all hover:opacity-90 disabled:opacity-50 self-start"
            >
              {isSubmitting ? t('settings.saving') : t('settings.saveChanges')}
            </button>
          </form>

          <div className="bg-[#1a0808] border border-brand-red/30 rounded-2xl p-6">
            <h3 className="font-bold text-lg text-brand-red mb-2">{t('headings.deleteAccount')}</h3>
            <p className="text-[#888] text-sm mb-6 max-w-sm font-bold">
              {t('settings.deleteClientDesc')}
            </p>
            <div className="inline-block">
              {/* Wrapping inside a container to stylize identically to DeleteAccountButton if necessary or let DeleteAccountButton handle itself */}
              <DeleteAccountButton role="client" />
            </div>
          </div>

        </div>
      </div>
    );
}

export default function ClientTitizaPage() {
  const { appUser, user } = useAuth();
  const firstName = appUser?.firstName?.trim() || 'there';

  const [phase, setPhase] = useState<Phase>('loading');
  // Captured once, on the first decision: was this a returning user on load?
  // Stays false for the whole genesis → Let's Begin → dashboard flow, so the
  // greeting reads "Hi" (not "Welcome back") right after a first meeting.
  const isReturningRef = useRef(false);
  const decidedRef = useRef(false);

  useEffect(() => {
    if (decidedRef.current) return;
    if (!appUser) return; // wait until the user document is available
    decidedRef.current = true;

    const hasMet = !!appUser.titiza?.hasMet;
    const phase2 = isTitizaPhase2Enabled(user?.uid);
    if (hasMet) {
      isReturningRef.current = true;
      // Flagged users land on the Phase 2 decision surface; everyone else keeps
      // the Phase 1 dashboard block (behavior unchanged when the flag is off).
      setPhase(phase2 ? 'phase2' : 'dashboard');
      if (user?.uid) touchTitizaVisit(user.uid); // bump lastVisitAt (once)
    } else {
      setPhase('genesis');
    }
  }, [appUser, user]);

  const handleBegin = useCallback(() => {
    if (user?.uid) markTitizaMet(user.uid);
    // Behind the flag, "Let's Begin" transitions into the decision flow instead
    // of the Phase 1 dashboard block. In-place cross-fade — no route change.
    setPhase(isTitizaPhase2Enabled(user?.uid) ? 'phase2' : 'dashboard');
  }, [user]);

  const showDashboard = phase === 'dashboard';
  const showPhase2 = phase === 'phase2';

  return (
    <div className={`${cormorant.variable} relative min-h-full overflow-hidden`}>
      <AmbientBackground />

      {phase !== 'loading' && (
        <div className="mx-auto flex w-full max-w-3xl flex-col gap-20 px-6 pb-28 pt-16 sm:gap-24 sm:pt-24">
          {showPhase2 ? (
            <TitizaDecisionFlow userName={firstName} />
          ) : (
            <>
              <TitizaHero
                userName={firstName}
                mode={showDashboard ? 'dashboard' : 'genesis'}
                isReturning={isReturningRef.current}
                onBegin={handleBegin}
              />

              {showDashboard && (
                <div className="flex flex-col gap-20 animate-titiza-fade-in sm:gap-24">
                  <BeautyProfileCard />

                  <section className="flex flex-col gap-8">
                    <div className="text-center">
                      <p className="text-xs font-medium uppercase tracking-[0.3em] text-gold-muted">
                        The Titiza Experience
                      </p>
                    </div>
                    <FeatureCards />
                  </section>
                </div>
              )}
            </>
          )}
        </div>
      )}
    </div>
  );
}

