function getCurrencySymbol(c?: string): string {
  const m: Record<string, string> = { EUR: '€', GBP: '£', USD: '$', MAD: 'MAD ', DZD: 'DA ' };
  return m[(c || 'EUR').toUpperCase()] ?? '€';
}

function fmtMoney(n: number, sym: string) {
  return `${sym}${n.toLocaleString('en-US', { minimumFractionDigits: 0, maximumFractionDigits: 0 })}`;
}

function exportCSV(rows: any[], currSym: string, monthLabel: string) {
  const header = ['Barber', 'Cuts', 'Hours', 'Earned', 'Avg/cut'];
  const data = rows.map(r => [
    r.name, r.cuts, r.hours.toFixed(1),
    `${currSym}${r.earned.toFixed(2)}`,
    r.cuts > 0 ? `${currSym}${(r.earned / r.cuts).toFixed(2)}` : '—',
  ]);
  const csv = [header, ...data].map(r => r.map(v => `"${String(v).replace(/"/g, '""')}"`).join(',')).join('\n');
  const blob = new Blob([csv], { type: 'text/csv' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url; a.download = `earnings-${monthLabel}.csv`; a.click();
  URL.revokeObjectURL(url);
}

export default function ShopEarningsPage() {
  const { user, loading } = useAuth();
  const router = useRouter();
  const { t, lang } = useLang();

  const [bookings, setBookings] = useState<any[]>([]);
  const [barbers, setBarbers] = useState<any[]>([]);
  const [barberNames, setBarberNames] = useState<Record<string, string>>({});
  const [shopCurrency, setShopCurrency] = useState('EUR');

  // Month selector — last 6 months
  const monthOptions = useMemo(() => {
    const opts: { value: string; label: string }[] = [];
    const d = new Date();
    for (let i = 0; i < 6; i++) {
      const yr = d.getFullYear();
      const mo = d.getMonth();
      const value = `${yr}-${String(mo + 1).padStart(2, '0')}`;
      const locale = lang === 'fr' ? 'fr-FR' : lang === 'es' ? 'es-ES' : 'en-US';
      const label = d.toLocaleDateString(locale, { month: 'long', year: 'numeric' });
      opts.push({ value, label });
      d.setMonth(mo - 1);
    }
    return opts;
  }, [lang]);

  const [selectedMonth, setSelectedMonth] = useState(monthOptions[0].value);
  const selectedMonthLabel = monthOptions.find(o => o.value === selectedMonth)?.label || selectedMonth;
  const currentYear = new Date().getFullYear().toString();

  useEffect(() => {
    if (!loading && !user) router.replace('/login');
  }, [user, loading, router]);

  // Fetch shop info
  useEffect(() => {
    if (!user) return;
    getDoc(doc(db, 'businesses', user.uid)).then(s => {
      if (s.exists()) setShopCurrency(s.data().currency || 'EUR');
    });
  }, [user]);

  // Real-time bookings
  useEffect(() => {
    if (!user) return;
    const q = query(collection(db, 'bookings'), where('shopId', '==', user.uid));
    const unsub = onSnapshot(q, snap => {
      setBookings(snap.docs.map(d => ({ id: d.id, ...d.data() } as any)));
    });
    return () => unsub();
  }, [user]);

  // Active barbers
  useEffect(() => {
    if (!user) return;
    const q = query(collection(db, 'professionalProfiles'), where('businessId', '==', user.uid));
    const unsub = onSnapshot(q, async snap => {
      const list = snap.docs.map(d => ({ id: d.id, ...d.data() } as any));
      setBarbers(list);
      // Fetch names
      const names: Record<string, string> = {};
      await Promise.all(list.map(async (b: any) => {
        const uSnap = await getDoc(doc(db, 'users', b.userId || b.id));
        if (uSnap.exists()) {
          const u = uSnap.data();
          names[b.id] = `${u.firstName} ${u.lastName}`;
        }
      }));
      setBarberNames(names);
    });
    return () => unsub();
  }, [user]);

  const currSym = getCurrencySymbol(shopCurrency);

  // ── Derived stats ──────────────────────────────────────────────────────────
  const monthlyCompleted = useMemo(() =>
    bookings.filter(b => b.status === 'completed' && b.date?.startsWith(selectedMonth)),
    [bookings, selectedMonth]
  );

  const yearlyCompleted = useMemo(() =>
    bookings.filter(b => b.status === 'completed' && b.date?.startsWith(currentYear)),
    [bookings, currentYear]
  );

  const monthRevenue = monthlyCompleted.reduce((s, b) => s + (b.price || 0), 0);
  const yearRevenue = yearlyCompleted.reduce((s, b) => s + (b.price || 0), 0);
  const monthCuts = monthlyCompleted.length;
  const avgPerCut = monthCuts > 0 ? monthRevenue / monthCuts : 0;

  // ── Per-barber breakdown ───────────────────────────────────────────────────
  const barberRows = useMemo(() => {
    return barbers.map(b => {
      const completedB = monthlyCompleted.filter(bk => bk.barberId === b.id);
      const earned = completedB.reduce((s, bk) => s + (bk.price || 0), 0);
      const hours = completedB.reduce((s, bk) => s + (bk.totalDuration || 0), 0) / 60;
      return {
        id: b.id,
        name: barberNames[b.id] || t('misc.barberFallback'),
        cuts: completedB.length,
        hours,
        earned,
      };
    }).sort((a, b) => b.earned - a.earned);
  }, [barbers, monthlyCompleted, barberNames]);

  const topEarnerId = barberRows[0]?.id;

  // ── Daily earnings chart ───────────────────────────────────────────────────
  const dailyChartData = useMemo(() => {
    const [yr, mo] = selectedMonth.split('-').map(Number);
    const daysInMonth = new Date(yr, mo, 0).getDate();
    return Array.from({ length: daysInMonth }, (_, i) => {
      const day = i + 1;
      const dayStr = `${selectedMonth}-${String(day).padStart(2, '0')}`;
      const earnings = monthlyCompleted
        .filter(b => b.date === dayStr)
        .reduce((s, b) => s + (b.price || 0), 0);
      return { day: String(day), earnings };
    });
  }, [monthlyCompleted, selectedMonth]);

  if (loading) return <div className="p-10 text-center animate-pulse text-[#555]">{t('misc.loading')}</div>;

  return (
    <div className="animate-fadeUp p-6 md:p-8 md:px-10 max-w-[900px]">
      {/* Header */}
      <div className="flex flex-wrap items-center justify-between gap-4 mb-6">
        <h1 className="text-2xl font-black">{t('shopDash.earnings')} 💰</h1>
        <select
          value={selectedMonth}
          onChange={e => setSelectedMonth(e.target.value)}
          className="bg-[#141414] border border-[#2a2a2a] text-white rounded-xl px-4 py-2.5 text-sm outline-none focus:border-brand-yellow"
        >
          {monthOptions.map(o => (
            <option key={o.value} value={o.value}>{o.label}</option>
          ))}
        </select>
      </div>

      {/* Stat cards */}
      <div className="grid grid-cols-2 lg:grid-cols-4 gap-3.5 mb-8">
        {[
          { val: fmtMoney(monthRevenue, currSym), label: t('shop.monthlyRevenue'), delta: selectedMonthLabel, color: 'text-brand-yellow' },
          { val: fmtMoney(yearRevenue, currSym), label: t('shopDash.annualRevenue'), delta: t('shopDash.thisYear'), color: 'text-brand-orange' },
          { val: monthCuts, label: t('shop.totalCuts'), delta: selectedMonthLabel, color: 'text-[#60a5fa]' },
          { val: `${currSym}${avgPerCut.toFixed(2)}`, label: t('shopDash.avgPerCut'), delta: t('shopDash.revenuePerService'), color: 'text-brand-green' },
        ].map((s, i) => (
          <div key={i} className="bg-brand-surface border border-brand-border rounded-2xl p-5 flex flex-col gap-1.5">
            <div className={`text-[28px] font-black leading-none ${s.color}`}>{s.val}</div>
            <div className="text-xs text-brand-text-secondary font-bold">{s.label}</div>
            <div className="text-[11px] font-extrabold text-[#444] mt-1">{s.delta}</div>
          </div>
        ))}
      </div>

      {/* Per-barber table */}
      <div className="bg-brand-surface border border-brand-border rounded-3xl p-6 mb-6">
        <div className="flex justify-between items-center mb-5">
          <div className="font-black text-base">{t('shopDash.breakdownByBarber').replace('{month}', selectedMonthLabel)}</div>
          <button
            onClick={() => exportCSV(barberRows, currSym, selectedMonth)}
            className="text-[11px] font-bold border border-[#2a2a2a] text-[#888] hover:border-brand-yellow hover:text-brand-yellow px-3 py-1.5 rounded-full transition-colors"
          >
            {t('shop.exportCSV')}
          </button>
        </div>

        {barberRows.length === 0 ? (
          <div className="text-[#555] text-sm">{t('shopDash.noBarbersTeamYet')}</div>
        ) : (
          <div className="overflow-x-auto">
            <table className="w-full text-sm">
              <thead>
                <tr className="border-b border-[#1e1e1e]">
                  {[t('shopDash.tableBarber'), t('shopDash.tableCuts'), t('shopDash.tableHours'), t('shopDash.tableEarned'), t('shopDash.tableAvgCut')].map(h => (
                    <th key={h} className="text-left text-[10px] font-black uppercase text-[#555] pb-3 pr-4">{h}</th>
                  ))}
                </tr>
              </thead>
              <tbody>
                {barberRows.map(row => (
                  <tr key={row.id} className="border-b border-[#111] hover:bg-[#0f0f0f] transition-colors">
                    <td className="py-3 pr-4 font-extrabold">
                      {row.id === topEarnerId && row.earned > 0 && <span className="mr-1.5">⭐</span>}
                      {row.name}
                    </td>
                    <td className="py-3 pr-4 font-bold">{row.cuts}</td>
                    <td className="py-3 pr-4 text-[#888] font-bold">{row.hours.toFixed(1)}h</td>
                    <td className="py-3 pr-4 font-black text-brand-yellow">{currSym}{row.earned.toFixed(0)}</td>
                    <td className="py-3 text-[#888] font-bold">
                      {row.cuts > 0 ? `${currSym}${(row.earned / row.cuts).toFixed(0)}` : '—'}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>

      {/* Daily chart */}
      <div className="bg-brand-surface border border-brand-border rounded-3xl p-6">
        <div className="font-black text-base mb-5">{t('shopDash.dailyEarnings').replace('{month}', selectedMonthLabel)}</div>
        <ResponsiveContainer width="100%" height={180}>
          <BarChart data={dailyChartData} margin={{ top: 4, right: 4, bottom: 0, left: 0 }}>
            <XAxis dataKey="day" tick={{ fill: '#555', fontSize: 10 }} axisLine={false} tickLine={false} interval={4} />
            <Tooltip
              contentStyle={{ background: '#141414', border: '1px solid #2a2a2a', borderRadius: 8, color: '#fff', fontSize: 12 }}
              cursor={{ fill: '#1a1a1a' }}
              formatter={(v: any) => [`${currSym}${v}`, t('shopDash.earningsLabel')]}
            />
            <Bar dataKey="earnings" radius={[4, 4, 0, 0]}>
              {dailyChartData.map((_, i) => (
                <Cell key={i} fill="#F5C518" fillOpacity={0.85} />
              ))}
            </Bar>
          </BarChart>
        </ResponsiveContainer>
      </div>
    </div>
  );
}

export default function ShopDashboardLayout({ children }: { children: React.ReactNode }) {
  const { user, appUser, loading } = useAuth();
  const router = useRouter();
  const pathname = usePathname();
  const { t } = useLang();
  const [toastMessage, setToastMessage] = useState('');
  const [challengeUnread, setChallengeUnread] = useState(0);

  useEffect(() => {
    if (!user?.uid) return;
    const q = query(
      collection(db, 'notifications'),
      where('userId', '==', user.uid),
      where('type', 'in', ['challenge_approved', 'challenge_rejected']),
      where('read', '==', false)
    );
    const unsub = onSnapshot(q, snap => {
      setChallengeUnread(snap.size);
    }, err => {
      console.warn('challenge unread listener', err);
    });
    return () => unsub();
  }, [user?.uid]);

  useEffect(() => {
    if (loading) return;
    if (!user) {
      router.replace('/login');
      return;
    }
    if (!appUser?.ownsShop) {
      router.replace(
        appUser?.role === 'client'
          ? '/dashboard/client'
          : '/dashboard/barber'
      );
    }
  }, [user, appUser, loading, router]);

  const { data: shop } = useQuery({
    queryKey: ['shop', user?.uid],
    queryFn: async () => { const s = await getDoc(doc(db, 'businesses', user!.uid)); return s.exists() ? s.data() : null; },
    enabled: !!user,
  });

  const { data: schedule } = useQuery({
    queryKey: ['shopSchedule', user?.uid],
    queryFn: async () => { const s = await getDoc(doc(db, 'schedules', `${user!.uid}_shard_0`)); return s.exists() ? s.data() : null; },
    enabled: !!user,
  });

  // Calculate open/closed status
  let shopStatus = { text: t('status.closedToday'), color: 'text-brand-red' };
  if (schedule) {
    const today = new Date();
    const todayStr = `${today.getFullYear()}-${String(today.getMonth() + 1).padStart(2, '0')}-${String(today.getDate()).padStart(2, '0')}`;
    const dayName = today.toLocaleDateString('en-US', { weekday: 'long' }).toLowerCase();
    if ((schedule as any).blockedDates?.includes(todayStr)) {
      shopStatus = { text: t('shopDash.onLeave'), color: 'text-brand-red' };
    } else {
      const h = (schedule as any).weeklyHours?.[dayName];
      if (h?.isOpen) {
        const nowMins = today.getHours() * 60 + today.getMinutes();
        const startMins = parseInt(h.start?.split(':')[0] || '0') * 60 + parseInt(h.start?.split(':')[1] || '0');
        const endMins = parseInt(h.end?.split(':')[0] || '0') * 60 + parseInt(h.end?.split(':')[1] || '0');
        if (nowMins >= startMins && nowMins < endMins) shopStatus = { text: t('status.openNow'), color: 'text-brand-green' };
        else if (nowMins < startMins) shopStatus = { text: t('status.closedOpens').replace('{time}', h.start), color: 'text-brand-red' };
      }
    }
  }

  const navItems = [
    { href: '/dashboard/shop', icon: '', label: t('shopDash.overviewNav'), exact: true },
    { href: '/dashboard/shop/team', icon: '', label: t('shopDash.teamNav'), exact: false },
    { href: '/dashboard/shop/bookings', icon: '', label: t('bookings.allBookings'), exact: false },
    { href: '/dashboard/shop/availability', icon: '', label: t('barberLayout.navAvailability'), exact: false },
    { href: '/dashboard/shop/earnings', icon: '', label: t('shopDash.earnings'), exact: false },
    { href: '/dashboard/shop/services', icon: '', label: t('barberLayout.navServices'), exact: false },
    { href: '/dashboard/shop/billing', icon: '', label: t('shopDash.navBilling'), exact: false },
    { href: '/dashboard/shop/photos', icon: '', label: t('shopDash.shopPhotosNav'), exact: false },
    { href: '/dashboard/shop/challenge', icon: '', label: '🏆 Challenge', exact: false },
    { href: '/dashboard/shop/reviews', icon: '', label: t('shopDash.reviews'), exact: false },
    { href: '/dashboard/shop/settings', icon: '', label: t('clientDash.settings'), exact: false },
  ];

  const isActive = (item: { href: string; exact: boolean }) =>
    item.exact ? pathname === item.href : pathname.startsWith(item.href);

  return (
    <div className="flex min-h-[calc(100vh-53px)] flex-col md:flex-row">
      {/* Sidebar */}
      <div className="w-full md:w-[220px] md:border-r border-brand-border p-6 shrink-0 flex flex-col">
        <div className="flex items-center gap-3 mb-6 px-2">
          {((shop as any)?.logoUrl || (shop as any)?.coverPhotoUrl) ? (
            <div className="relative w-10 h-10 rounded-xl overflow-hidden shrink-0">
              <Image src={(shop as any).logoUrl || (shop as any).coverPhotoUrl} alt="Shop" fill className="object-cover" referrerPolicy="no-referrer" />
            </div>
          ) : (
            <div className="w-10 h-10 rounded-xl bg-gradient-to-br from-brand-orange to-brand-yellow flex items-center justify-center font-black text-base text-[#0a0a0a]">
              {(shop as any)?.name?.[0] || 'S'}
            </div>
          )}
          <div>
            <div className="font-extrabold text-sm truncate max-w-[120px]">{(shop as any)?.name || t('barberLayout.myShop')}</div>
            <div className="text-[11px] text-brand-text-secondary mt-0.5 truncate max-w-[120px]">
              📍 {(shop as any)?.address?.city || t('shopDash.locationNotSet')}
            </div>
            <div className={`text-[11px] mt-1 font-bold ${shopStatus.color}`}>{shopStatus.text}</div>
          </div>
        </div>

        <div className="flex md:flex-col gap-2 overflow-x-auto md:overflow-visible pb-2 md:pb-0">
          {navItems.map(l => (
            <Link key={l.href} href={l.href}
              className={`flex items-center gap-2.5 px-4 py-2.5 rounded-xl text-[13px] font-bold transition-colors shrink-0 ${
                isActive(l) ? 'bg-[#1a1a1a] text-brand-yellow' : 'text-[#888] hover:bg-[#1a1a1a] hover:text-white'
              }`}>
              <span className="flex items-center gap-2">
                {l.label}
                {l.href === '/dashboard/shop/challenge' && challengeUnread > 0 && (
                  <span className="w-2 h-2 bg-brand-red rounded-full" />
                )}
              </span>
            </Link>
          ))}
        </div>

        {appUser?.role === 'professional' && (
          <div className="hidden md:block mt-6 pt-6 border-t border-brand-border">
            <Link href="/dashboard/barber" className="flex items-center gap-2.5 px-4 py-2.5 rounded-xl text-[13px] font-bold text-[#888] hover:bg-[#1a1a1a] hover:text-white transition-colors">
              <span>✂️</span> {t('shopDash.myBarberDashboard')}
            </Link>
          </div>
        )}
      </div>

      {/* Main content */}
      <main className="flex-1 overflow-y-auto max-h-[calc(100vh-53px)] pb-[60px] md:pb-0">
        {children}
      </main>

      {/* Mobile bottom tab bar */}
      <div className="fixed bottom-0 left-0 right-0 bg-[#111] border-t border-[#1e1e1e] h-[60px] flex md:hidden z-40">
        {[
          { href: '/dashboard/shop', label: t('shopDash.overviewNav'), exact: true },
          { href: '/dashboard/shop/team', label: t('shopDash.teamNav'), exact: false },
          { href: '/dashboard/shop/bookings', label: t('barberLayout.navBookings'), exact: false },
          { href: '/dashboard/shop/billing', label: t('shopDash.navBilling'), exact: false },
          { href: '/dashboard/shop/settings', label: t('barberLayout.navMore'), exact: false },
        ].map(item => (
          <Link key={item.href} href={item.href}
            className={`flex-1 flex flex-col items-center justify-center gap-0.5 text-[10px] font-bold transition-colors ${
              isActive(item) ? 'text-brand-yellow' : 'text-[#555]'
            }`}>
            {item.label}
          </Link>
        ))}
      </div>

      {toastMessage && (
        <div className="fixed bottom-6 right-6 bg-[#1a0808] border border-brand-yellow/30 text-brand-yellow px-6 py-3 rounded-full font-bold text-sm shadow-xl z-50">
          {toastMessage}
        </div>
      )}
    </div>
  );
}

