            <div className="h-24 bg-[#111] rounded-2xl animate-pulse" />
            <div className="h-[300px] bg-[#111] rounded-2xl animate-pulse" />
            <div className="h-[200px] bg-[#111] rounded-2xl animate-pulse" />
