                        {/* Languages */}
                        {languages.length > 0 && (
                          <div className="text-[11px] text-[#555] font-bold mb-3">
                            {languages.slice(0, 2).join(' · ')}{languages.length > 2 ? ` +${languages.length - 2}` : ''}
