                  })}
                </div>
              )}
            </div>

            {/* SECTION 2 — SERVICES */}
            <div className="mb-10">
              <div className="mb-5">
                <h2 className="font-black text-lg">{t('profile.shopServicesTitle')}</h2>
                <p className="text-xs text-[#555] font-bold mt-0.5">
                  {t('profile.servicesSynced')}
