                    <span className="text-sm shrink-0 mt-0.5">📍</span>
                    <div className="text-xs font-bold text-white leading-snug">
                      {[address.street, address.number].filter(Boolean).join(' ')}
                      {address.city ? `, ${address.city}` : ''}
