                  </div>
                )}
                {shop.contactPhone && (
                  <div className="flex items-center gap-2.5">
                    <span className="text-sm shrink-0">📞</span>
                    <a href={`tel:${shop.contactPhone}`} className="text-xs font-bold text-white hover:text-brand-yellow transition-colors">
