function getCurrencySymbol(c?: string): string {
  const m: Record<string, string> = { EUR: '€', GBP: '£', USD: '$', MAD: 'MAD ', DZD: 'DA ', TND: 'DT ', SAR: 'SAR ', AED: 'AED ' };
  return m[(c || 'EUR').toUpperCase()] ?? '€';
}

export function ShopServicesTab({ services = [], mutateServices, shop, mutateShop }: ShopServicesTabProps) {
  const { user } = useAuth();
  const { t } = useLang();
  const currSym = getCurrencySymbol(shop?.currency);

  // Add form
  const [newServiceName, setNewServiceName] = useState('');
  const [newServicePrice, setNewServicePrice] = useState('');
  const [newServiceDuration, setNewServiceDuration] = useState('');
  const [addError, setAddError] = useState('');

  // titeZMe Cut
  const [isSavingTitz, setIsSavingTitz] = useState(false);
  const [titzData, setTitzData] = useState({
    duration: shop?.titeZMeCut?.durationMinutes?.toString() || '45',
    price: shop?.titeZMeCut?.price?.toString() || '20',
  });

  // Inline editing
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editName, setEditName] = useState('');
  const [editPrice, setEditPrice] = useState('');
  const [editDuration, setEditDuration] = useState('');

  // ── Add service ──────────────────────────────────────────────────────────
  const handleCreateService = async (name = newServiceName, price = newServicePrice, duration = newServiceDuration) => {
    if (!name || !price || !duration || !user) return;
    // Duplicate check
    const exists = services.some(s => s.name.toLowerCase() === name.toLowerCase() && s.isActive !== false);
    if (exists) { setAddError(t('barberDash.serviceAlreadyExists').replace('{name}', name)); return; }
    setAddError('');
    try {
      await addDoc(collection(db, 'services'), serviceSchema.parse({
        providerId: user.uid,
        providerType: 'shop',
        name,
        price: Number(price),
        currency: shop?.currency || 'EUR',
        durationMinutes: Number(duration),
        isActive: true,
        createdAt: new Date().toISOString(),
      }));
      setNewServiceName(''); setNewServicePrice(''); setNewServiceDuration('');
      mutateServices();
    } catch (e) { console.error(e); }
  };

  const handleDeleteService = async (id: string) => {
    try { await deleteDoc(doc(db, 'services', id)); mutateServices(); } catch (e) { console.error(e); }
  };

  const handleToggleActive = async (id: string, current: boolean) => {
    try { await updateDoc(doc(db, 'services', id), { isActive: !current }); mutateServices(); } catch (e) { console.error(e); }
  };

  const startEdit = (s: any) => {
    setEditingId(s.id); setEditName(s.name); setEditPrice(String(s.price)); setEditDuration(String(s.durationMinutes));
  };

  const handleSaveEdit = async (id: string) => {
    if (!editName || !editPrice || !editDuration) return;
    try {
      await updateDoc(doc(db, 'services', id), { name: editName, price: Number(editPrice), durationMinutes: Number(editDuration) });
      setEditingId(null); mutateServices();
    } catch (e) { console.error(e); }
  };

  // ── titeZMe Cut ──────────────────────────────────────────────────────────
  const handleSaveTitzCut = async () => {
    if (!user) return;
    setIsSavingTitz(true);
    try {
      await updateDoc(doc(db, 'businesses', user.uid), businessUpdateSchema.parse({
        titeZMeCut: { durationMinutes: Number(titzData.duration), price: Number(titzData.price), currency: shop?.currency || 'EUR' },
      }));
      mutateShop();
    } catch (e) { console.error(e); }
    setIsSavingTitz(false);
  };

  // Summary line
  const activeServices = services.filter(s => s.isActive !== false);
  const prices = activeServices.map(s => Number(s.price)).filter(p => p > 0);
  const minPrice = prices.length ? Math.min(...prices) : null;
  const maxPrice = prices.length ? Math.max(...prices) : null;

  return (
    <div className="animate-fadeUp max-w-2xl">
      <h1 className="text-2xl font-black mb-2">{t('headings.shopServicesHeading')} ✂️</h1>
      <p className="text-brand-text-secondary text-sm mb-8">{t('shop.manageServicesDesc')}</p>

      {/* Summary line */}
      {activeServices.length > 0 && (
        <div className="text-[12px] text-[#888] font-bold mb-5">
          {activeServices.length} {activeServices.length === 1 ? t('barberLayout.activeService') : t('barberLayout.activeServices')}
          {minPrice !== null && ` · ${t('barberLayout.from')} ${currSym}${minPrice} ${t('barberLayout.to')} ${currSym}${maxPrice}`}
        </div>
      )}

      {/* TITEZME CUT */}
      <div className="bg-[#141414] border border-[#2a2a2a] border-l-4 border-l-brand-yellow rounded-xl p-5 mb-8">
        <div className="flex justify-between items-start mb-2">
          <div>
            <div className="flex items-center gap-2 mb-1">
              <span className="font-black text-lg text-brand-yellow">titeZMe Cut</span>
              <span className="text-brand-text-secondary text-xs">{t('shop.lockedBadge')}</span>
            </div>
            <p className="text-[#888] text-xs max-w-sm">{t('booking.titeZMeCutDesc')}</p>
          </div>
        </div>
        <div className="flex flex-wrap items-end gap-3 mt-4">
          <div>
            <label className="text-[10px] font-bold text-[#888] uppercase block mb-1">{t('forms.duration')}</label>
            <input type="number" value={titzData.duration} onChange={(e) => setTitzData({ ...titzData, duration: e.target.value })}
              className="bg-[#0a0a0a] border border-[#2a2a2a] text-white rounded-lg px-3 py-2 w-20 text-sm" />
          </div>
          <div>
            <label className="text-[10px] font-bold text-[#888] uppercase block mb-1">{t('forms.price')} ({currSym})</label>
            <input type="number" value={titzData.price} onChange={(e) => setTitzData({ ...titzData, price: e.target.value })}
              className="bg-[#0a0a0a] border border-[#2a2a2a] text-white rounded-lg px-3 py-2 w-20 text-sm" />
          </div>
          <button onClick={handleSaveTitzCut} disabled={isSavingTitz}
            className="ml-auto bg-[#2a2a2a] hover:bg-[#333] text-white px-4 py-2 rounded-lg font-bold text-xs transition-colors">
            {isSavingTitz ? t('settings.saving') : t('settings.saveChanges')}
          </button>
        </div>
      </div>

      {/* SHOP SERVICES LIST */}
      <h2 className="font-black text-lg mb-4">{t('headings.shopServicesHeading')}</h2>
      <div className="flex flex-col gap-3 mb-8">
        {services.length === 0 ? (
          <div className="text-brand-text-secondary text-sm">{t('emptyStates.noRegularServices')}</div>
        ) : (
          services.map(s => {
            const isActive = s.isActive !== false;
            const isEditing = editingId === s.id;
            return (
              <div key={s.id} className={`bg-brand-surface border rounded-xl p-4 transition-all ${isActive ? 'border-brand-border' : 'border-[#1a1a1a] opacity-50'}`}>
                {isEditing ? (
                  /* Inline edit form */
                  <div className="flex flex-wrap gap-2 items-center">
                    <input value={editName} onChange={e => setEditName(e.target.value)}
                      className="flex-1 min-w-[120px] bg-[#0a0a0a] border border-[#2a2a2a] text-white rounded-lg px-3 py-1.5 text-sm" />
                    <input type="number" value={editDuration} onChange={e => setEditDuration(e.target.value)}
                      className="w-16 bg-[#0a0a0a] border border-[#2a2a2a] text-white rounded-lg px-2 py-1.5 text-sm" placeholder="Min" />
                    <div className="relative">
                      <span className="absolute left-2.5 top-1/2 -translate-y-1/2 text-[#888] text-xs">{currSym}</span>
                      <input type="number" value={editPrice} onChange={e => setEditPrice(e.target.value)}
                        className="w-20 bg-[#0a0a0a] border border-[#2a2a2a] text-white rounded-lg pl-6 pr-2 py-1.5 text-sm" />
                    </div>
                    <button onClick={() => handleSaveEdit(s.id)}
                      className="text-[11px] font-black text-brand-green border border-brand-green/40 px-3 py-1.5 rounded-lg hover:bg-[#0f2010] transition-colors">{t('buttons.save')}</button>
                    <button onClick={() => setEditingId(null)}
                      className="text-[11px] font-bold text-[#888] hover:text-white px-2">{t('buttons.cancel')}</button>
                  </div>
                ) : (
                  <div className="flex items-center justify-between">
                    <div>
                      <div className="font-bold text-base mb-0.5">{s.name}</div>
                      <div className="text-xs text-brand-text-secondary">{s.durationMinutes} {t('misc.minShort')} · {currSym}{s.price}</div>
                    </div>
                    <div className="flex items-center gap-2">
                      {/* Active toggle */}
                      <button onClick={() => handleToggleActive(s.id, isActive)}
                        className={`relative w-9 h-5 rounded-full transition-colors ${isActive ? 'bg-brand-green' : 'bg-[#2a2a2a]'}`}>
                        <span className={`absolute top-0.5 w-4 h-4 rounded-full bg-white transition-all ${isActive ? 'left-4' : 'left-0.5'}`} />
                      </button>
                      {/* Edit */}
                      <button onClick={() => startEdit(s)}
                        className="w-8 h-8 rounded-full flex items-center justify-center text-sm text-[#555] hover:text-brand-yellow hover:bg-[#1a1500] transition-colors">
                        ✏️
                      </button>
                      {/* Delete */}
                      <button onClick={() => handleDeleteService(s.id)}
                        className="w-8 h-8 rounded-full flex items-center justify-center text-[#555] hover:text-brand-red hover:bg-[#1a0808] transition-colors text-lg">
                        ✕
                      </button>
                    </div>
                  </div>
                )}
              </div>
            );
          })
        )}
      </div>

      {/* ADD SERVICE FORM */}
      <div className="bg-[#141414] border border-[#2a2a2a] rounded-xl p-5">
        <h3 className="font-extrabold text-sm mb-4">{t('buttons.addNewService')}</h3>
        {addError && (
          <div className="text-brand-red text-xs font-bold mb-3 bg-[#1a0808] border border-[#3b1a1a] rounded-lg px-3 py-2">{addError}</div>
        )}
        <div className="grid grid-cols-1 sm:grid-cols-12 gap-3 mb-4">
          <div className="sm:col-span-6">
            <input type="text" placeholder={t('forms.serviceNamePlaceholder')} value={newServiceName}
              onChange={e => { setNewServiceName(e.target.value); setAddError(''); }}
              className="w-full bg-[#0a0a0a] border border-[#2a2a2a] rounded-xl px-4 py-3 text-white text-sm" />
          </div>
          <div className="sm:col-span-3">
            <input type="number" placeholder={t('forms.minPlaceholder')} value={newServiceDuration}
              onChange={e => setNewServiceDuration(e.target.value)}
              className="w-full bg-[#0a0a0a] border border-[#2a2a2a] rounded-xl px-4 py-3 text-white text-sm" />
          </div>
          <div className="sm:col-span-3 relative">
            <span className="absolute left-4 top-1/2 -translate-y-1/2 text-[#888] font-medium text-sm">{currSym}</span>
            <input type="number" placeholder={t('forms.pricePlaceholder')} value={newServicePrice}
              onChange={e => setNewServicePrice(e.target.value)}
              className="w-full bg-[#0a0a0a] border border-[#2a2a2a] rounded-xl pl-8 pr-4 py-3 text-white text-sm" />
          </div>
        </div>
        <button onClick={() => handleCreateService()}
          disabled={!newServiceName || !newServicePrice || !newServiceDuration}
          className="w-full sm:w-auto bg-white text-black px-6 py-3 rounded-xl font-bold text-sm hover:bg-gray-200 disabled:opacity-50 transition-colors mb-4">
          {t('buttons.addService')}
        </button>

        {/* Quick-add chips */}
        <div className="flex flex-wrap gap-2">
          {QUICK_CHIPS.map(chip => {
            const alreadyExists = services.some(s => s.name.toLowerCase() === chip.toLowerCase());
            if (alreadyExists) return null;
            return (
              <button key={chip}
                onClick={() => { setNewServiceName(chip); setAddError(''); }}
                className="text-[11px] font-bold bg-[#1a1a1a] text-[#888] hover:bg-[#222] hover:text-white px-3 py-1.5 rounded-full transition-colors">
                + {chip}
              </button>
            );
          })}
        </div>
      </div>

      {/* Info note */}
      <div className="mt-5 bg-[#0d0d0d] border border-[#1e1e1e] rounded-[10px] px-[14px] py-[10px]">
        <p className="text-[11px] text-[#555]">
          {t('shop.servicesSharedNote')}
        </p>
      </div>
    </div>
  );
}

export function ShopSettingsTab({ shop, mutateShop }: ShopSettingsTabProps) {
  const { user } = useAuth();
  const { t } = useLang();
  const router = useRouter();
  const [photoLoading, setPhotoLoading] = useState(false);
  const [logoLoading, setLogoLoading] = useState(false);
  const [savingGlobal, setSavingGlobal] = useState(false);
  const [savingSocial, setSavingSocial] = useState(false);
  const [deleting, setDeleting] = useState(false);
  const [errorMsg, setErrorMsg] = useState('');
  const [successMsg, setSuccessMsg] = useState('');
  const [localPhotoUrl, setLocalPhotoUrl] = useState('');
  const [localLogoUrl, setLocalLogoUrl] = useState('');

  const [formData, setFormData] = useState({
    name: shop?.name || '',
    street: shop?.address?.street || '',
    buildingNumber: shop?.address?.buildingNumber || '',
    postalCode: shop?.address?.postalCode || '',
    floorSuite: shop?.address?.floorSuite || '',
    description: shop?.description || '',
    chairsCount: shop?.chairsCount ?? '',
    establishedYear: shop?.establishedYear ?? '',
  });

  const existingPhoneParts = (shop?.contactPhone || '').split(' ');
  const initPhoneCodeStr = existingPhoneParts[0]?.replace('+', '') || '';
  const initPhoneNumStr = existingPhoneParts.length > 1 ? existingPhoneParts.slice(1).join('') : (existingPhoneParts[0] && !existingPhoneParts[0].startsWith('+') ? existingPhoneParts[0] : '');

  const [phoneNumberInput, setPhoneNumberInput] = useState(initPhoneNumStr);
  const [phoneCode, setPhoneCode] = useState<any>(null);
  
  const [selectedCountry, setSelectedCountry] = useState<any>(null);
  const [selectedState, setSelectedState] = useState<any>(null);
  const [selectedCityOption, setSelectedCityOption] = useState<any>(null);
  const [csc, setCsc] = useState<any>(null);

  useEffect(() => { import('country-state-city').then(m => setCsc(m)); }, []);

  const countryOptions = useMemo(() => {
    if (!csc) return [];
    return csc.Country.getAllCountries().map((c: any) => ({ value: c.isoCode, label: `${c.flag} ${c.name}` }));
  }, [csc]);

  const phoneCodeOptions = useMemo(() => {
    if (!csc) return [];
    return csc.Country.getAllCountries().map((c: any) => ({ value: c.phonecode, label: `${c.flag} ${c.name} (+${c.phonecode})` }));
  }, [csc]);
  
  useEffect(() => {
    setTimeout(() => {
      if (initPhoneCodeStr) {
        const match = phoneCodeOptions.find((o: any) => o.value === initPhoneCodeStr);
        if (match) setPhoneCode(match);
      }
      if (shop?.address?.country) {
        const match = countryOptions.find((o: any) => o.value === shop.address.country);
        if (match) setSelectedCountry(match);
      }
    }, 0);
  }, [initPhoneCodeStr, shop?.address?.country, phoneCodeOptions, countryOptions]);

  useEffect(() => {
    setTimeout(() => {
      if (shop?.address?.city && selectedCountry && csc) {
        const cities = csc.City.getCitiesOfCountry(selectedCountry.value) || [];
        const match = cities.find((c: any) => c.name === shop.address.city);
        if (match) {
          setSelectedCityOption({ value: match.name, label: match.name });
        } else if (shop.address.city) {
          setSelectedCityOption({ value: shop.address.city, label: shop.address.city });
        }
      }
    }, 0);
  }, [shop?.address?.city, selectedCountry, csc]);

  const selectStyles = {
    control: (base: any, state: any) => ({
      ...base,
      background: '#141414',
      borderColor: state.isFocused ? '#FFD700' : '#2a2a2a',
      borderRadius: '0.75rem',
      padding: '2px',
      color: 'white',
      boxShadow: 'none',
      '&:hover': {
        borderColor: state.isFocused ? '#FFD700' : '#2a2a2a',
      }
    }),
    menu: (base: any) => ({
      ...base,
      background: '#141414',
      border: '1.5px solid #2a2a2a',
      borderRadius: '0.75rem',
      overflow: 'hidden',
      zIndex: 50
    }),
    option: (base: any, state: any) => ({
      ...base,
      backgroundColor: state.isFocused ? '#2a2a2a' : '#141414',
      color: 'white',
      cursor: 'pointer',
      '&:hover': {
        backgroundColor: '#2a2a2a'
      }
    }),
    singleValue: (base: any) => ({
      ...base,
      color: 'white'
    }),
    input: (base: any) => ({
      ...base,
      color: 'white'
    }),
    placeholder: (base: any) => ({
      ...base,
      color: '#444'
    }),
  };

  const [socialData, setSocialData] = useState({
    instagram: shop?.instagram || '',
    facebook: shop?.facebook || '',
    tiktok: shop?.tiktok || ''
  });

  const [googleMapsUrl, setGoogleMapsUrl] = useState(shop?.googleMapsUrl || '');
  const [savingMaps, setSavingMaps] = useState(false);
  const [notifyInviteResponse, setNotifyInviteResponse] = useState(shop?.notifyInviteResponse !== false);
  const [notifyNewBooking, setNotifyNewBooking] = useState(shop?.notifyNewBooking !== false);
  // Layer 1 — chair rental
  const [rentsChairs, setRentsChairs] = useState<boolean>(shop?.rentsChairs ?? false);
  const [availableChairsForRent, setAvailableChairsForRent] = useState<number>(shop?.availableChairsForRent ?? 0);
  const [savingChairRental, setSavingChairRental] = useState(false);
  const maxRentableChairs = Number(formData.chairsCount) > 0 ? Number(formData.chairsCount) : 99;

  const handlePhotoUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file || !user) return;
    
    if (!['image/jpeg', 'image/png', 'image/webp'].includes(file.type)) {
      setErrorMsg(t('errors.invalidImageType'));
      return;
    }

    setPhotoLoading(true);
    setErrorMsg('');
    setSuccessMsg('');

    try {
      const options = {
        maxSizeMB: 1, // Shop profile max 1MB
        maxWidthOrHeight: 1200, // Shop profile max 1200px
        useWebWorker: false,
      };
      
      const compressedFile = await imageCompression(file, options);

      const storageRef = ref(storage, `shop-profile/${user.uid}/cover.jpg`);
      const uploadTask = uploadBytesResumable(storageRef, compressedFile, { cacheControl: 'public, max-age=31536000' });

      uploadTask.on('state_changed', 
        null, 
        (error) => {
          setPhotoLoading(false);
          setErrorMsg(t('errors.uploadFailed'));
          console.error("Upload Error:", error);
        }, 
        async () => {
          try {
            const downloadURL = await getDownloadURL(uploadTask.snapshot.ref);
            await updateDoc(doc(db, 'businesses', user.uid), businessUpdateSchema.parse({ coverPhotoUrl: downloadURL }));
            setLocalPhotoUrl(downloadURL);
            mutateShop();
            setSuccessMsg(t('success.shopPhotoUpdated'));
          } catch (err) {
             console.error("Database Update Error:", err);
             setErrorMsg(t('errors.failedUpdatePhoto'));
          }
          setPhotoLoading(false);
        }
      );
    } catch (error) {
      console.error(error);
      setErrorMsg(t('errors.imageCompressionFailed'));
      setPhotoLoading(false);
    }
  };

  const handleLogoUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file || !user) return;

    if (!['image/jpeg', 'image/png', 'image/webp'].includes(file.type)) {
      setErrorMsg(t('errors.invalidImageType'));
      return;
    }

    setLogoLoading(true);
    setErrorMsg('');
    setSuccessMsg('');

    try {
      const options = {
        maxSizeMB: 1,
        maxWidthOrHeight: 1200,
        useWebWorker: false,
      };

      const compressedFile = await imageCompression(file, options);
      const storageRef = ref(storage, `shop-profile/${user.uid}/logo.jpg`);
      const uploadTask = uploadBytesResumable(storageRef, compressedFile, { cacheControl: 'public, max-age=31536000' });

      uploadTask.on('state_changed',
        null,
        (error) => {
          setLogoLoading(false);
          setErrorMsg(t('errors.uploadFailed'));
          console.error("Logo Upload Error:", error);
        },
        async () => {
          try {
            const downloadURL = await getDownloadURL(uploadTask.snapshot.ref);
            await updateDoc(doc(db, 'businesses', user.uid), businessUpdateSchema.parse({ logoUrl: downloadURL }));
            setLocalLogoUrl(downloadURL);
            mutateShop();
            setSuccessMsg(t('success.shopPhotoUpdated'));
          } catch (err) {
            console.error("Logo DB Update Error:", err);
            setErrorMsg(t('errors.failedUpdatePhoto'));
          }
          setLogoLoading(false);
        }
      );
    } catch (error) {
      console.error(error);
      setErrorMsg(t('errors.imageCompressionFailed'));
      setLogoLoading(false);
    }
  };

  const handleDeleteCover = async () => {
    if (!user) return;
    try {
      await deleteObject(ref(storage, `shop-profile/${user.uid}/cover.jpg`));
    } catch {
      // ignore if file doesn't exist in storage
    }
    await updateDoc(doc(db, 'businesses', user.uid), { coverPhotoUrl: deleteField() });
    setLocalPhotoUrl('');
    mutateShop();
    setSuccessMsg(t('success.shopPhotoUpdated'));
  };

  const handleDeleteLogo = async () => {
    if (!user) return;
    try {
      await deleteObject(ref(storage, `shop-profile/${user.uid}/logo.jpg`));
    } catch {
      // ignore if file doesn't exist in storage
    }
    await updateDoc(doc(db, 'businesses', user.uid), { logoUrl: deleteField() });
    setLocalLogoUrl('');
    mutateShop();
    setSuccessMsg(t('success.shopPhotoUpdated'));
  };

  const handleSaveInfo = async () => {
    if (!user) return;
    if (!formData.name || !formData.street || !formData.buildingNumber || !formData.postalCode) {
      setErrorMsg(t('errors.fillRequiredFields'));
      return;
    }

    setSavingGlobal(true);
    setErrorMsg('');
    setSuccessMsg('');
    try {
      const phoneStr = phoneCode && phoneNumberInput ? `+${phoneCode.value} ${phoneNumberInput}` : null;
      const cityStr = selectedCityOption ? selectedCityOption.value : "";
      const countryStr = selectedCountry ? selectedCountry.value : "";

      await updateDoc(doc(db, 'businesses', user.uid), businessUpdateSchema.parse({
              name: sanitizeText(formData.name, 100),
              contactEmail: shop.contactEmail,
              contactPhone: phoneStr,
              address: {
                country: countryStr,
                ...(selectedState ? { state: selectedState.value } : {}),
                city: cityStr,
                street: formData.street,
                buildingNumber: formData.buildingNumber,
                postalCode: formData.postalCode,
                floorSuite: formData.floorSuite
              },
              description: sanitizeText(formData.description, 300),
              ...(formData.chairsCount ? { chairsCount: Number(formData.chairsCount) } : {}),
              ...(formData.establishedYear ? { establishedYear: Number(formData.establishedYear) } : {}),
            }));
      mutateShop();
      setSuccessMsg(t('success.shopInfoSaved'));
    } catch (e) {
      console.error(e);
      setErrorMsg(t('errors.failedSaveShopInfo'));
    }
    setSavingGlobal(false);
  };

  const handleSaveSocial = async () => {
    if (!user) return;
    setSavingSocial(true);
    setErrorMsg('');
    setSuccessMsg('');
    try {
      await updateDoc(doc(db, 'businesses', user.uid), businessUpdateSchema.parse({
              instagram: sanitizeHandle(socialData.instagram),
              facebook: sanitizeHandle(socialData.facebook),
              tiktok: sanitizeHandle(socialData.tiktok),
            }));
      mutateShop();
      setSuccessMsg(t('success.socialLinksSaved'));
    } catch (e) {
      console.error(e);
      setErrorMsg(t('errors.failedSaveSocialLinks'));
    }
    setSavingSocial(false);
  };

  const handleSaveMaps = async () => {
    if (!user) return;
    setSavingMaps(true);
    setErrorMsg(''); setSuccessMsg('');
    try {
      await updateDoc(doc(db, 'businesses', user.uid), businessUpdateSchema.parse({ googleMapsUrl: sanitizeUrl(googleMapsUrl) }));
      mutateShop();
      setSuccessMsg(t('success.mapsLinkSaved'));
    } catch (e) {
      console.error(e);
      setErrorMsg(t('errors.failedSaveMapsLink'));
    }
    setSavingMaps(false);
  };

  const handleSaveChairRental = async () => {
    if (!user) return;
    setSavingChairRental(true);
    setErrorMsg(''); setSuccessMsg('');
    try {
      await updateDoc(doc(db, 'businesses', user.uid), {
        rentsChairs,
        availableChairsForRent: rentsChairs
          ? Math.min(
              availableChairsForRent,
              Number(formData.chairsCount) > 0 ? Number(formData.chairsCount) : availableChairsForRent
            )
          : 0,
      });
      mutateShop();
    } catch (e) {
      console.error(e);
    } finally {
      setSavingChairRental(false);
    }
  };

  const handleToggleNotif = async (field: 'notifyInviteResponse' | 'notifyNewBooking', value: boolean) => {
    if (!user) return;
    if (field === 'notifyInviteResponse') setNotifyInviteResponse(value);
    else setNotifyNewBooking(value);
    try {
      await updateDoc(doc(db, 'users', user.uid), { [field]: value });
    } catch (e) {
      console.error(e);
    }
  };

  const handleDeleteShop = async () => {
    if(!confirm(t('errors.deleteShopConfirm'))) return;
    setDeleting(true);
    try {
      // Deleting a shop requires a complex set of operations. We'll do it using a cloud function normally, 
      // but here we just update the user's status since this is an MVP. Wait, prompt says:
      // "On confirm: 1. Update all barbers where shopId == uid ... 6. Update users... 8. Redirect"
      // we'll hit the /api/shop/delete endpoint if it existed, or we do it directly.
      // But we can't easily query and delete everything blindly without batch. Let's do the minimum requested for MVP.
      
      const { collection, getDocs, query, where, writeBatch } = await import('firebase/firestore');
      const batch = writeBatch(db);
      
      // 1. Detach all professionals who belonged to this business
      const barbersSnap = await getDocs(query(collection(db, 'professionalProfiles'), where('businessId', '==', user?.uid)));
      for (const d of barbersSnap.docs) {
        batch.update(d.ref, {
          businessId: null,
        });
        const notifRef = doc(
          collection(db, 'notifications')
        );
        batch.set(notifRef, {
          userId: d.id,
          type: 'shop_deleted',
          message: 'The shop you were part of has been deleted. Your barber profile is safe. You are now a solo barber.',
          read: false,
          createdAt: Date.now(),
        });
      }

      // 2. Delete services
      const servicesSnap = await getDocs(query(collection(db, 'services'), where('providerId', '==', user?.uid), where('providerType', '==', 'shop')));
      servicesSnap.docs.forEach(d => batch.delete(d.ref));

      // 3. Delete invites
      const invitesSnap = await getDocs(query(collection(db, 'invites'), where('shopId', '==', user?.uid)));
      invitesSnap.docs.forEach(d => batch.delete(d.ref));

      // Cancel future shop bookings + notify clients
      const futureBookingsSnap = await getDocs(
        query(
          collection(db, 'bookings'),
          where('shopId', '==', user!.uid),
          where('status', 'in', ['pending', 'confirmed'])
        )
      );

      for (const booking of futureBookingsSnap.docs) {
        batch.update(booking.ref, {
          status: 'cancelled',
          updatedAt: Date.now(),
          cancellationReason: 'shop_deleted',
        });
        const notifRef = doc(collection(db, 'notifications'));
        batch.set(notifRef, {
          userId: booking.data().clientId,
          type: 'booking_cancelled',
          message: 'The barbershop you booked has closed. Your booking was cancelled.',
          bookingId: booking.id,
          read: false,
          createdAt: Date.now(),
        });
      }

      // Anonymize past shop bookings
      const pastBookingsSnap = await getDocs(
        query(
          collection(db, 'bookings'),
          where('shopId', '==', user!.uid),
          where('status', 'in', [
            'completed',
            'cancelled',
            'cancelled_by_client',
            'cancelled_by_barber'
          ])
        )
      );

      for (const booking of pastBookingsSnap.docs) {
        batch.update(booking.ref, {
          shopId: 'deleted_shop',
          shopName: 'Deleted Shop',
        });
      }

      // 4. Delete schedule
      batch.delete(doc(db, 'schedules', `${user!.uid}_shard_0`));

      // 5. Delete business
      batch.delete(doc(db, 'businesses', user!.uid));

      // 6 & 7. Update the owner's user + professional profile
      batch.update(doc(db, 'users', user!.uid), { ownsShop: false });
      batch.update(doc(db, 'professionalProfiles', user!.uid), { ownsBusiness: false, businessId: null });

      await batch.commit();

      router.push('/dashboard/barber');
    } catch(e) {
      console.error(e);
      setErrorMsg(t('errors.deleteShopFailed'));
      setDeleting(false);
    }
  }

  const currentPhoto = localPhotoUrl || shop?.coverPhotoUrl;
  const currentLogo = localLogoUrl || shop?.logoUrl;

  return (
    <div className="animate-fadeUp max-w-2xl">
      <h1 className="text-2xl font-black mb-2">{t('headings.shopSettings')}</h1>
      <p className="text-brand-text-secondary text-sm mb-8">{t('settings.manageShopDesc')}</p>

      {errorMsg && (
        <div className="bg-[#1a0808] border border-[#3b1a1a] text-brand-red rounded-xl px-4 py-3 text-sm font-bold mb-6">
          {errorMsg}
        </div>
      )}
      {successMsg && (
        <div className="bg-[#0f2010] border border-[#1b3b1c] text-brand-green rounded-xl px-4 py-3 text-sm font-bold mb-6">
          {successMsg}
        </div>
      )}

      {/* SECTION B1: SHOP LOGO */}
      <section className="mb-6 bg-brand-surface border border-brand-border rounded-3xl p-6">
        <h2 className="text-lg font-black mb-4">{t('settings.shopLogo')}</h2>
        <div className="flex items-center gap-6">
          <div className="relative w-24 h-24 rounded-2xl overflow-hidden bg-[#1a1a1a] border border-[#2a2a2a] shrink-0">
            {currentLogo ? (
              <Image src={currentLogo} alt={shop?.name || 'Shop'} fill className="object-cover" referrerPolicy="no-referrer" />
            ) : (
              <div className="w-full h-full flex items-center justify-center text-3xl font-black text-white bg-[#E8491D] uppercase">
                {shop?.name?.[0] || 'S'}
              </div>
            )}
          </div>
          <div>
            <div className="flex items-center gap-3 flex-wrap">
              <label className={`bg-[#1a1a1a] text-white px-5 py-2.5 rounded-full font-bold text-sm cursor-pointer hover:bg-[#2a2a2a] transition-colors inline-block ${logoLoading ? 'opacity-50 pointer-events-none' : ''}`}>
                {logoLoading ? t('settings.uploading') : t('settings.uploadLogo')}
                <input
                  type="file"
                  accept="image/jpeg,image/png,image/webp"
                  onChange={handleLogoUpload}
                  className="hidden"
                  disabled={logoLoading}
                />
              </label>
              {currentLogo && (
                <button
                  onClick={handleDeleteLogo}
                  className="text-sm font-bold text-brand-red hover:underline"
                >
                  {t('settings.removePhoto')}
                </button>
              )}
            </div>
            <p className="text-xs text-[#888] mt-3">{t('settings.logoHint')}</p>
          </div>
        </div>
      </section>

      {/* SECTION B2: COVER PHOTO */}
      <section className="mb-10 bg-brand-surface border border-brand-border rounded-3xl p-6">
        <h2 className="text-lg font-black mb-4">{t('settings.coverPhoto')}</h2>
        <div className="relative w-full h-[140px] rounded-2xl overflow-hidden bg-[#1a1a1a] border border-[#2a2a2a] mb-4"
          style={!currentPhoto ? { background: 'linear-gradient(135deg, #E8491D, #F5C518)' } : {}}>
          {currentPhoto ? (
            <Image src={currentPhoto} alt={shop?.name || 'Shop'} fill className="object-cover" referrerPolicy="no-referrer" />
          ) : (
            <div className="w-full h-full flex items-center justify-center text-4xl font-black" style={{ color: 'rgba(0,0,0,0.3)' }}>
              {(shop?.name ?? 'S').split(' ').slice(0, 2).map((w: string) => w[0]).join('').toUpperCase() || 'S'}
            </div>
          )}
        </div>
        <div className="flex items-center gap-3 flex-wrap">
          <label className={`bg-[#1a1a1a] text-white px-5 py-2.5 rounded-full font-bold text-sm cursor-pointer hover:bg-[#2a2a2a] transition-colors inline-block ${photoLoading ? 'opacity-50 pointer-events-none' : ''}`}>
            {photoLoading ? t('settings.uploading') : t('settings.uploadCover')}
            <input
              type="file"
              accept="image/jpeg,image/png,image/webp"
              onChange={handlePhotoUpload}
              className="hidden"
              disabled={photoLoading}
            />
          </label>
          {currentPhoto && (
            <button
              onClick={handleDeleteCover}
              className="text-sm font-bold text-brand-red hover:underline"
            >
              {t('settings.removePhoto')}
            </button>
          )}
        </div>
        <p className="text-xs text-[#888] mt-3">{t('settings.coverHint')}</p>
      </section>

      {/* SECTION A: SHOP INFO */}
      <section className="mb-10 bg-brand-surface border border-brand-border rounded-3xl p-6">
        <h2 className="text-lg font-black mb-4">{t('headings.shopInfo')}</h2>
        
        <div className="mb-4">
          <label className="text-xs font-bold text-[#888] block mb-1.5 uppercase">{t('forms.shopName')} *</label>
          <input 
            type="text" 
            value={formData.name}
            onChange={e => setFormData({...formData, name: e.target.value})}
            maxLength={100}
            className="w-full bg-[#141414] border border-[#2a2a2a] rounded-xl px-4 py-3 text-white text-sm"
          />
        </div>

        <div className="mb-4">
          <label className="text-xs font-bold text-[#888] block mb-1.5 uppercase">{t('forms.phone')}</label>
          <div className="flex gap-2">
            <div className="flex-[0.8] sm:flex-[0.6] min-w-[120px]">
              <Select 
                options={phoneCodeOptions} 
                value={phoneCode}
                onChange={setPhoneCode}
                styles={selectStyles}
                placeholder="Code"
              />
            </div>
            <div className="flex-1">
              <input 
                type="text"
                inputMode="numeric"
                value={phoneNumberInput}
                onChange={e => setPhoneNumberInput(e.target.value.replace(/\D/g, ''))}
                maxLength={20}
                className="w-full bg-[#141414] border-[1.5px] border-[#2a2a2a] rounded-xl px-4 py-3 text-white text-sm outline-none transition-colors focus:border-brand-yellow placeholder:text-[#444] h-[48px]"
                placeholder="600 000 000" 
              />
            </div>
          </div>
        </div>

        <div className="grid grid-cols-1 sm:grid-cols-3 gap-4 mb-4">
          <div>
            <label className="text-xs font-bold text-[#888] block mb-1.5 uppercase">{t('forms.country')}</label>
            <Select
              options={countryOptions}
              value={selectedCountry}
              onChange={(option: any) => {
                setSelectedCountry(option);
                setSelectedState(null);
                setSelectedCityOption(null);
              }}
              styles={selectStyles}
              placeholder="Country..."
            />
          </div>
          <div>
            <label className="text-xs font-bold text-[#888] block mb-1.5 uppercase">Region</label>
            <Select
              options={selectedCountry && csc ?
                (csc.State.getStatesOfCountry(selectedCountry.value) ?? []).map((s: any) => ({
                  value: s.isoCode,
                  label: s.name
                }))
                : []
              }
              value={selectedState}
              onChange={(option: any) => {
                setSelectedState(option);
                setSelectedCityOption(null);
              }}
              isDisabled={!selectedCountry || !csc}
              isLoading={!csc}
              styles={selectStyles}
              placeholder="Region..."
            />
          </div>
          <div>
            <label className="text-xs font-bold text-[#888] block mb-1.5 uppercase">{t('forms.city')}</label>
            <Select 
              options={selectedCountry && csc ?
                (csc.City.getCitiesOfCountry(selectedCountry.value) ?? []).map((c: any) => ({
                  value: c.name,
                  label: c.name
                }))
                : []
              } 
              value={selectedCityOption}
              onChange={setSelectedCityOption}
              isDisabled={!selectedCountry}
              styles={selectStyles}
              placeholder="City..."
            />
          </div>
        </div>

        <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 mb-4">
          <div>
            <label className="text-xs font-bold text-[#888] block mb-1.5 uppercase">{t('forms.streetName')} *</label>
            <input 
              type="text" 
              value={formData.street}
              onChange={e => setFormData({...formData, street: e.target.value})}
              className="w-full bg-[#141414] border border-[#2a2a2a] rounded-xl px-4 py-3 text-white text-sm"
              placeholder="Calle Mayor"
            />
          </div>
          <div>
            <label className="text-xs font-bold text-[#888] block mb-1.5 uppercase">{t('forms.buildingNumber')} *</label>
            <input 
              type="text" 
              value={formData.buildingNumber}
              onChange={e => setFormData({...formData, buildingNumber: e.target.value})}
              className="w-full bg-[#141414] border border-[#2a2a2a] rounded-xl px-4 py-3 text-white text-sm"
              placeholder="12"
            />
          </div>
        </div>

        <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 mb-4">
          <div>
            <label className="text-xs font-bold text-[#888] block mb-1.5 uppercase">{t('forms.postalCode')} *</label>
            <input 
              type="text" 
              value={formData.postalCode}
              onChange={e => setFormData({...formData, postalCode: e.target.value})}
              className="w-full bg-[#141414] border border-[#2a2a2a] rounded-xl px-4 py-3 text-white text-sm"
              placeholder="28013"
            />
          </div>
          <div>
            <label className="text-xs font-bold text-[#888] block mb-1.5 uppercase">{t('forms.floorSuite')}</label>
            <input 
              type="text" 
              value={formData.floorSuite}
              onChange={e => setFormData({...formData, floorSuite: e.target.value})}
              className="w-full bg-[#141414] border border-[#2a2a2a] rounded-xl px-4 py-3 text-white text-sm"
              placeholder="2º B"
            />
          </div>
        </div>

        <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 mb-4">
          <div>
            <label className="text-xs font-bold text-[#888] block mb-1.5 uppercase">{t('shopSettings.chairsCount')}</label>
            <input
              type="number"
              min={1}
              max={99}
              value={formData.chairsCount}
              onChange={e => setFormData({...formData, chairsCount: e.target.value})}
              className="w-full bg-[#141414] border border-[#2a2a2a] rounded-xl px-4 py-3 text-white text-sm"
              placeholder={t('forms.chairsPlaceholder')}
            />
          </div>
          <div>
            <label className="text-xs font-bold text-[#888] block mb-1.5 uppercase">{t('shopSettings.establishedYear')}</label>
            <input
              type="number"
              min={1900}
              max={new Date().getFullYear()}
              value={formData.establishedYear}
              onChange={e => setFormData({...formData, establishedYear: e.target.value})}
              className="w-full bg-[#141414] border border-[#2a2a2a] rounded-xl px-4 py-3 text-white text-sm"
              placeholder={t('forms.yearEstablishedPlaceholder')}
            />
          </div>
        </div>

        <div className="mb-6">
          <label className="text-xs font-bold text-[#888] block mb-1.5 uppercase">{t('forms.description')}</label>
          <textarea
            value={formData.description}
            onChange={e => setFormData({...formData, description: e.target.value})}
            maxLength={2000}
            className="w-full bg-[#141414] border border-[#2a2a2a] rounded-xl px-4 py-3 text-white text-sm h-24 resize-none focus:border-brand-yellow outline-none"
            placeholder="Tell clients about your shop..."
          />
        </div>

        <button 
          onClick={handleSaveInfo}
          disabled={savingGlobal}
          className="bg-brand-yellow text-black px-6 py-3 rounded-xl font-bold text-sm hover:bg-yellow-500 disabled:opacity-50"
        >
          {savingGlobal ? t('settings.saving') : t('buttons.saveShopInfo')}
        </button>
      </section>

      {/* SECTION C: SOCIAL MEDIA */}
      <section className="mb-10 bg-brand-surface border border-brand-border rounded-3xl p-6">
        <h2 className="text-lg font-black mb-4">{t('headings.socialMedia')}</h2>
        
        <div className="mb-4">
          <label className="text-xs font-bold text-[#888] block mb-1.5 uppercase">{t('forms.instagram')}</label>
          <input 
            type="text" 
            value={socialData.instagram}
            onChange={e => setSocialData({...socialData, instagram: e.target.value})}
            className="w-full bg-[#141414] border border-[#2a2a2a] rounded-xl px-4 py-3 text-white text-sm"
            placeholder="@your_username"
          />
        </div>

        <div className="mb-4">
          <label className="text-xs font-bold text-[#888] block mb-1.5 uppercase">{t('forms.facebook')}</label>
          <input 
            type="text" 
            value={socialData.facebook}
            onChange={e => setSocialData({...socialData, facebook: e.target.value})}
            className="w-full bg-[#141414] border border-[#2a2a2a] rounded-xl px-4 py-3 text-white text-sm"
            placeholder="your.profile.name"
          />
        </div>

        <div className="mb-6">
          <label className="text-xs font-bold text-[#888] block mb-1.5 uppercase">{t('forms.tiktok')}</label>
          <input 
            type="text" 
            value={socialData.tiktok}
            onChange={e => setSocialData({...socialData, tiktok: e.target.value})}
            className="w-full bg-[#141414] border border-[#2a2a2a] rounded-xl px-4 py-3 text-white text-sm"
            placeholder="@your_username"
          />
        </div>

        <button 
          onClick={handleSaveSocial}
          disabled={savingSocial}
          className="bg-[#1a1a1a] text-white px-6 py-3 rounded-xl font-bold text-sm hover:bg-[#2a2a2a] disabled:opacity-50"
        >
          {savingSocial ? t('settings.saving') : t('buttons.saveSocialLinks')}
        </button>
      </section>

      {/* SECTION D: GOOGLE MAPS */}
      <section className="mb-10 bg-brand-surface border border-brand-border rounded-3xl p-6">
        <h2 className="text-lg font-black mb-1">{t('headings.googleMapsLink')}</h2>
        <p className="text-[#888] text-xs mb-5">{t('settings.helpFindLocation')}</p>

        {/* Auto-generated link from address */}
        {shop?.address?.street && (
          <div className="mb-4">
            <div className="text-[10px] font-bold text-[#555] uppercase mb-1.5">{t('settings.autoGeneratedLink')}</div>
            <a
              href={`https://www.google.com/maps/search/?api=1&query=${encodeURIComponent([shop.address.street, shop.address.buildingNumber, shop.address.city, shop.address.country].filter(Boolean).join(' '))}`}
              target="_blank"
              rel="noopener noreferrer"
              className="text-[12px] text-brand-yellow hover:underline break-all"
            >
              {t('settings.previewAutoLink')}
            </a>
          </div>
        )}

        <div className="mb-4">
          <label className="text-xs font-bold text-[#888] block mb-1.5 uppercase">{t('settings.customMapsLabel')}</label>
          <input
            type="url"
            value={googleMapsUrl}
            onChange={e => setGoogleMapsUrl(e.target.value)}
            className="w-full bg-[#141414] border border-[#2a2a2a] rounded-xl px-4 py-3 text-white text-sm focus:border-brand-yellow outline-none"
            placeholder="https://maps.google.com/..."
          />
        </div>
        <button
          onClick={handleSaveMaps}
          disabled={savingMaps}
          className="bg-brand-yellow text-black px-6 py-3 rounded-xl font-bold text-sm hover:bg-yellow-400 disabled:opacity-50"
        >
          {savingMaps ? t('settings.saving') : t('buttons.saveMapsLink')}
        </button>
      </section>

      {/* SECTION D2: CHAIR RENTAL */}
      <div style={{
        background: '#111',
        border: '1px solid #2a2a2a',
        borderRadius: 16,
        padding: 24,
        marginBottom: 24,
      }}>
        <div style={{
          fontSize: 13,
          fontWeight: 800,
          color: '#F5C518',
          letterSpacing: '0.5px',
          textTransform: 'uppercase',
          marginBottom: 20,
        }}>
          {t('shopSettings.chairRentalTitle')}
        </div>

        {/* rentsChairs toggle */}
        <div style={{
          display: 'flex',
          justifyContent: 'space-between',
          alignItems: 'flex-start',
          marginBottom: rentsChairs ? 20 : 24,
        }}>
          <div style={{
            fontSize: 14,
            fontWeight: 700,
            color: '#fff',
          }}>
            {t('shopSettings.rentsChairs')}
          </div>
          <button
            onClick={() => setRentsChairs(v => !v)}
            style={{
              width: 44,
              height: 24,
              borderRadius: 12,
              background: rentsChairs ? '#F5C518' : '#2a2a2a',
              border: 'none',
              cursor: 'pointer',
              position: 'relative',
              flexShrink: 0,
              marginLeft: 16,
              transition: 'background 0.2s',
            }}
          >
            <div style={{
              position: 'absolute',
              top: 2,
              left: rentsChairs ? 22 : 2,
              width: 20,
              height: 20,
              borderRadius: '50%',
              background: '#fff',
              transition: 'left 0.2s',
            }} />
          </button>
        </div>

        {/* availableChairsForRent — only shown when rentsChairs is true */}
        {rentsChairs && (
          <div style={{ marginBottom: 24 }}>
            <label style={{
              display: 'block',
              fontSize: 13,
              fontWeight: 700,
              color: '#aaa',
              marginBottom: 8,
            }}>
              {t('shopSettings.availableChairsForRent')}
            </label>
            <input
              type="number"
              min={1}
              max={maxRentableChairs}
              value={availableChairsForRent}
              onChange={e => {
                const val = parseInt(e.target.value) || 0;
                setAvailableChairsForRent(Math.min(Math.max(1, val), maxRentableChairs));
              }}
              style={{
                background: '#1a1a1a',
                border: '1px solid #2a2a2a',
                borderRadius: 10,
                color: '#fff',
                fontSize: 14,
                padding: '10px 14px',
                width: 100,
                outline: 'none',
              }}
            />
          </div>
        )}

        {/* Save button */}
        <button
          onClick={handleSaveChairRental}
          disabled={savingChairRental}
          style={{
            background: '#F5C518',
            color: '#0a0a0a',
            fontWeight: 900,
            fontSize: 13,
            padding: '10px 20px',
            borderRadius: 10,
            border: 'none',
            cursor: savingChairRental ? 'not-allowed' : 'pointer',
            opacity: savingChairRental ? 0.6 : 1,
          }}
        >
          {savingChairRental ? '...' : t('shopSettings.saveChairRental')}
        </button>
      </div>

      {/* SECTION E: NOTIFICATIONS */}
      <section className="mb-10 bg-brand-surface border border-brand-border rounded-3xl p-6">
        <h2 className="text-lg font-black mb-5">{t('headings.notifications')}</h2>
        {[
          {
            field: 'notifyInviteResponse' as const,
            label: t('settings.shopNotifyInvite'),
            value: notifyInviteResponse,
          },
          {
            field: 'notifyNewBooking' as const,
            label: t('settings.shopNotifyBooking'),
            value: notifyNewBooking,
          },
        ].map(({ field, label, value }) => (
          <div key={field} className="flex items-center justify-between gap-4 mb-4">
            <span className="text-sm font-bold text-[#aaa] flex-1">{label}</span>
            <button
              onClick={() => handleToggleNotif(field, !value)}
              className={`relative w-11 h-6 rounded-full transition-colors shrink-0 ${value ? 'bg-brand-yellow' : 'bg-[#2a2a2a]'}`}
            >
              <span className={`absolute top-1 w-4 h-4 rounded-full bg-white transition-all ${value ? 'left-6' : 'left-1'}`} />
            </button>
          </div>
        ))}
      </section>

      {/* SECTION F: DANGER ZONE */}
      <section className="bg-[#1a0808] border border-brand-red/30 rounded-3xl p-6">
        <h2 className="text-lg font-black text-brand-red mb-2">{t('headings.deleteShopProfile')}</h2>
        <p className="text-[#888] text-sm mb-6">{t('settings.deleteShopProfileDesc')}</p>
        <div className="w-max">
           <button 
             onClick={handleDeleteShop}
             disabled={deleting}
             className="bg-brand-red text-white px-6 py-3 rounded-xl font-bold text-[13px] tracking-wide transition-colors hover:bg-red-700 disabled:opacity-50"
           >
             {deleting ? t('shop.deleting') : t('shop.deleteShopBtn')}
           </button>
        </div>
      </section>
    </div>
  );
}

export function ShopTeamTab() {
  const { user, appUser } = useAuth();
  const { t } = useLang();
  const [inviteCode, setInviteCode] = useState('');
  const [loading, setLoading] = useState(false);
  const [errorMsg, setErrorMsg] = useState('');
  const [foundBarber, setFoundBarber] = useState<any>(null);
  const [searchAttempts, setSearchAttempts] = useState(0);
  const [searchBlockedUntil, setSearchBlockedUntil] = useState<number | null>(null);
  const [pendingInvites, setPendingInvites] = useState<any[]>([]);
  const [activeBarbers, setActiveBarbers] = useState<any[]>([]);
  const [barberUsers, setBarberUsers] = useState<Record<string, any>>({});
  const [barberSchedules, setBarberSchedules] = useState<Record<string, any>>({});
  const [removeConfirmId, setRemoveConfirmId] = useState<string | null>(null);
  const [removing, setRemoving] = useState(false);

  const todayDate = getLocalDateString();

  // ── Pending invites (real-time) ────────────────────────────────────────────
  useEffect(() => {
    if (!user) return;
    const q = query(
      collection(db, 'invites'),
      where('shopId', '==', user.uid),
      where('status', '==', 'pending')
    );
    const unsub = onSnapshot(q, async (snap) => {
      const invitesData = snap.docs.map(d => ({ id: d.id, ...d.data() } as any));
      const invitesWithNames = await Promise.all(invitesData.map(async (inv: any) => {
        const bSnap = await getDoc(doc(db, 'users', inv.barberId));
        if (bSnap.exists()) {
          const u = bSnap.data();
          return { ...inv, barberName: `${u.firstName} ${u.lastName}` };
        }
        return inv;
      }));
      invitesWithNames.sort((a: any, b: any) => b.createdAt - a.createdAt);
      setPendingInvites(invitesWithNames);
    });
    return () => unsub();
  }, [user]);

  // ── Active team (real-time) ────────────────────────────────────────────────
  useEffect(() => {
    if (!user) return;
    const q = query(collection(db, 'professionalProfiles'), where('businessId', '==', user.uid));
    const unsub = onSnapshot(q, (snap) => {
      const barbers = snap.docs.map(d => ({ id: d.id, ...d.data() } as any));
      setActiveBarbers(barbers);
    });
    return () => unsub();
  }, [user]);

  // ── Fetch user data + schedules for each active barber ────────────────────
  useEffect(() => {
    if (activeBarbers.length === 0) return;
    const fetchBarberDetails = async () => {
      const usersMap: Record<string, any> = {};
      const schedulesMap: Record<string, any> = {};
      await Promise.all(activeBarbers.map(async (b: any) => {
        const barberId = b.userId || b.id;
        // User data
        const uSnap = await getDoc(doc(db, 'users', barberId));
        if (uSnap.exists()) usersMap[b.id] = uSnap.data();
        // Schedule
        const sSnap = await getDoc(doc(db, 'schedules', `${barberId}_shard_0`));
        if (sSnap.exists()) schedulesMap[b.id] = sSnap.data();
      }));
      setBarberUsers(usersMap);
      setBarberSchedules(schedulesMap);
    };
    fetchBarberDetails();
  }, [activeBarbers]);

  // ── Search barber by code ──────────────────────────────────────────────────
  const handleSearch = async () => {
    if (!inviteCode) return;

    // Rate limit check
    if (searchBlockedUntil && Date.now() < searchBlockedUntil) {
      const secondsLeft = Math.ceil((searchBlockedUntil - Date.now()) / 1000);
      toast.error(t('settings.tooManySearches').replace('{n}', String(secondsLeft)));
      return;
    }

    // Input format validation
    const codePattern = /^TZB-[A-Z0-9]{6}$/;
    const normalised = inviteCode.trim().toUpperCase();
    if (!codePattern.test(normalised)) {
      setErrorMsg(t('errors.barberCodeFormat'));
      return;
    }

    // Increment attempt counter
    const newAttempts = searchAttempts + 1;
    setSearchAttempts(newAttempts);
    if (newAttempts >= 10) {
      setSearchBlockedUntil(Date.now() + (5 * 60 * 1000));
      setSearchAttempts(0);
      toast.error(t('settings.tooManySearches').replace('{n}', '300'));
      return;
    }

    setLoading(true);
    setErrorMsg('');
    setFoundBarber(null);

    try {
      const q = query(collection(db, 'professionalProfiles'), where('professionalCode', '==', normalised));
      const snap = await getDocs(q);

      if (snap.empty) {
        setErrorMsg(t('errors.noBarberFound'));
        return;
      }

      const barberData = snap.docs[0].data();
      const barberId = snap.docs[0].id;
      const targetUid = barberData.userId || barberId;
      const bUserSnap = await getDoc(doc(db, 'users', targetUid));
      const bUserData = bUserSnap.exists() ? bUserSnap.data() : {};

      setFoundBarber({
        ...barberData,
        id: barberId,
        name: `${bUserData.firstName || ''} ${bUserData.lastName || ''}`.trim() || t('misc.barberFallback'),
        userId: barberData.userId || barberId,
      });
    } catch (err) {
      console.error('handleSearch error:', err);
      setErrorMsg('Something went wrong. Please try again.');
    } finally {
      setLoading(false);
    }
  };

  // ── Send invite ────────────────────────────────────────────────────────────
  const handleInvite = async () => {
    if (!user || !appUser || !foundBarber) return;
    setLoading(true);
    setErrorMsg('');

    try {
      const inviteQ = query(
        collection(db, 'invites'),
        where('shopId', '==', user.uid),
        where('barberId', '==', foundBarber.userId),
        where('status', '==', 'pending')
      );
      const inviteSnap = await getDocs(inviteQ);
      if (!inviteSnap.empty) {
        setErrorMsg(t('errors.inviteAlreadySent'));
        setLoading(false);
        return;
      }
      if (foundBarber.businessId === user.uid) {
        setErrorMsg(t('errors.barberAlreadyOnTeam'));
        setLoading(false);
        return;
      }

      const businessSnap = await getDoc(doc(db, 'businesses', user.uid));
      const shopName = businessSnap.exists() ? businessSnap.data().name : (appUser?.firstName ? `${appUser.firstName}'s Shop` : 'Unknown Shop');

      const currentTime = Date.now();
      await addDoc(collection(db, 'invites'), inviteSchema.parse({
        shopId: user.uid,
        shopName,
        barberId: foundBarber.userId,
        status: 'pending',
        createdAt: currentTime,
      }));

      await addDoc(collection(db, 'notifications'), notificationSchema.parse({
        userId: foundBarber.userId,
        message: `${shopName} invited you to join their team! Check your invites.`,
        read: false,
        linkTo: '/dashboard/barber/invites',
        createdAt: currentTime,
      }));
      updateDoc(doc(db, 'users', foundBarber.userId), { unreadCount: increment(1) }).catch(console.error);

      setFoundBarber(null);
      setInviteCode('');
      toast.success(t('success.inviteSent'));
    } catch (e: any) {
      console.error(e);
      setErrorMsg(t('settings.failedSendInvite'));
    }
    setLoading(false);
  };

  const handleCancelInvite = async (inviteId: string) => {
    try {
      await setDoc(doc(db, 'invites', inviteId), inviteUpdateSchema.parse({ status: 'cancelled', respondedAt: Date.now() }), { merge: true });
    } catch (e) {
      console.error(e);
    }
  };

  // ── Remove barber from shop ────────────────────────────────────────────────
  const handleRemove = async (barberId: string, barberName: string) => {
    if (!user) return;
    setRemoving(true);
    try {
      await updateDoc(doc(db, 'professionalProfiles', barberId), {
        businessId: null,
      });
      // Cancel any pending invites
      const invQ = query(collection(db, 'invites'), where('shopId', '==', user.uid), where('barberId', '==', barberId));
      const invSnap = await getDocs(invQ);
      await Promise.all(invSnap.docs.map(d => deleteDoc(doc(db, 'invites', d.id))));
      setRemoveConfirmId(null);
      toast.success(t('settings.removedFromTeam').replace('{name}', barberName));
    } catch (e) {
      console.error(e);
      toast.error(t('errors.failedRemoveBarber'));
    }
    setRemoving(false);
  };

  // ── Helpers ────────────────────────────────────────────────────────────────
  const isWorkingToday = (barberId: string) => {
    const sched = barberSchedules[barberId];
    const slots: string[] = sched?.availableSlots?.[todayDate] ?? [];
    return slots.length > 0;
  };

  const getBarberName = (barber: any) => {
    const u = barberUsers[barber.id];
    if (u) return `${u.firstName || ''} ${u.lastName || ''}`.trim();
    return barber.name || t('misc.barberFallback');
  };

  // ── Invite status label ────────────────────────────────────────────────────
  const getInviteStatus = () => {
    if (!foundBarber) return null;
    if (foundBarber.businessId === user?.uid) return 'already_here';
    if (foundBarber.businessId && foundBarber.businessId !== user?.uid) return 'in_other_shop';
    return 'available';
  };

  return (
    <div className="animate-fadeUp max-w-2xl">
      <h1 className="text-2xl font-black mb-6">{t('headings.team')}</h1>

      {/* ── INVITE A BARBER ─────────────────────────────────────────────── */}
      <div className="bg-brand-surface border border-brand-border rounded-3xl p-6 mb-8">
        <h2 className="text-lg font-black mb-1">{t('headings.inviteBarber')}</h2>
        <p className="text-xs text-[#888] mb-5">{t('settings.inviteBarberDesc')}</p>
        <div className="flex gap-3">
          <input
            type="text"
            placeholder="TZB-XXXXXX"
            value={inviteCode}
            onChange={(e) => { setInviteCode(e.target.value.toUpperCase()); setFoundBarber(null); setErrorMsg(''); }}
            onKeyDown={(e) => e.key === 'Enter' && handleSearch()}
            className="flex-1 bg-[#141414] border border-[#2a2a2a] rounded-xl px-4 py-3 text-white font-mono uppercase text-sm outline-none focus:border-brand-yellow transition-colors"
          />
          <button
            onClick={handleSearch}
            disabled={loading || !inviteCode}
            className="bg-brand-yellow text-black px-6 py-3 rounded-xl font-black text-sm hover:bg-yellow-400 disabled:opacity-50 transition-colors"
          >
            {loading ? '...' : t('buttons.search')}
          </button>
        </div>

        {errorMsg && (
          <div className="mt-4 text-brand-red text-sm font-bold bg-[#1a0808] border border-[#3b1a1a] rounded-xl p-3">
            {errorMsg}
          </div>
        )}

        {/* ── BARBER PREVIEW CARD ───────────────────────────────────────── */}
        {foundBarber && (() => {
          const status = getInviteStatus();
          return (
            <div className="mt-5 bg-[#141414] border border-[#2a2a2a] rounded-2xl p-5">
              <div className="flex items-start gap-4 mb-4">
                <div className="w-12 h-12 rounded-xl bg-brand-yellow flex items-center justify-center font-black text-lg text-black shrink-0">
                  {foundBarber.name?.[0] || '?'}
                </div>
                <div className="flex-1 min-w-0">
                  <div className="font-black text-base">{foundBarber.name}</div>
                  <div className="text-xs text-brand-yellow mt-0.5 font-bold">
                    ★ {foundBarber.rating?.toFixed(1) || '—'}{foundBarber.reviewCount > 0 ? ` · ${foundBarber.reviewCount} ${t('profile.reviewsCount')}` : ''}
                  </div>
                  {foundBarber.specialties?.length > 0 && (
                    <div className="flex flex-wrap gap-1 mt-2">
                      {(foundBarber.specialties as string[]).slice(0, 3).map((s: string) => (
                        <span key={s} className="text-[10px] font-bold bg-[#1a1a1a] text-[#888] px-2 py-0.5 rounded-md">{s}</span>
                      ))}
                    </div>
                  )}
                  {foundBarber.languages?.length > 0 && (
                    <div className="flex flex-wrap gap-1 mt-1.5">
                      {(foundBarber.languages as string[]).map((l: string) => (
                        <span key={l} className="text-[10px] font-bold bg-[#1a1a1a] text-[#555] px-2 py-0.5 rounded-md">{l}</span>
                      ))}
                    </div>
                  )}
                </div>
              </div>

              {status === 'already_here' && (
                <div className="text-sm font-bold text-brand-green mb-4">
                  {t('errors.alreadyOnTeam').replace('{name}', foundBarber.name)}
                </div>
              )}
              {status === 'in_other_shop' && (
                <div className="text-sm font-bold text-brand-orange mb-4">
                  {t('errors.barberInAnotherShop').replace('{name}', foundBarber.name)}
                </div>
              )}

              <div className="flex gap-3">
                {status === 'available' && (
                  <button
                    onClick={handleInvite}
                    disabled={loading}
                    className="bg-brand-yellow text-black px-6 py-2.5 rounded-xl font-black text-sm hover:bg-yellow-400 disabled:opacity-50 transition-colors"
                  >
                    {loading ? t('forms.sending') : t('buttons.sendInvite')}
                  </button>
                )}
                <button
                  onClick={() => { setFoundBarber(null); setInviteCode(''); }}
                  className="text-[#888] hover:text-white text-sm font-bold px-4 py-2.5 transition-colors"
                >
                  {t('buttons.cancel')}
                </button>
              </div>
            </div>
          );
        })()}
      </div>

      {/* ── PENDING INVITES ──────────────────────────────────────────────────── */}
      <h2 className="font-extrabold text-base mb-3">{t('headings.pendingInvites')}</h2>
      {pendingInvites.length === 0 ? (
        <div className="text-[#555] text-sm mb-8">{t('emptyStates.noPendingInvites')}</div>
      ) : (
        <div className="flex flex-col gap-3 mb-8">
          {pendingInvites.map(inv => (
            <div key={inv.id} className="bg-brand-surface border border-brand-border rounded-2xl p-4 flex items-center justify-between">
              <div>
                <div className="font-extrabold">{inv.barberName || t('misc.barberFallback')}</div>
                <div className="text-xs text-[#888] mt-0.5">{t('shop.sentDate').replace('{date}', new Date(inv.createdAt).toLocaleDateString())}</div>
              </div>
              <div className="flex items-center gap-4">
                <span className="text-[10px] font-black tracking-wider text-brand-yellow bg-brand-yellow/10 px-2.5 py-1 rounded-md uppercase">
                  {t('status.pending')}
                </span>
                <button onClick={() => handleCancelInvite(inv.id)} className="text-xs font-bold text-[#888] hover:text-white transition-colors">
                  {t('buttons.cancel')}
                </button>
              </div>
            </div>
          ))}
        </div>
      )}

      {/* ── ACTIVE TEAM ──────────────────────────────────────────────────────── */}
      <h2 className="font-extrabold text-base mb-3">{t('shop.teamCount').replace('{n}', String(activeBarbers.length))}</h2>
      {activeBarbers.length === 0 ? (
        <div className="text-[#555] text-sm">{t('emptyStates.noBarbers')}</div>
      ) : (
        <div className="flex flex-col gap-3">
          {activeBarbers.map((barber: any) => {
            const barberId = barber.id;
            const u = barberUsers[barberId];
            const name = u ? `${u.firstName || ''} ${u.lastName || ''}`.trim() : t('misc.barberFallback');
            const photoUrl = u?.photoUrl || u?.profilePhotoUrl || '';
            const working = isWorkingToday(barberId);
            const isConfirming = removeConfirmId === barberId;

            return (
              <div key={barberId} className={`bg-brand-surface border rounded-2xl p-4 transition-all ${isConfirming ? 'border-brand-red/40' : 'border-brand-border'}`}>
                <div className="flex items-center gap-3.5">
                  {/* Avatar */}
                  <div className="w-11 h-11 rounded-xl overflow-hidden bg-[#1a1a1a] border border-[#2a2a2a] shrink-0 flex items-center justify-center">
                    {photoUrl ? (
                      <Image src={photoUrl} alt={name} width={44} height={44} className="object-cover w-full h-full" />
                    ) : (
                      <span className="font-black text-base text-white">{name[0] || '?'}</span>
                    )}
                  </div>

                  {/* Info */}
                  <div className="flex-1 min-w-0">
                    <div className="flex items-center gap-2 flex-wrap">
                      <span className="font-extrabold text-[15px]">{name}</span>
                      <span className={`text-[10px] font-bold ${working ? 'text-brand-green' : 'text-[#555]'}`}>
                        ● {working ? t('status.workingToday') : t('status.offToday')}
                      </span>
                    </div>
                    {(barber.rating > 0 || barber.reviewCount > 0) && (
                      <div className="text-xs text-[#888] mt-0.5">
                        ★ {barber.rating?.toFixed(1) || '—'}{barber.reviewCount > 0 ? ` · ${barber.reviewCount} ${t('profile.reviewsCount')}` : ''}
                      </div>
                    )}
                    {barber.specialties?.length > 0 && (
                      <div className="flex gap-1 mt-1.5 flex-wrap">
                        {(barber.specialties as string[]).slice(0, 2).map((s: string) => (
                          <span key={s} className="text-[10px] font-bold bg-[#1a1a1a] text-[#666] px-2 py-0.5 rounded-md">{s}</span>
                        ))}
                      </div>
                    )}
                  </div>

                  {/* Actions */}
                  <div className="flex flex-col items-end gap-2 shrink-0">
                    <Link href={`/barber/${barberId}`} className="text-[11px] font-bold text-brand-yellow hover:underline">
                      {t('buttons.viewProfile')}
                    </Link>
                    <button
                      onClick={() => setRemoveConfirmId(isConfirming ? null : barberId)}
                      className="text-[11px] font-bold text-brand-red hover:underline"
                    >
                      {isConfirming ? t('buttons.keep') : t('buttons.remove')}
                    </button>
                  </div>
                </div>

                {/* Confirm removal */}
                {isConfirming && (
                  <div className="mt-4 pt-4 border-t border-[#2a2a2a]">
                    <p className="text-xs text-[#888] font-bold mb-3">
                      Remove <span className="text-white">{name}</span> from your team? They will return to solo mode. Their existing bookings will <span className="text-white">NOT</span> be cancelled.
                    </p>
                    <div className="flex gap-2">
                      <button
                        onClick={() => handleRemove(barberId, name)}
                        disabled={removing}
                        className="bg-brand-red text-white text-xs font-black px-4 py-2 rounded-lg hover:bg-red-700 disabled:opacity-50 transition-colors"
                      >
                        {removing ? t('settings.removing') : t('buttons.yesRemove')}
                      </button>
                      <button
                        onClick={() => setRemoveConfirmId(null)}
                        className="text-[#888] text-xs font-bold px-4 py-2 hover:text-white transition-colors"
                      >
                        {t('buttons.cancel')}
                      </button>
                    </div>
                  </div>
                )}
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}

