function makeEnergyShell(opts: {
  radius?: number
  detail?: number
  color?: THREE.Color
  intensity?: number
  displace?: number
  speed?: number
  opacity?: number
}) {
  const {
    radius = 1.35,
    detail = 48,
    color = GOLD,
    intensity = 1.6,
    displace = 0.08,
    speed = 0.6,
    opacity = 1,
  } = opts

  const uniforms = {
    uTime: { value: 0 },
    uColor: { value: color.clone() },
    uIntensity: { value: intensity },
    uDisplace: { value: displace },
    uOpacity: { value: opacity },
  }

  const material = new THREE.ShaderMaterial({
    uniforms,
    transparent: true,
    depthWrite: false,
    blending: THREE.AdditiveBlending,
    side: THREE.DoubleSide,
    vertexShader: SHELL_VERTEX,
    fragmentShader: SHELL_FRAGMENT,
  })

  const mesh = new THREE.Mesh(new THREE.IcosahedronGeometry(radius, detail), material)
  return { mesh, material, speed }
}

function makeOrbitalRing(opts: {
  radius?: number
  tube?: number
  color?: THREE.Color
  opacity?: number
  speed?: number
  tilt?: [number, number, number]
}) {
  const {
    radius = 2,
    tube = 0.012,
    color = GOLD,
    opacity = 0.5,
    speed = 0.25,
    tilt = [Math.PI / 2.4, 0, 0] as [number, number, number],
  } = opts

  const material = new THREE.MeshBasicMaterial({
    color,
    transparent: true,
    opacity,
    blending: THREE.AdditiveBlending,
    depthWrite: false,
  })
  const mesh = new THREE.Mesh(new THREE.TorusGeometry(radius, tube, 16, 160), material)
  // Initial tilt on x/y; rotation.z is driven by the animation loop.
  mesh.rotation.x = tilt[0]
  mesh.rotation.y = tilt[1]
  return { mesh, material, radius, speed, baseOpacity: opacity }
}

export default function TitizaCoreScene({
  genesis = false,
  onGenesisComplete,
  apiRef,
  sustainedState = 'idle',
  ringTrigger,
}: TitizaCoreSceneProps) {
  const containerRef = useRef<HTMLDivElement>(null)
  // Keep the latest onGenesisComplete without re-running the (heavy) scene
  // effect, whose dependency array is intentionally empty.
  const onGenesisCompleteRef = useRef(onGenesisComplete)
  onGenesisCompleteRef.current = onGenesisComplete
  // Live mirrors of the additive props so the empty-dep scene effect can read
  // their latest values each frame without re-running (same pattern as above).
  const sustainedStateRef = useRef(sustainedState)
  sustainedStateRef.current = sustainedState
  const ringTriggerRef = useRef(ringTrigger)
  ringTriggerRef.current = ringTrigger

  useEffect(() => {
    const container = containerRef.current
    if (!container) return

    const prefersReduced = window.matchMedia(
      '(prefers-reduced-motion: reduce)',
    ).matches
    // Whether the birth sequence runs at all this mount.
    const doGenesis = genesis

    /* -------------------------- renderer + camera ------------------------- */
    const renderer = new THREE.WebGLRenderer({
      antialias: true,
      alpha: true,
      powerPreference: 'high-performance',
    })
    renderer.setClearColor(0x000000, 0) // transparent background
    const initialW = container.clientWidth || 1
    const initialH = container.clientHeight || 1
    renderer.setSize(initialW, initialH)
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2)) // dpr [1, 2]
    renderer.domElement.style.display = 'block'
    container.appendChild(renderer.domElement)

    const scene = new THREE.Scene()
    const camera = new THREE.PerspectiveCamera(42, initialW / initialH, 0.1, 100)
    camera.position.set(0, 0, 6)

    /* ------------------------------- lights ------------------------------- */
    scene.add(new THREE.AmbientLight(0xffffff, 0.7))
    const key = new THREE.PointLight(GOLD_BRIGHT, 2.5)
    key.position.set(4, 5, 4)
    scene.add(key)
    const rim = new THREE.PointLight(new THREE.Color('#8a6a2a'), 1.2)
    rim.position.set(-5, -3, -2)
    scene.add(rim)
    const dir = new THREE.DirectionalLight(GOLD_BRIGHT, 1.4)
    dir.position.set(0, 2, 5)
    scene.add(dir)

    /* --------------------- rig groups (Presence + Float) ------------------ */
    const rig = new THREE.Group() // PresenceRig — pointer-reactive
    const floatGroup = new THREE.Group() // FloatRig — gentle bob/rotation
    rig.add(floatGroup)
    scene.add(rig)

    /* 1. living core — inner glow + metallic heart */
    const innerGlow = new THREE.Mesh(
      new THREE.SphereGeometry(1, 24, 24),
      new THREE.MeshBasicMaterial({
        color: GOLD_BRIGHT,
        transparent: true,
        opacity: 0.4,
        blending: THREE.AdditiveBlending,
        depthWrite: false,
      }),
    )
    floatGroup.add(innerGlow)

    const coreMat = new THREE.MeshStandardMaterial({
      color: GOLD_BRIGHT,
      emissive: GOLD,
      emissiveIntensity: 0.65,
      metalness: 0.92,
      roughness: 0.22,
      flatShading: true,
    })
    const coreHeart = new THREE.Mesh(new THREE.IcosahedronGeometry(1, 4), coreMat)
    floatGroup.add(coreHeart)

    /* 3. glass energy membranes */
    const shellA = makeEnergyShell({ radius: 1.3, intensity: 1.7, displace: 0.09, opacity: 0.9 })
    const shellB = makeEnergyShell({
      radius: 1.55,
      intensity: 0.9,
      displace: 0.05,
      speed: -0.4,
      color: GOLD_BRIGHT,
      opacity: 0.5,
    })
    floatGroup.add(shellA.mesh)
    floatGroup.add(shellB.mesh)
    const shells = [shellA, shellB]

    /* 2. glass reflection glint (added after shells so it sits on top) */
    const glintMat = new THREE.MeshBasicMaterial({
      color: GOLD_BRIGHT,
      transparent: true,
      opacity: 0.3,
      blending: THREE.AdditiveBlending,
      depthWrite: false,
    })
    const glint = new THREE.Mesh(new THREE.CircleGeometry(0.32, 32), glintMat)
    glint.position.set(-0.55, 0.7, 1.15)
    floatGroup.add(glint)

    /* 4. faint holographic wire cage */
    const holo = new THREE.Mesh(
      new THREE.IcosahedronGeometry(1, 2),
      new THREE.MeshBasicMaterial({
        color: GOLD,
        wireframe: true,
        transparent: true,
        opacity: 0.06,
        blending: THREE.AdditiveBlending,
        depthWrite: false,
      }),
    )
    holo.scale.setScalar(1.85)
    floatGroup.add(holo)

    /* 5. two gentle orbital rings on distinct planes → depth */
    const ringA = makeOrbitalRing({
      radius: 1.95,
      tube: 0.012,
      opacity: 0.4,
      speed: 0.16,
      tilt: [Math.PI / 2.3, 0.4, 0],
    })
    const ringB = makeOrbitalRing({
      radius: 2.45,
      tube: 0.008,
      color: GOLD_BRIGHT,
      opacity: 0.22,
      speed: -0.1,
      tilt: [Math.PI / 3.2, -0.5, 0.3],
    })
    floatGroup.add(ringA.mesh)
    floatGroup.add(ringB.mesh)
    const rings = [ringA, ringB]

    /* heartbeat pulse */
    const heartbeatMat = new THREE.MeshBasicMaterial({
      color: GOLD_BRIGHT,
      transparent: true,
      opacity: 0,
      blending: THREE.AdditiveBlending,
      depthWrite: false,
    })
    const heartbeat = new THREE.Mesh(new THREE.TorusGeometry(1, 0.02, 16, 128), heartbeatMat)
    floatGroup.add(heartbeat)
    const heartbeatPeriod = 8

    /* one-shot trigger ring — fired by `ringTrigger` increments. Same look and
       geometry as the genesis ring (§3.4) but wholly independent of the genesis
       timeline, so it can pulse at any time without touching birth behavior. */
    const triggerRingMat = new THREE.MeshBasicMaterial({
      color: GOLD_BRIGHT,
      transparent: true,
      opacity: 0,
      blending: THREE.AdditiveBlending,
      depthWrite: false,
    })
    const triggerRing = new THREE.Mesh(
      new THREE.TorusGeometry(1, 0.02, 16, 128),
      triggerRingMat,
    )
    triggerRing.rotation.x = Math.PI / 2.2
    triggerRing.visible = false
    floatGroup.add(triggerRing)
    let triggerRingT = -1 // elapsed seconds since last fire; < 0 = inactive
    // Seed the change-detector with the value present at mount, so an initial
    // ringTrigger (or its absence) never counts as a fire — only later changes.
    let lastRingTrigger = ringTriggerRef.current

    /* 6. inflowing particle stream */
    const PARTICLE_COUNT = 900
    const R_OUT = 3.6
    const R_IN = 0.6
    const positions = new Float32Array(PARTICLE_COUNT * 3)
    const dirs = new Float32Array(PARTICLE_COUNT * 3) // unit direction from center
    const radii = new Float32Array(PARTICLE_COUNT) // current radius along its ray
    const pSpeeds = new Float32Array(PARTICLE_COUNT)
    for (let i = 0; i < PARTICLE_COUNT; i++) {
      const u = Math.random()
      const v = Math.random()
      const theta = 2 * Math.PI * u
      const phi = Math.acos(2 * v - 1)
      const dx = Math.sin(phi) * Math.cos(theta)
      const dy = Math.sin(phi) * Math.sin(theta)
      const dz = Math.cos(phi)
      const r = R_IN + Math.random() * (R_OUT - R_IN)
      dirs[i * 3] = dx
      dirs[i * 3 + 1] = dy
      dirs[i * 3 + 2] = dz
      radii[i] = r
      pSpeeds[i] = 0.12 + Math.random() * 0.22
      positions[i * 3] = dx * r
      positions[i * 3 + 1] = dy * r
      positions[i * 3 + 2] = dz * r
    }
    const particleGeo = new THREE.BufferGeometry()
    particleGeo.setAttribute('position', new THREE.BufferAttribute(positions, 3))
    const particleMat = new THREE.PointsMaterial({
      size: 0.026,
      color: GOLD,
      transparent: true,
      opacity: 0.7,
      sizeAttenuation: true,
      blending: THREE.AdditiveBlending,
      depthWrite: false,
    })
    const particles = new THREE.Points(particleGeo, particleMat)
    floatGroup.add(particles)

    /* 7. persistent ambient orbiters — "dust around a planet". ~10 tiny motes
          on slow orbits that live for as long as the orb does (both the
          genesis path and the repeat-visit path). Distinct from the genesis
          burst (which plays once) and from the inflow stream (which flows
          inward). Added to floatGroup so they ride along once the orb is alive
          and inherit the birth reveal. */
    const DUST_COUNT = 10
    const dustPos = new Float32Array(DUST_COUNT * 3)
    const dustDir = new Float32Array(DUST_COUNT * 3)
    const dustRadius = new Float32Array(DUST_COUNT)
    const dustPhase = new Float32Array(DUST_COUNT)
    for (let i = 0; i < DUST_COUNT; i++) {
      const theta = Math.random() * Math.PI * 2
      const phi = Math.acos(2 * Math.random() - 1)
      dustDir[i * 3] = Math.sin(phi) * Math.cos(theta)
      dustDir[i * 3 + 1] = Math.sin(phi) * Math.sin(theta)
      dustDir[i * 3 + 2] = Math.cos(phi)
      dustRadius[i] = 2.0 + Math.random() * 0.7
      dustPhase[i] = Math.random() * Math.PI * 2
      dustPos[i * 3] = dustDir[i * 3] * dustRadius[i]
      dustPos[i * 3 + 1] = dustDir[i * 3 + 1] * dustRadius[i]
      dustPos[i * 3 + 2] = dustDir[i * 3 + 2] * dustRadius[i]
    }
    const dustGeo = new THREE.BufferGeometry()
    dustGeo.setAttribute('position', new THREE.BufferAttribute(dustPos, 3))
    const dust = new THREE.Points(
      dustGeo,
      new THREE.PointsMaterial({
        size: 0.03,
        color: GOLD_BRIGHT,
        transparent: true,
        opacity: 0.55,
        sizeAttenuation: true,
        blending: THREE.AdditiveBlending,
        depthWrite: false,
      }),
    )
    floatGroup.add(dust)
    // Reduced motion → orbit even slower.
    const dustSpeed = prefersReduced ? 0.01 : 0.025

    /* -------------------------- genesis-only objects ---------------------- */
    // The birth-particle burst: motes converge from a loose sphere into the
    // core. Parked at the center (radius 0) until revealed, so before the
    // spawn phase they read as a single seed point. Added to `rig` (not
    // floatGroup) so the birth is not scaled away while the orb resolves.
    const G_COUNT = 140
    const gDir = new Float32Array(G_COUNT * 3)
    const gTarget = new Float32Array(G_COUNT)
    const gPos = new Float32Array(G_COUNT * 3)
    for (let i = 0; i < G_COUNT; i++) {
      const theta = Math.random() * Math.PI * 2
      const phi = Math.acos(2 * Math.random() - 1)
      gDir[i * 3] = Math.sin(phi) * Math.cos(theta)
      gDir[i * 3 + 1] = Math.sin(phi) * Math.sin(theta)
      gDir[i * 3 + 2] = Math.cos(phi)
      gTarget[i] = 1.2 + Math.random() * 0.7
      // start collapsed at center
      gPos[i * 3] = 0
      gPos[i * 3 + 1] = 0
      gPos[i * 3 + 2] = 0
    }
    const genesisGeo = new THREE.BufferGeometry()
    genesisGeo.setAttribute('position', new THREE.BufferAttribute(gPos, 3))
    const genesisMat = new THREE.PointsMaterial({
      size: 0.05,
      color: GOLD_BRIGHT,
      transparent: true,
      opacity: 0,
      sizeAttenuation: true,
      blending: THREE.AdditiveBlending,
      depthWrite: false,
    })
    const genesisBurst = new THREE.Points(genesisGeo, genesisMat)
    genesisBurst.visible = doGenesis
    rig.add(genesisBurst)

    // One-shot expanding ring pulse as the orb resolves (§3.4).
    const genesisRingMat = new THREE.MeshBasicMaterial({
      color: GOLD_BRIGHT,
      transparent: true,
      opacity: 0,
      blending: THREE.AdditiveBlending,
      depthWrite: false,
    })
    const genesisRing = new THREE.Mesh(
      new THREE.TorusGeometry(1, 0.02, 16, 128),
      genesisRingMat,
    )
    genesisRing.rotation.x = Math.PI / 2.2
    genesisRing.visible = doGenesis
    rig.add(genesisRing)

    // The orb is born hidden on the genesis path; already full-size otherwise.
    floatGroup.scale.setScalar(doGenesis ? 0 : 1)

    /* ----------------------- pointer (cursor) tracking -------------------- */
    // Normalized device coords relative to the canvas, matching r3f's pointer.
    const pointer = new THREE.Vector2(0, 0)
    const onPointerMove = (e: PointerEvent) => {
      const rect = renderer.domElement.getBoundingClientRect()
      if (rect.width === 0 || rect.height === 0) return
      pointer.x = ((e.clientX - rect.left) / rect.width) * 2 - 1
      pointer.y = -(((e.clientY - rect.top) / rect.height) * 2 - 1)
    }
    window.addEventListener('pointermove', onPointerMove)

    /* ------------------------------ resize -------------------------------- */
    const onResize = () => {
      const w = container.clientWidth || 1
      const h = container.clientHeight || 1
      camera.aspect = w / h
      camera.updateProjectionMatrix()
      renderer.setSize(w, h)
    }
    window.addEventListener('resize', onResize)

    /* ---------------------- imperative reactions (API) -------------------- */
    // Eye-contact = a brief sustained brighten; pulse = a quick heartbeat.
    // Both decay on their own in the loop. Reactions are muted under reduced
    // motion (the brighten still applies faintly; the scale pulse is dropped).
    let glowBoost = 0 // current brighten amount
    let glowTarget = 0 // where brighten is easing toward
    let pulseVal = 0 // quick heartbeat, decays fast
    if (apiRef) {
      apiRef.current = {
        reactEyeContact: () => {
          glowTarget = prefersReduced ? 0.06 : 0.13
        },
        reactPulse: () => {
          if (!prefersReduced) pulseVal = 1
        },
      }
    }

    /* --------------------------- animation loop --------------------------- */
    const clock = new THREE.Clock()
    const floatOffset = Math.random() * 10000
    let raf = 0
    let genesisComplete = !doGenesis
    const fireGenesisComplete = () => {
      if (genesisComplete) return
      genesisComplete = true
      onGenesisCompleteRef.current?.()
    }

    const animate = () => {
      raf = requestAnimationFrame(animate)
      const delta = clock.getDelta()
      const t = clock.elapsedTime

      // ---- genesis birth sequence (plays once, drives floatGroup.scale) ----
      if (doGenesis && !genesisComplete) {
        const gt = t
        const gArr = genesisGeo.attributes.position.array as Float32Array
        if (prefersReduced) {
          // Reduced motion: collapse to a ~1.5s scale/fade to the resting orb.
          const p = clamp01(gt / 1.5)
          floatGroup.scale.setScalar(easeOutCubic(p))
          genesisBurst.visible = false
          genesisRing.visible = false
          if (gt >= 1.5) fireGenesisComplete()
        } else if (gt < 0.8) {
          // 0.0–0.8s — a single seed point fades in at center.
          genesisMat.opacity = clamp01(gt / 0.8)
          for (let i = 0; i < G_COUNT; i++) {
            gArr[i * 3] = 0
            gArr[i * 3 + 1] = 0
            gArr[i * 3 + 2] = 0
          }
          genesisGeo.attributes.position.needsUpdate = true
          floatGroup.scale.setScalar(0)
        } else if (gt < 1.8) {
          // 0.8–1.8s — points spawn on an accelerating (ease-in) curve into a
          // loose sphere.
          const p = (gt - 0.8) / 1.0
          const eased = p * p
          const revealCount = 1 + Math.floor(eased * (G_COUNT - 1))
          genesisMat.opacity = 1
          for (let i = 0; i < G_COUNT; i++) {
            const r = i < revealCount ? gTarget[i] * eased : 0
            gArr[i * 3] = gDir[i * 3] * r
            gArr[i * 3 + 1] = gDir[i * 3 + 1] * r
            gArr[i * 3 + 2] = gDir[i * 3 + 2] * r
          }
          genesisGeo.attributes.position.needsUpdate = true
          floatGroup.scale.setScalar(0)
        } else if (gt < 2.8) {
          // 1.8–2.8s — points drift toward center (ease-in-out cubic), losing
          // individual identity and fading as they blend into the glow.
          const p = (gt - 1.8) / 1.0
          const e = easeInOutCubic(p)
          genesisMat.opacity = 1 - e
          for (let i = 0; i < G_COUNT; i++) {
            const r = THREE.MathUtils.lerp(gTarget[i], 0.2, e)
            gArr[i * 3] = gDir[i * 3] * r
            gArr[i * 3 + 1] = gDir[i * 3 + 1] * r
            gArr[i * 3 + 2] = gDir[i * 3 + 2] * r
          }
          genesisGeo.attributes.position.needsUpdate = true
          floatGroup.scale.setScalar(0)
        } else if (gt < 4.5) {
          // 2.8–4.5s — orb resolves to full size with a single expanding ring
          // pulse and a slight spring overshoot-settle.
          const p = clamp01((gt - 2.8) / 1.7)
          genesisBurst.visible = false
          floatGroup.scale.setScalar(Math.max(0, backOut(p)))
          genesisRing.visible = true
          genesisRing.scale.setScalar(1 + p * 2.4)
          genesisRingMat.opacity = (1 - p) * 0.5
        } else {
          // 4.5s+ — hand off to the existing resting behavior.
          floatGroup.scale.setScalar(1)
          genesisBurst.visible = false
          genesisRing.visible = false
          fireGenesisComplete()
        }
      }

      // ---- held presence state (additive; 'idle' contributes nothing) ----
      const heldState = sustainedStateRef.current
      // 'bright' keeps glowTarget pinned at the eye-contact magnitude while
      // active, so the existing glow machinery holds it up and — once the state
      // returns to 'idle' — releases it smoothly via the slow-release line below.
      if (heldState === 'bright') {
        const brightHold = prefersReduced ? 0.06 : 0.13
        if (glowTarget < brightHold) glowTarget = brightHold
      }
      // 'thinking' is a continuous low-amplitude loop that holds while active
      // (0 when idle → no effect). Distinct from the one-shot pulseVal.
      const thinking = heldState === 'thinking' && !prefersReduced ? 1 : 0
      const thinkingWave = thinking * (0.5 + 0.5 * Math.sin(t * 4))

      // ---- one-shot ring trigger (increment-to-fire) ----
      if (ringTriggerRef.current !== lastRingTrigger) {
        lastRingTrigger = ringTriggerRef.current
        triggerRingT = 0 // (re)start the expanding ring
        const tick = prefersReduced ? 0.06 : 0.13 // brief glow tick
        if (glowTarget < tick) glowTarget = tick
      }
      if (triggerRingT >= 0) {
        triggerRingT += delta
        const p = clamp01(triggerRingT / 1.2)
        triggerRing.visible = true
        triggerRing.scale.setScalar(1 + p * 2.4)
        triggerRingMat.opacity = (1 - p) * 0.5
        if (p >= 1) {
          triggerRing.visible = false
          triggerRingT = -1
        }
      }

      // ---- reaction envelopes (eye-contact brighten + quick pulse) ----
      glowBoost = THREE.MathUtils.damp(glowBoost, glowTarget, 6, delta)
      glowTarget = THREE.MathUtils.damp(glowTarget, 0, 0.5, delta) // slow release
      pulseVal = THREE.MathUtils.damp(pulseVal, 0, 9, delta) // quick release

      // ambient orbiters — slow rotation + faint radius breathing
      dust.rotation.y = t * dustSpeed * 2
      dust.rotation.x = Math.sin(t * 0.05) * 0.3
      dust.scale.setScalar(1 + Math.sin(t * 0.3) * 0.03)

      // PresenceRig — calm rotation toward the cursor + subtle parallax drift
      const targetY = pointer.x * 0.35
      const targetX = -pointer.y * 0.25
      rig.rotation.y = THREE.MathUtils.damp(rig.rotation.y, targetY, 1.6, delta)
      rig.rotation.x = THREE.MathUtils.damp(rig.rotation.x, targetX, 1.6, delta)
      rig.position.x = THREE.MathUtils.damp(rig.position.x, pointer.x * 0.22, 1.4, delta)
      rig.position.y = THREE.MathUtils.damp(rig.position.y, pointer.y * 0.16, 1.4, delta)

      // FloatRig — gentle bob + rotation wobble (drei Float math, speed 1)
      const tf = floatOffset + t
      floatGroup.rotation.x = (Math.cos(tf / 4) / 8) * 0.18
      floatGroup.rotation.y = (Math.sin(tf / 4) / 8) * 0.18
      floatGroup.rotation.z = (Math.sin(tf / 4) / 20) * 0.18
      floatGroup.position.y = (Math.sin(tf / 4) / 10) * 0.45

      // inner glow — breathing scale + opacity (lifted by eye-contact brighten)
      const glowScale = 0.72 + Math.sin(t * 0.75) * 0.05
      innerGlow.scale.setScalar(glowScale)
      ;(innerGlow.material as THREE.MeshBasicMaterial).opacity =
        (0.34 + Math.sin(t * 0.75) * 0.1) * (1 + glowBoost)

      // core heart — slow spin, breathe, inner-light pulse
      // (+ eye-contact brighten on emissive, + quick heartbeat on scale/emissive)
      coreHeart.rotation.y = -t * 0.14
      coreHeart.scale.setScalar(
        0.55 + Math.sin(t * 0.7) * 0.028 + pulseVal * 0.06 + thinkingWave * 0.03,
      )
      coreMat.emissiveIntensity =
        (0.65 + Math.sin(t * 0.7) * 0.22) * (1 + glowBoost) +
        pulseVal * 0.4 +
        thinkingWave * 0.25

      // energy shells — flowing uniforms + rotation + breathing scale
      const shellScale = 1 + Math.sin(t * 0.55) * 0.045
      for (const s of shells) {
        s.material.uniforms.uTime.value = t * s.speed
        s.mesh.rotation.y = t * 0.06
        s.mesh.rotation.x = t * 0.025
        s.mesh.scale.setScalar(shellScale)
      }

      // glass glint — drifting highlight
      glint.scale.setScalar(0.6 + Math.sin(t * 0.25) * 0.15)
      glintMat.opacity = 0.28 + Math.sin(t * 0.5) * 0.08

      // holographic wire — slow counter-rotation
      holo.rotation.y = -t * 0.1
      holo.rotation.x = t * 0.045

      // orbital rings — spin on own axis + opacity breathing
      for (const ring of rings) {
        ring.mesh.rotation.z = t * ring.speed
        ring.material.opacity = ring.baseOpacity * (0.7 + Math.sin(t * 0.5 + ring.radius) * 0.3)
      }

      // heartbeat wave — expand + fade every `period` seconds
      const phase = (t % heartbeatPeriod) / heartbeatPeriod
      heartbeat.scale.setScalar(1.2 + phase * 2.4)
      heartbeatMat.opacity = Math.max(0, 0.45 * (1 - phase) * (1 - phase))

      // particle stream — swirl + inflow toward the core, respawn outward
      particles.rotation.y = t * 0.03
      const arr = particleGeo.attributes.position.array as Float32Array
      for (let i = 0; i < PARTICLE_COUNT; i++) {
        radii[i] -= pSpeeds[i] * delta
        if (radii[i] <= R_IN) {
          radii[i] = R_OUT * (0.85 + Math.random() * 0.15)
        }
        const r = radii[i]
        arr[i * 3] = dirs[i * 3] * r
        arr[i * 3 + 1] = dirs[i * 3 + 1] * r
        arr[i * 3 + 2] = dirs[i * 3 + 2] * r
      }
      particleGeo.attributes.position.needsUpdate = true

      renderer.render(scene, camera)
    }
    animate()

    /* ------------------------------ cleanup ------------------------------- */
    return () => {
      cancelAnimationFrame(raf)
      if (apiRef) apiRef.current = null
      window.removeEventListener('pointermove', onPointerMove)
      window.removeEventListener('resize', onResize)

      scene.traverse((obj) => {
        const mesh = obj as THREE.Mesh
        if (mesh.geometry) mesh.geometry.dispose()
        const material = mesh.material
        if (material) {
          if (Array.isArray(material)) material.forEach((m) => m.dispose())
          else material.dispose()
        }
      })
      renderer.dispose()
      if (renderer.domElement.parentNode === container) {
        container.removeChild(renderer.domElement)
      }
    }
  }, [])

  return <div ref={containerRef} style={{ width: '100%', height: '100%' }} />
}

