export function TitizaDecisionFlow({ userName = 'there' }: TitizaDecisionFlowProps) {
  void userName // reserved for later checkpoints
  const { t } = useLang()
  const apiRef = useRef<TitizaCoreApi | null>(null)
  const timersRef = useRef<number[]>([])

  // Reposition the orb from a centered-ish spot up to the fixed upper anchor.
  // Pure CSS transform on the wrapper (Frozen Decision #2). Reduced motion
  // snaps straight to the anchor (no travel).
  const [anchored, setAnchored] = useState(false)
  const [reducedMotion, setReducedMotion] = useState(false)
  const reducedRef = useRef(false) // readable inside event handlers

  // §4 greeting beats.
  const [line1Shown, setLine1Shown] = useState(false)
  const [seedShown, setSeedShown] = useState(false)
  // §5 tiles reveal (just after the seed line) + current selection.
  const [tilesShown, setTilesShown] = useState(false)
  const [selectedId, setSelectedId] = useState<string | null>(null)

  // §6 thinking moment. 'choosing' → a tile is live; 'thinking' → the brief
  // pause after a selection; 'revealed' → thinking done, Path A/B takes over
  // (built in checkpoints 4-5).
  const [stage, setStage] = useState<'choosing' | 'thinking' | 'revealed'>(
    'choosing',
  )
  // Whether the thinking beat has already played this session — first play is
  // 1.0s, every later one 0.6s (§6). Session-local, never Firestore.
  const thinkingPlayedRef = useRef(false)

  // A tile was chosen (§6): dim/lock the grid, react on the orb, hold the
  // thinking beat, then hand off to the reveal stage.
  const handleSelect = (categoryId: string) => {
    if (stage !== 'choosing') return
    setSelectedId(categoryId)
    setStage('thinking')

    // Orb reaction — existing API only (Frozen Decision #2). reactEyeContact is
    // the sustained ~13% brighten; reactPulse adds the emphasis beat. Literal
    // "particles quicken" (§6) would need a new scene method, which Decision #2
    // disallows, so it's approximated by this pulse.
    apiRef.current?.reactEyeContact()
    apiRef.current?.reactPulse()

    const first = !thinkingPlayedRef.current
    thinkingPlayedRef.current = true
    const duration = reducedRef.current ? 0 : first ? 1000 : 600 // §6

    timersRef.current.push(
      window.setTimeout(() => setStage('revealed'), duration),
    )
  }

  useEffect(() => {
    const prefersReduced = window.matchMedia(
      '(prefers-reduced-motion: reduce)',
    ).matches
    setReducedMotion(prefersReduced)
    reducedRef.current = prefersReduced
    const timers = timersRef.current

    // Trigger the reposition on the next frame so the transition actually runs.
    const raf = requestAnimationFrame(() => setAnchored(true))

    // First message at 1.2s; seed line ~300ms after (§4). Reduced motion shows
    // both immediately.
    timers.push(
      window.setTimeout(
        () => {
          setLine1Shown(true)
          apiRef.current?.reactEyeContact() // gentle orb brighten on the ask
        },
        prefersReduced ? 0 : 1200,
      ),
    )
    timers.push(
      window.setTimeout(() => setSeedShown(true), prefersReduced ? 0 : 1500),
    )
    // Tiles arrive just after the seed line (§5).
    timers.push(
      window.setTimeout(() => setTilesShown(true), prefersReduced ? 0 : 1800),
    )

    return () => {
      cancelAnimationFrame(raf)
      timers.forEach((id) => clearTimeout(id))
    }
  }, [])

  // Resolve the selection for the reveal stage. Path branch is on the field
  // (titizaEntryMode), never the category name (Frozen Decision #1).
  const selectedCategory = selectedId ? getCategory(selectedId) : null
  const categoryName = selectedId ? t(`category.${selectedId}`) : ''
  const revealed = stage === 'revealed'

  return (
    <div className="flex flex-col items-center text-center animate-titiza-fade-in">
      {/* Orb at the fixed upper anchor (~20-25% from top). Smaller than the
          genesis stage so the decision content has room below it. */}
      <div
        className="w-full max-w-[280px] sm:max-w-[320px]"
        style={{
          transform:
            reducedMotion || anchored ? 'translateY(0)' : 'translateY(18vh)',
          transition: reducedMotion
            ? 'none'
            : 'transform 700ms cubic-bezier(0.65, 0, 0.35, 1)',
        }}
      >
        <TitizaCore genesis={false} apiRef={apiRef} />
      </div>

      {/* Question + tiles — the selection surface. Recedes once a path opens. */}
      {!revealed && (
        <>
          <div
            aria-live="polite"
            className="-mt-2 flex max-w-xl flex-col items-center"
          >
            {line1Shown && (
              <h2 className="animate-titiza-fade-in font-serif text-3xl font-light text-foreground sm:text-4xl">
                What would you like us to work on today?
              </h2>
            )}
            {seedShown && (
              <div className="mt-3 animate-titiza-fade-in">
                <p className="text-sm font-light leading-relaxed text-muted-foreground opacity-70">
                  Your Beauty Profile becomes more personal over time.
                </p>
              </div>
            )}
          </div>

          {/* Category tiles (§5). */}
          {tilesShown && (
            <div className="mt-12 w-full max-w-xl animate-titiza-fade-in">
              <CategoryGrid
                selectedId={selectedId}
                locked={stage !== 'choosing'}
                onSelect={handleSelect}
              />
            </div>
          )}
        </>
      )}

      {/* Path A — guided analysis (§7.1). */}
      {revealed && selectedCategory?.titizaEntryMode === 'analysis' && (
        <PathAnalysis
          categoryName={categoryName}
          reducedMotion={reducedMotion}
          apiRef={apiRef}
        />
      )}

      {/* Path B — continue with professionals (§7.2). */}
      {revealed && selectedCategory?.titizaEntryMode === 'direct' && (
        <PathDirect categoryName={categoryName} apiRef={apiRef} />
      )}
    </div>
  )
}

export function TitizaHero({
  userName = 'there',
  mode = 'dashboard',
  isReturning = false,
  onBegin,
}: TitizaHeroProps) {
  const isGenesis = mode === 'genesis'
  const apiRef = useRef<TitizaCoreApi | null>(null)
  const genesisTimersRef = useRef<number[]>([])

  // Greeting reveal gates. On the dashboard path everything is present at once
  // (no delays). On the genesis path they open on the choreography below.
  // Elements are only MOUNTED once their gate is true, so screen readers get
  // nothing announced until the greeting text actually exists.
  const [line1Shown, setLine1Shown] = useState(!isGenesis)
  const [line2Shown, setLine2Shown] = useState(!isGenesis && !isReturning)
  const [ctaShown, setCtaShown] = useState(false)

  // Genesis greeting choreography, timed against the orb's onGenesisComplete
  // (fires ~4.5s in, or ~1.5s under reduced motion) rather than a standalone
  // hardcoded timer. Offsets reproduce the spec's 5.5s / 7.2s / 8.0s anchors
  // relative to a 4.5s completion.
  const handleGenesisComplete = () => {
    if (!isGenesis) return
    const timers = genesisTimersRef.current
    timers.push(
      window.setTimeout(() => {
        setLine1Shown(true) // "Hi, {userName}."  (~5.5s)
        apiRef.current?.reactEyeContact() // orb brightens ~10-15%
      }, 1000),
    )
    timers.push(
      window.setTimeout(() => {
        setLine2Shown(true) // "I'm Titiza."  (~7.2s)
        apiRef.current?.reactPulse() // quick heartbeat pulse
      }, 2700),
    )
    timers.push(
      window.setTimeout(() => setCtaShown(true), 3500), // CTA (~8.0s)
    )
  }

  // Clear any pending greeting timers on unmount.
  useEffect(() => {
    const timers = genesisTimersRef.current
    return () => timers.forEach((id) => clearTimeout(id))
  }, [])

  return (
    <section className="flex flex-col items-center text-center">
      {/* Header / branding — belongs to the resolved dashboard, not the birth.
          Hidden during genesis so the orb's birth has the stage to itself. */}
      {!isGenesis && (
        <div className="animate-titiza-fade-in">
          <p className="mb-3 text-xs font-medium uppercase tracking-[0.35em] text-muted-foreground">
            titeZMe
          </p>
          <h1 className="font-serif text-6xl font-light tracking-tight text-foreground sm:text-7xl md:text-8xl">
            <span className="titiza-shimmer-text">Titiza</span>
          </h1>
          <p className="mt-4 text-balance text-base font-light tracking-wide text-muted-foreground sm:text-lg">
            Beauty Intelligence, built around you.
          </p>
        </div>
      )}

      {/* The presence — mounted in both modes. On genesis it plays the birth;
          on dashboard it mounts already in its resting breathing state. */}
      <div className="mt-6 w-full animate-titiza-float">
        <TitizaCore
          genesis={isGenesis}
          onGenesisComplete={handleGenesisComplete}
          apiRef={apiRef}
        />
      </div>

      {/* Below the assistant — Titiza speaks. */}
      <div className="-mt-4 flex max-w-xl flex-col items-center">
        {line1Shown && (
          <p className="animate-titiza-fade-in font-serif text-3xl font-light text-foreground sm:text-4xl">
            {isReturning ? `Welcome back, ${userName}.` : `Hi, ${userName}.`}
          </p>
        )}
        {!isReturning && line2Shown && (
          <p className="mt-2 animate-titiza-fade-in font-serif text-3xl font-light text-foreground sm:text-4xl">
            {"I'm Titiza."}
          </p>
        )}

        {/* Let's Begin — genesis path only. Hairline pill, gold token, no fill,
            no gradient, no shadow, no icon. Real <button> for accessibility. */}
        {isGenesis && ctaShown && (
          <button
            type="button"
            onClick={onBegin}
            className="animate-titiza-fade-in mt-10 rounded-full border border-gold/40 px-8 py-3 text-sm font-medium uppercase tracking-[0.25em] text-gold-soft/90 transition-colors duration-300 hover:border-gold-soft hover:text-gold-soft focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-gold/50 focus-visible:ring-offset-2 focus-visible:ring-offset-background"
            style={{ animationDuration: '0.5s' }}
          >
            Let&apos;s Begin
          </button>
        )}

        {/* Dashboard content that used to live in the greeting — Titiza's line
            about growing, plus the "learning from" cards. These belong to the
            dashboard view (after Let's Begin / on repeat visits), not the
            first-meeting greeting. */}
        {!isGenesis && (
          <>
            <p
              className="mt-5 max-w-md animate-titiza-fade-up text-pretty text-base font-light leading-relaxed text-muted-foreground sm:text-lg"
              style={{ animationDelay: '0.2s', animationFillMode: 'both' }}
            >
              I grow with every professional beauty analysis and every
              conversation we have.
            </p>

            <div
              className="mt-10 w-full animate-titiza-fade-up"
              style={{ animationDelay: '0.35s', animationFillMode: 'both' }}
            >
              <p className="text-center text-xs uppercase tracking-[0.3em] text-muted-foreground">
                Learning from
              </p>
              <ul className="mt-5 grid gap-3 sm:grid-cols-3">
                {[
                  'Professional Beauty Analyses',
                  'Your Beauty Profile',
                  'Our Conversations',
                ].map((item) => (
                  <li
                    key={item}
