                  >
                    <span
                      aria-hidden="true"
                      className="size-1.5 shrink-0 rounded-full bg-gold shadow-[0_0_8px_var(--gold)]"
                    />
                    <span className="text-sm font-light text-foreground/90">
                      {item}
                    </span>
                  </li>
                ))}
              </ul>
              <p className="mt-6 text-center text-sm leading-relaxed text-muted-foreground">
