export function TypingLines({
  lines,
  startAt,
  stagger,
  elapsed,
  revealDuration = 500,
}: TypingLinesProps) {
  return (
    <ul className="flex flex-col items-center gap-2 font-mono text-xs text-muted-foreground sm:text-sm">
      {lines.map((line, i) => {
        const revealAt = startAt + i * stagger
        if (elapsed < revealAt) return null
        return (
          <li
            key={i}
            className="flex items-center gap-2"
            style={{
              animation: `filmFadeUp8 ${revealDuration}ms cubic-bezier(0.4, 0, 0.2, 1) both`,
            }}
          >
            <span
              aria-hidden="true"
              className="size-1 shrink-0 rounded-full bg-gold"
            />
            <span>{line}</span>
          </li>
        )
      })}
    </ul>
  )
}

export function VerticalMontage({
  words,
  visibleDuration,
  overlap,
  elapsed,
}: VerticalMontageProps) {
  const step = visibleDuration - overlap

  return (
    <div className="relative flex min-h-[1.4em] items-center justify-center">
      {words.map((word, i) => {
        const local = elapsed - i * step
        if (local < 0 || local > visibleDuration) return null

        const rawOpacity =
          local < FADE
            ? local / FADE
            : local > visibleDuration - FADE
              ? Math.max(0, (visibleDuration - local) / FADE)
              : 1
        const opacity = easeInOut(Math.min(1, rawOpacity))
        const scale = 0.98 + 0.02 * (local < FADE ? easeInOut(local / FADE) : 1)

        return (
          <p
            key={i}
            className="absolute whitespace-nowrap text-center font-serif text-4xl font-light tracking-tight text-foreground sm:text-5xl"
            style={{ opacity, transform: `scale(${scale})` }}
          >
            {word}
          </p>
        )
      })}
    </div>
  )
}

export function TopNav() {
  const pathname = usePathname();
  const router = useRouter();
  const { user, appUser, authLoading, logout } = useAuth();
  const { lang, setLang, t } = useLang();
  const [menuOpen, setMenuOpen] = useState(false);
  const [showLangMenu, setShowLangMenu] = useState(false);
  const langMenuRef = useRef<HTMLDivElement>(null);

  const handleLogout = async () => {
    await logout();
    router.push('/login');
  };

  const getLinkClass = (path: string) => {
    return pathname === path
      ? 'text-sm font-bold text-[#FFD600] transition-colors'
      : 'text-sm font-bold text-[#888580] hover:text-[#F0EDE8] transition-colors';
  };

  // Close drawer on route change
  useEffect(() => {
    setMenuOpen(false);
  }, [pathname]);

  // Close lang menu on outside click
  useEffect(() => {
    function handleClickOutside(e: MouseEvent) {
      if (langMenuRef.current && !langMenuRef.current.contains(e.target as Node)) {
        setShowLangMenu(false);
      }
    }
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  // Lock body scroll when drawer is open
  useEffect(() => {
    if (menuOpen) {
      document.body.style.overflow = 'hidden';
    } else {
      document.body.style.overflow = 'unset';
    }
    return () => {
      document.body.style.overflow = 'unset';
    };
  }, [menuOpen]);

  return (
    <div className="sticky top-0 left-0 right-0 z-50 flex flex-col w-full">
      <style>{`
        @keyframes langDropIn {
          from {
            opacity: 0;
            transform: translateY(-8px) scale(0.96);
          }
          to {
            opacity: 1;
            transform: translateY(0) scale(1);
          }
