export function AuthProvider({ children }: { children: React.ReactNode }) {
  const [user, setUser] = useState<FirebaseUser | null>(null);
  const [appUser, setAppUser] = useState<AppUser | null>(null);
  const [loading, setLoading] = useState(true);

  const refreshUser = async () => {
    if (user) {
      try {
        const docRef = doc(db, 'users', user.uid);
        const docSnap = await getDoc(docRef);
        if (docSnap.exists()) {
          setAppUser(docSnap.data() as AppUser);
        }
      } catch (error) {
        console.error("Error refreshing user", error);
      }
    }
  };

  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, async (firebaseUser) => {
      setUser(firebaseUser);
      
      if (firebaseUser) {
        try {
          const docRef = doc(db, 'users', firebaseUser.uid);
          let docSnap = await getDoc(docRef);
          
          if (!docSnap.exists()) {
            console.warn('User document not found, retrying in 1s...');
            await new Promise(r => setTimeout(r, 1000));
            docSnap = await getDoc(docRef);
          }
          
          if (docSnap.exists()) {
            let userData = docSnap.data() as AppUser;
            
            // Heal Check
            if (userData.role === 'professional' && !userData.isOnboarded) {
              const profileRef = doc(db, 'professionalProfiles', firebaseUser.uid);
              const profileSnap = await getDoc(profileRef);
              if (profileSnap.exists()) {
                try {
                  const { updateDoc } = await import('firebase/firestore');
                  await updateDoc(docRef, userUpdateSchema.parse({ isOnboarded: true }));
                  userData.isOnboarded = true;
                } catch (e) {
                  console.error("Failed to heal profile", e);
                }
              }
            }

            // Heal: if users doc is missing phone/city/country,
            // copy them from the professionalProfile so isProfileComplete()
            // stops returning false for a fully-onboarded professional.
            if (
              userData.role === 'professional' &&
              userData.isOnboarded === true &&
              (!userData.phone?.trim() || !userData.city?.trim() || !userData.country?.trim())
            ) {
              const profileRef = doc(db, 'professionalProfiles', firebaseUser.uid);
              const profileSnap = await getDoc(profileRef);
              if (profileSnap.exists()) {
                const p = profileSnap.data();
                const updates: Record<string, string> = {};
                if (!userData.phone?.trim() && p.phone) updates.phone = p.phone;
                if (!userData.city?.trim() && p.city)  updates.city  = p.city;
                if (!userData.country?.trim() && p.country) updates.country = p.country;
                if (Object.keys(updates).length > 0) {
                  try {
                    const { updateDoc } = await import('firebase/firestore');
                    await updateDoc(docRef, updates);
                    Object.assign(userData, updates);
                  } catch (e) {
                    console.error("Failed to heal phone/city/country from professionalProfile", e);
                  }
                }
              }
            }

            setAppUser(userData);
          } else {
            console.warn('User document not found in Firestore after retry');
            // Default appUser based on what we have
            setAppUser({
              uid: firebaseUser.uid,
              email: firebaseUser.email || '',
              role: 'client', // Default fallback
              firstName: '',
              lastName: '',
              isOnboarded: false,
              ownsShop: false
            });
          }
        } catch (error) {
          console.error("Error fetching user role", error);
        }
      } else {
        setAppUser(null);
      }
      
      setLoading(false);
    }, (error) => {
      console.error(error);
      setLoading(false);
    });

    return () => unsubscribe();
  }, []);

  const logout = async () => {
    await signOut(auth);
  };

  return (
    <AuthContext.Provider value={{ user, appUser, loading, authLoading: loading, logout, refreshUser }}>
      {children}
    </AuthContext.Provider>
  );
}

export async function cleanupBookingLock(booking: {
  barberId: string;
  date: string;
  startTime: string;
  endTime?: string;
  id: string;
}): Promise<void> {
  const lockDocRef = doc(db, 'bookingLocks', `${booking.barberId}_${booking.date}`);
  try {
    await runTransaction(db, async (t) => {
      const lockDoc = await t.get(lockDocRef);
      if (!lockDoc.exists()) return;

      const slots: any[] = lockDoc.data().slots || [];
      const updatedSlots = slots.filter((s: any) => s.bookingId !== booking.id);

      if (updatedSlots.length === 0) {
        t.delete(lockDocRef);
      } else {
        t.update(lockDocRef, { slots: updatedSlots });
      }
    });
  } catch (e) {
    // Non-critical — don't throw, just log
    console.error('Failed to clean booking lock:', e);
  }
}

export function statusColor(
  status?: ChallengeSubmissionData['status'],
): { bg: string; text: string } {
  switch (status) {
    case 'awaiting_payment':
      return { bg: 'bg-brand-yellow/10', text: 'text-brand-yellow' };
    case 'pending':
      return { bg: 'bg-[#3b3b1a]', text: 'text-brand-yellow' };
    case 'approved':
      return { bg: 'bg-[#103a1c]', text: 'text-brand-green' };
    case 'rejected':
      return { bg: 'bg-[#3a1010]', text: 'text-brand-red' };
    default:
      return { bg: 'bg-[#1a1a1a]', text: 'text-[#888]' };
  }
}

export function buildPaymentReference(
  submission: Pick<
    ChallengeSubmissionData,
    'type' | 'userId' | 'submitterName' | 'barberCode'
  >,
): string {
  const name = submission.submitterName || '';
  if (submission.type === 'barber') {
    return `${name} - ${submission.barberCode || 'NOCODE'} - titeZMe Desafío`;
  }
  return `${name} - titeZMe Desafío`;
}

