export async function deleteClientAccount(uid: string): Promise<void> {
  const mgr = new BatchManager();

  // 1. Cancel future bookings + notify barbers
  const futureBookings = await getDocs(query(
    collection(db, 'bookings'),
    where('clientId', '==', uid),
    where('status', 'in', ['pending', 'confirmed'])
  ));

  for (const booking of futureBookings.docs) {
    await mgr.update(booking.ref, {
      status: 'cancelled_by_client',
      updatedAt: Date.now(),
      cancellationReason: 'account_deleted',
    });

    const notifRef = doc(collection(db, 'notifications'));
    await mgr.set(notifRef, {
      userId: booking.data().barberId,
      type: 'booking_cancelled',
      message: 'A client deleted their account. Their booking was cancelled.',
      bookingId: booking.id,
      read: false,
      createdAt: Date.now(),
    });
  }

  // 2. Anonymize past bookings (do NOT delete — barber stats reference them)
  const pastBookings = await getDocs(query(
    collection(db, 'bookings'),
    where('clientId', '==', uid),
    where('status', 'in', PAST_STATUSES)
  ));

  for (const d of pastBookings.docs) {
    await mgr.update(d.ref, {
      clientId: DELETED_USER_ID,
      clientName: DELETED_USER_NAME,
    });
  }

  // 3. Anonymize reviews (keep rating attached to barber)
  const reviews = await getDocs(query(
    collection(db, 'reviews'),
    where('clientId', '==', uid)
  ));

  for (const d of reviews.docs) {
    await mgr.update(d.ref, {
      clientId: DELETED_USER_ID,
      clientName: DELETED_USER_NAME,
    });
  }

  // 4. Delete notifications
  const notifications = await getDocs(query(
    collection(db, 'notifications'),
    where('userId', '==', uid)
  ));

  for (const d of notifications.docs) {
    await mgr.delete(d.ref);
  }

  // 5. Delete user doc
  await mgr.delete(doc(db, 'users', uid));

  // Commit all Firestore changes
  await mgr.commit();

  // 6. Delete Firebase Auth (LAST — cannot be rolled back)
  if (auth.currentUser) {
    await deleteUser(auth.currentUser);
  }
}

export async function deleteBarberAccount(uid: string): Promise<void> {
  const mgr = new BatchManager();

  // 1. Read professional profile to check business membership
  const profileSnap = await getDoc(doc(db, 'professionalProfiles', uid));
  const profile = profileSnap.exists() ? profileSnap.data() : null;
  const businessId: string | null = profile?.businessId || null;

  // 2. Cancel future bookings + notify clients
  const futureBookings = await getDocs(query(
    collection(db, 'bookings'),
    where('barberId', '==', uid),
    where('status', 'in', ['pending', 'confirmed'])
  ));

  for (const booking of futureBookings.docs) {
    await mgr.update(booking.ref, {
      status: 'cancelled_by_barber',
      updatedAt: Date.now(),
      cancellationReason: 'account_deleted',
    });

    const notifRef = doc(collection(db, 'notifications'));
    await mgr.set(notifRef, {
      userId: booking.data().clientId,
      type: 'booking_cancelled',
      message: 'A barber you booked has deleted their account. Your booking was cancelled.',
      bookingId: booking.id,
      read: false,
      createdAt: Date.now(),
    });
  }

  // 3. Anonymize past bookings — shop history preserved because shopId stays
  const pastBookings = await getDocs(query(
    collection(db, 'bookings'),
    where('barberId', '==', uid),
    where('status', 'in', PAST_STATUSES)
  ));

  for (const d of pastBookings.docs) {
    await mgr.update(d.ref, {
      barberId: DELETED_BARBER_ID,
      barberName: DELETED_BARBER_NAME,
    });
  }

  // 4. Delete reviews this barber received
  const receivedReviews = await getDocs(query(
    collection(db, 'reviews'),
    where('providerId', '==', uid)
  ));
  for (const d of receivedReviews.docs) {
    await mgr.delete(d.ref);
  }

  // 5. Anonymize reviews this barber left as a client
  const leftReviews = await getDocs(query(
    collection(db, 'reviews'),
    where('clientId', '==', uid)
  ));
  for (const d of leftReviews.docs) {
    await mgr.update(d.ref, {
      clientId: DELETED_USER_ID,
      clientName: DELETED_USER_NAME,
    });
  }

  // 6. Notify the business owner. Membership lives on this professional's own
  //    profile (businessId), which is deleted at step 10 — so there is no
  //    shop-side team array to maintain. Skipped if not in a business or the
  //    business is already gone.
  if (businessId) {
    const businessSnap = await getDoc(doc(db, 'businesses', businessId));
    if (businessSnap.exists()) {
      const businessData = businessSnap.data();

      const notifRef = doc(collection(db, 'notifications'));
      await mgr.set(notifRef, {
        userId: businessData.ownerId,
        type: 'barber_left_shop',
        message: 'A barber on your team deleted their account and was removed from your shop.',
        read: false,
        createdAt: Date.now(),
      });
    }
  }

  // 7. Delete services
  const services = await getDocs(query(
    collection(db, 'services'),
    where('providerId', '==', uid)
  ));
  for (const d of services.docs) {
    await mgr.delete(d.ref);
  }

  // 8. Delete schedule (no-op if absent — batch.delete on a non-existent doc
  //    is harmless)
  await mgr.delete(doc(db, 'schedules', `${uid}_shard_0`));

  // 9. Delete notifications
  const notifications = await getDocs(query(
    collection(db, 'notifications'),
    where('userId', '==', uid)
  ));
  for (const d of notifications.docs) {
    await mgr.delete(d.ref);
  }

  // 10. Delete professional profile
  await mgr.delete(doc(db, 'professionalProfiles', uid));

  // 11. Delete user doc
  await mgr.delete(doc(db, 'users', uid));

  // Commit all Firestore changes
  await mgr.commit();

  // 12. Delete Firebase Auth (LAST)
  if (auth.currentUser) {
    await deleteUser(auth.currentUser);
  }
}

export async function deleteShopOwnerAccount(uid: string, shopId: string): Promise<void> {
  const mgr = new BatchManager();

  // 1. Query team members by businessId. The barbers[] array no longer exists;
  //    membership lives on each professional's own profile.
  const teamSnap = await getDocs(query(
    collection(db, 'professionalProfiles'),
    where('businessId', '==', shopId)
  ));

  // 2. Notify each team member + clear their businessId. Skip the owner — their
  //    profile gets handled by the deleteBarberAccount() call below. Per
  //    firestore.rules the owner may only clear businessId (not isSolo).
  for (const memberDoc of teamSnap.docs) {
    const barberId = memberDoc.id;
    if (barberId === uid) continue;

    await mgr.update(doc(db, 'professionalProfiles', barberId), {
      businessId: null,
    });

    const notifRef = doc(collection(db, 'notifications'));
    await mgr.set(notifRef, {
      userId: barberId,
      type: 'shop_deleted',
      message: 'The shop you were part of has been deleted. Your barber profile and cut count are safe. You are now a solo barber.',
      read: false,
      createdAt: Date.now(),
    });
  }

  // 3. Cancel future shop bookings + notify clients
  const futureBookings = await getDocs(query(
    collection(db, 'bookings'),
    where('shopId', '==', shopId),
    where('status', 'in', ['pending', 'confirmed'])
  ));

  for (const booking of futureBookings.docs) {
    await mgr.update(booking.ref, {
      status: 'cancelled',
      updatedAt: Date.now(),
      cancellationReason: 'shop_deleted',
    });

    const notifRef = doc(collection(db, 'notifications'));
    await mgr.set(notifRef, {
      userId: booking.data().clientId,
      type: 'booking_cancelled',
      message: 'The barbershop you booked has closed. Your booking was cancelled.',
      bookingId: booking.id,
      read: false,
      createdAt: Date.now(),
    });
  }

  // 4. Anonymize past shop bookings. barberId stays untouched so each barber's
  //    personal totalCuts history continues to reference the real booking.
  const pastBookings = await getDocs(query(
    collection(db, 'bookings'),
    where('shopId', '==', shopId),
    where('status', 'in', PAST_STATUSES)
  ));

  for (const d of pastBookings.docs) {
    await mgr.update(d.ref, {
      shopId: DELETED_SHOP_ID,
      shopName: DELETED_SHOP_NAME,
    });
  }

  // 5. Delete shop services
  const shopServices = await getDocs(query(
    collection(db, 'services'),
    where('providerId', '==', shopId)
  ));
  for (const d of shopServices.docs) {
    await mgr.delete(d.ref);
  }

  // 6. Delete business doc itself
  await mgr.delete(doc(db, 'businesses', shopId));

  // Commit shop-related changes
  await mgr.commit();

  // 7. Delegate owner's barber/user/Auth deletion. The team-removal step
  //    inside deleteBarberAccount is a no-op because the shop no longer
  //    exists (the if (shopSnap.exists()) check skips it).
  await deleteBarberAccount(uid);
}

export async function reauthenticateUser(password?: string): Promise<void> {
  const user = auth.currentUser;
  if (!user) throw new Error('No user logged in');

  const isGoogleUser = user.providerData.some(p => p.providerId === 'google.com');

  if (isGoogleUser) {
    const provider = new GoogleAuthProvider();
    await reauthenticateWithPopup(user, provider);
  } else {
    if (!password) throw new Error('Password required');
    const credential = EmailAuthProvider.credential(user.email!, password);
    await reauthenticateWithCredential(user, credential);
  }
}

export function validateEnv(): void {
  // Skip validation during Next.js static build analysis
  if (typeof window === 'undefined') return;

  const missing = required.filter((key) => !process.env[key]);

  if (missing.length > 0) {
    // Only warn — project uses firebase-applet-config.json as the config source
    if (process.env.NODE_ENV === 'development') {
      console.warn(
        '[titeZMe] Firebase env vars not set (using JSON config instead):\n' +
          missing.join('\n')
      );
    }
  }
}

function randInt(min: number, max: number): number {
  return Math.floor(Math.random() * (max - min + 1)) + min;
}

function pick<T>(arr: T[]): T {
  return arr[Math.floor(Math.random() * arr.length)];
}

function uid(): string {
  if (typeof crypto !== 'undefined' && typeof crypto.randomUUID === 'function') {
    return crypto.randomUUID().replace(/-/g, '');
  }
  return Math.random().toString(36).slice(2) + Date.now().toString(36);
}

function pickWeightedCity() {
  const total = cityPool.reduce((s, c) => s + c.weight, 0);
  let r = Math.random() * total;
  for (const c of cityPool) {
    r -= c.weight;
    if (r <= 0) return c;
  }
  return cityPool[0];
}

function generateName(): { firstName: string; lastName: string } {
  const firstName = pick(firstNames);
  if (arabicFirstNames.includes(firstName))  return { firstName, lastName: pick(arabicSurnames) };
  if (africanFirstNames.includes(firstName)) return { firstName, lastName: pick(africanSurnames) };
  const s1 = pick(spanishSurnames);
  let s2 = pick(spanishSurnames);
  while (s2 === s1) s2 = pick(spanishSurnames);
  return { firstName, lastName: `${s1} ${s2}` };
}

function generatePhoto(): string {
  const isMen = Math.random() < 0.7;
  const idx = randInt(1, 99);
  return isMen
    ? `https://randomuser.me/api/portraits/men/${idx}.jpg`
    : `https://randomuser.me/api/portraits/women/${idx}.jpg`;
}

function generateWeeklyHours(): { days: string[]; opensAt: string; closesAt: string } {
  const r = Math.random();
  if (r < 0.60) return { days: ['Mon','Tue','Wed','Thu','Fri','Sat'], opensAt: '09:00', closesAt: '19:00' };
  if (r < 0.85) return { days: ['Tue','Wed','Thu','Fri','Sat','Sun'], opensAt: '10:00', closesAt: '20:00' };
  return            { days: ['Mon','Tue','Wed','Thu','Fri'],         opensAt: '09:00', closesAt: '18:00' };
}

function generateServices(): FakeService[] {
  const count = randInt(3, 5);
  const pool = [...servicePool];
  const out: FakeService[] = [];
  for (let i = 0; i < count && pool.length > 0; i++) {
    const idx = Math.floor(Math.random() * pool.length);
    const spec = pool.splice(idx, 1)[0];
    out.push({ name: spec.name, price: randInt(spec.minPrice, spec.maxPrice), duration: spec.duration });
  }
  return out;
}

function generateReviews(): FakeReview[] {
  const count = randInt(3, 8);
  const out: FakeReview[] = [];
  const now = Date.now();
  const DAY = 24 * 60 * 60 * 1000;
  for (let i = 0; i < count; i++) {
    out.push({
      rating: Math.random() < 0.5 ? 4 : 5,
      comment: pick(reviewComments),
      clientName: pick(reviewerNames),
      createdAt: now - randInt(0, 180) * DAY,
    });
  }
  return out;
}

function generateLanguages(): string[] {
  const langs = ['es'];
  if (Math.random() < 0.5) langs.push(Math.random() < 0.5 ? 'en' : 'ar');
  return langs;
}

function generateSpecialties(): string[] {
  const count = randInt(2, 3);
  const pool = [...specialtyPool];
  const out: string[] = [];
  for (let i = 0; i < count && pool.length > 0; i++) {
    const idx = Math.floor(Math.random() * pool.length);
    out.push(pool.splice(idx, 1)[0]);
  }
  return out;
}

function generateRating(): number {
  return Math.round((4.2 + Math.random() * 0.8) * 10) / 10;
}

export function generateFakeBarbers(count: number): FakeBarber[] {
  const out: FakeBarber[] = [];
  const now = Date.now();
  const DAY = 24 * 60 * 60 * 1000;
  const THIRTY_DAYS = 30 * DAY;
  for (let i = 0; i < count; i++) {
    const { firstName, lastName } = generateName();
    const cityEntry = pickWeightedCity();
    const photo = generatePhoto();
    const reviews = generateReviews();
    out.push({
      userId: uid(),
      firstName,
      lastName,
      photoUrl: photo,
      role: 'professional',
      isFake: true,
      city: cityEntry.city,
      country: 'ES',
      createdAt: now - randInt(0, 365) * DAY,

      bio: pick(bioPool),
      isLive: true,
      isSolo: true,
      approvalStatus: 'approved',
      isVisible: true,
      rating: generateRating(),
      reviewCount: reviews.length,
      totalCuts: randInt(80, 600),
      experienceStartYear: randInt(2010, 2022),
      languages: generateLanguages(),
      specialties: generateSpecialties(),
      currency: 'EUR',
      lastActive: now - Math.floor(Math.random() * THIRTY_DAYS),
