      location: { lat: cityEntry.lat, lng: cityEntry.lng },

      services: generateServices(),
      weeklyHours: generateWeeklyHours(),
      reviews,
    });
  }
  return out;
}

export function generateFakeShops(count: number): FakeShop[] {
