function getAdminApp(): App {
  const existingApps = getApps();
  if (existingApps.length > 0) return existingApps[0];

  // If explicit service account credentials are set, use them.
  // Otherwise fall back to Application Default Credentials (ADC),
  // which work in Cloud Run / Firebase-hosted environments.
  if (process.env.FIREBASE_ADMIN_PRIVATE_KEY) {
    return initializeApp({
      credential: cert({
        projectId: process.env.FIREBASE_ADMIN_PROJECT_ID,
        clientEmail: process.env.FIREBASE_ADMIN_CLIENT_EMAIL,
        privateKey: process.env.FIREBASE_ADMIN_PRIVATE_KEY.replace(/\\n/g, '\n'),
      }),
    });
  }

  return initializeApp();
}

function getFirestoreErrorMessage(error: any): string {
  switch (error?.code) {
    case 'permission-denied':
      return "You don't have permission to do this. Please log in again.";
    case 'not-found':
      return 'This record no longer exists.';
    case 'already-exists':
      return 'This already exists.';
    case 'resource-exhausted':
      return 'Too many requests. Please wait a moment.';
    case 'unauthenticated':
      return 'Please log in to continue.';
    case 'network-request-failed':
      return 'Network error. Check your connection.';
    case 'unavailable':
      return 'Service temporarily unavailable. Try again.';
    default:
      return 'Something went wrong. Please try again.';
  }
}

export async function safeFirestoreWithRetry<T>(
  operation: () => Promise<T>,
  options?: {
    maxRetries?: number;
    successMessage?: string;
    errorMessage?: string;
  }
): Promise<T | null> {
  const maxRetries = options?.maxRetries ?? 3;
  const delays = [1000, 2000, 4000];

  for (let attempt = 0; attempt <= maxRetries; attempt++) {
    try {
      const result = await operation();
      if (options?.successMessage) toast.success(options.successMessage);
      return result;
    } catch (error: any) {
      const isRetryable = RETRYABLE_CODES.includes(error?.code);
      const isLastAttempt = attempt === maxRetries;

      if (!isRetryable || isLastAttempt) {
        const message = options?.errorMessage ?? getFirestoreErrorMessage(error);
        toast.error(message);
        console.error('Firestore write failed after retries:', error);
        return null;
      }

      await new Promise(resolve => setTimeout(resolve, delays[attempt] ?? 4000));
    }
  }
  return null;
}

export async function safeFirestore<T>(
  operation: () => Promise<T>,
  options?: {
    successMessage?: string;
    errorMessage?: string;
    silent?: boolean;
    loadingToastId?: string;
  }
): Promise<T | null> {
  try {
    const result = await operation();
    if (options?.successMessage) {
      if (options.loadingToastId) {
        toast.success(options.successMessage, { id: options.loadingToastId });
      } else {
        toast.success(options.successMessage);
      }
    }
    return result;
  } catch (error: any) {
    const message = options?.errorMessage ?? getFirestoreErrorMessage(error);
    if (!options?.silent) {
      if (options?.loadingToastId) {
        toast.error(message, { id: options.loadingToastId });
      } else {
        toast.error(message);
      }
    }
    console.error('Firestore error:', {
      code: error?.code,
      message: error?.message,
      operation: operation.toString().substring(0, 100),
    });
    return null;
  }
}

function detectLanguage(): Language {
  if (typeof window === 'undefined') return 'en';
  const saved = localStorage.getItem(STORAGE_KEY);
  if (saved === 'fr' || saved === 'es' || saved === 'en') return saved;
  const browser = navigator.language.toLowerCase();
  if (browser.startsWith('fr')) return 'fr';
  if (browser.startsWith('es')) return 'es';
  return 'en';
}

export function LangProvider({ children }: { children: React.ReactNode }) {
  const [lang, setLangState] = useState<Language>(() => {
    if (typeof window === 'undefined') return 'en';
    return detectLanguage();
  });

  const setLang = (l: Language) => {
    setLangState(l);
    localStorage.setItem(STORAGE_KEY, l);
  };

  const t = (path: string): string => {
    const keys = path.split('.');
    let current: any = translations[lang];
    for (const key of keys) {
      if (current?.[key] === undefined) {
        let fallback: any = translations.en;
        for (const k of keys) {
          fallback = fallback?.[k];
        }
        return fallback ?? path;
      }
      current = current[key];
    }
    return current ?? path;
  };

  return (
    <LangContext.Provider value={{ lang, setLang, t }}>
      {children}
    </LangContext.Provider>
  );
}

export function useLang() {
  return useContext(LangContext);
}

