export async function getISO6391(): Promise<any> {
  if (_ISO6391) return _ISO6391;

  try {
    const mod: any = await import('iso-639-1');
    _ISO6391 = mod?.default ?? mod;

    // Some bundler interop paths wrap the class one level deeper, e.g.
    // `{ default: { default: class ISO6391 {} } }`. If our resolved value
    // doesn't actually expose the expected static methods, probe one key
    // deeper and re-assign if we find them there.
    if (typeof _ISO6391?.getAllNames !== 'function') {
      const keys = Object.keys(_ISO6391 || {});
      if (keys.length > 0) {
        const inner = _ISO6391[keys[0]];
        if (typeof inner?.getAllNames === 'function') {
          _ISO6391 = inner;
        }
      }
    }
  } catch (e) {
    console.error('iso-639-1 load failed:', e);
  }

  return _ISO6391;
}

export async function getLanguageOptions(): Promise<LanguageOption[]> {
  const ISO6391 = await getISO6391();
  if (!ISO6391) return [];

  try {
    return ISO6391.getAllNames().map((name: string) => ({
      value: name,
      label: name,
    }));
  } catch (e) {
    console.error('Language options failed:', e);
    return [];
  }
}

export function normalizeLocation(value: string): string {
  if (!value || typeof value !== 'string') return '';
  return value
    .trim()
    .toLowerCase()
    .split(' ')
    .map(word => (word ? word.charAt(0).toUpperCase() + word.slice(1) : ''))
    .join(' ');
}

export function locationsMatch(stored: string, selected: string): boolean {
  if (!stored || !selected) return false;
  const a = stored.toLowerCase().trim();
  const b = selected.toLowerCase().trim();
  return a === b || a.includes(b) || b.includes(a);
}

export function isProfileComplete(user: Record<string, any>): boolean {
  if (!user) return false;

  const hasBasicFields =
    !!user.firstName?.trim() &&
    !!user.lastName?.trim() &&
    !!user.phone?.trim() &&
    !!user.city?.trim() &&
    !!user.country?.trim();

  if (!hasBasicFields) return false;

  // Professionals: isOnboarded flag on the users doc is the sole routing gate.
  // phone/city/country live authoritatively on professionalProfiles, not users,
  // so we do not check them here for professionals.
  if (user.role === 'professional') {
    return user.isOnboarded === true;
  }

  return true;
}

export function getMissingFields(user: Record<string, any>): string[] {
  const missing: string[] = [];
  if (!user?.firstName?.trim()) missing.push('firstName');
  if (!user?.lastName?.trim()) missing.push('lastName');
  if (!user?.phone?.trim()) missing.push('phone');
  if (!user?.city?.trim()) missing.push('city');
  if (!user?.country?.trim()) missing.push('country');
  if (user?.role === 'professional' && PROFESSIONAL_DEFAULTS.includes(user?.city)) {
    if (!missing.includes('city')) missing.push('city');
  }
  return missing;
}

export default function Providers({ children }: { children: ReactNode }) {
  if (persister) {
    return (
      <PersistQueryClientProvider
        client={queryClient}
        persistOptions={{ persister, maxAge: 5 * 60 * 1000 }}
      >
        {children}
      </PersistQueryClientProvider>
    );
  }

  return (
    <QueryClientProvider client={queryClient}>
      {children}
    </QueryClientProvider>
  );
}

export function sanitizeText(input: string, maxLength: number = 500): string {
  if (!input || typeof input !== 'string') return '';
  return input
    .trim()
    .slice(0, maxLength)
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#x27;')
    .replace(/\//g, '&#x2F;')
    .replace(/\\/g, '&#x5C;')
    .replace(/`/g, '&#96;');
}

export function sanitizeUrl(url: string): string {
  if (!url || typeof url !== 'string') return '';
  const trimmed = url.trim();
  if (!trimmed.startsWith('http://') && !trimmed.startsWith('https://')) return '';
  if (trimmed.toLowerCase().includes('javascript:')) return '';
  return trimmed.slice(0, 500);
}

export function sanitizeHandle(handle: string): string {
  if (!handle || typeof handle !== 'string') return '';
  return handle
    .trim()
    .replace(/[^a-zA-Z0-9._-]/g, '')
    .slice(0, 100);
}

export function sanitizeBarberCode(input: string): string {
  return input.replace(/[^A-Z0-9-]/g, '').toUpperCase().slice(0, 10);
}

export function sanitizePhone(input: unknown): string {
  if (!input || typeof input !== 'string') return '';
  return input.trim().replace(/[^0-9+\-\s()]/g, '').slice(0, 20);
}

export function sanitizeProfileData(data: Record<string, any>): Record<string, any> {
  return {
    ...data,
    firstName: sanitizeText(data.firstName, 100),
    lastName: sanitizeText(data.lastName, 100),
    bio: sanitizeText(data.bio, 2000),
    phone: sanitizePhone(data.phone),
    city: sanitizeText(data.city, 100),
  };
}

export function sanitizeServiceData(data: Record<string, any>): Record<string, any> {
  return {
    ...data,
    name: sanitizeText(data.name, 100),
    description: sanitizeText(data.description || '', 500),
  };
}

export function sanitizeReviewData(data: Record<string, any>): Record<string, any> {
  return {
    ...data,
    comment: sanitizeText(data.comment || '', 1000),
    clientName: sanitizeText(data.clientName, 100),
  };
}

export function sanitizeShopData(data: Record<string, any>): Record<string, any> {
  return {
    ...data,
    name: sanitizeText(data.name, 100),
    description: sanitizeText(data.description || '', 2000),
    googleMapsUrl: sanitizeUrl(data.googleMapsUrl),
  };
}

export function getScheduleDocId(uid: string): string {
  return `${uid}_shard_0`
}

export function getLocalDateString(timezone?: string): string {
  try {
    if (timezone) {
      const now = new Date()
      const formatter = new Intl.DateTimeFormat('en-CA', {
        timeZone: timezone,
        year: 'numeric',
        month: '2-digit',
        day: '2-digit'
      })
      return formatter.format(now)
    }
  } catch (e) {
    // fallback if timezone is invalid
  }
  const now = new Date()
  return `${now.getFullYear()}-` +
    `${String(now.getMonth() + 1).padStart(2, '0')}-` +
    `${String(now.getDate()).padStart(2, '0')}`
}

export function getLocalHourString(timezone?: string): string {
  try {
    if (timezone) {
      const now = new Date()
      const formatter = new Intl.DateTimeFormat('en-GB', {
        timeZone: timezone,
        hour: '2-digit',
        hour12: false
      })
      const hour = formatter.format(now).split(':')[0]
      return `${hour.padStart(2, '0')}:00`
    }
  } catch (e) {
    // fallback
  }
  const now = new Date()
  return `${String(now.getHours()).padStart(2, '0')}:00`
}

export function getOpenStatus(
  availableSlots: Record<string, string[]> | null | undefined,
  city?: string,
  country?: string,
  barberId?: string
): OpenStatus {
  // Check cache (1 minute)
  if (barberId) {
    const cached = statusCache.get(barberId)
    if (cached && Date.now() - cached.timestamp < 60000) {
      return cached.result
    }
  }

  if (!availableSlots || Object.keys(availableSlots).length === 0) {
    return { label: 'Schedule not set', color: 'text-[#555]', isOpen: false, state: 'no_schedule' }
  }

  const timezone = getTimezoneFromLocation(city, country)
  const todayDate = getLocalDateString(timezone)
  const nowStr = getLocalHourString(timezone)
  const nowHour = parseInt(nowStr.split(':')[0])

  const todaySlots = availableSlots[todayDate] || []

  if (todaySlots.length === 0) {
    // Check if there are future slots this week to show next open time
    const futureDates = Object.keys(availableSlots).filter(d => d > todayDate).sort()

    if (futureDates.length > 0) {
      const nextDate = futureDates[0]
      const nextSlots = availableSlots[nextDate]
      if (nextSlots && nextSlots.length > 0) {
        const nextDateObj = new Date(nextDate + 'T12:00:00')
        const dayName = nextDateObj.toLocaleDateString('en-US', { weekday: 'short' })
        const result: OpenStatus = {
          label: `🔴 Closed · Opens ${dayName} ${nextSlots[0]}`,
          color: 'text-[#ef4444]',
          isOpen: false,
          state: 'closed'
        }
        if (barberId) statusCache.set(barberId, { result, timestamp: Date.now() })
        return result
      }
    }

    const result: OpenStatus = {
      label: '🔴 Closed today',
      color: 'text-[#ef4444]',
      isOpen: false,
      state: 'closed'
    }
    if (barberId) statusCache.set(barberId, { result, timestamp: Date.now() })
    return result
  }

  // Check if open RIGHT NOW
  if (todaySlots.includes(nowStr)) {
    const lastHour = parseInt(todaySlots[todaySlots.length - 1]) + 1
    const closeStr = `${String(lastHour).padStart(2, '0')}:00`
    const result: OpenStatus = {
      label: `🟢 Open now · Closes ${closeStr}`,
      color: 'text-[#22c55e]',
      isOpen: true,
      state: 'open'
    }
    if (barberId) statusCache.set(barberId, { result, timestamp: Date.now() })
    return result
  }

  // Check if opening soon (within 3 hours)
  const firstHour = parseInt(todaySlots[0])
  const hoursUntilOpen = firstHour - nowHour

  if (nowHour < firstHour) {
    if (hoursUntilOpen <= 3) {
      const result: OpenStatus = {
        label: `🟡 Opens in ${hoursUntilOpen}h · at ${todaySlots[0]}`,
        color: 'text-[#F5C518]',
        isOpen: false,
        state: 'opens_soon'
      }
      if (barberId) statusCache.set(barberId, { result, timestamp: Date.now() })
      return result
    }
    const result: OpenStatus = {
      label: `🔴 Closed · Opens at ${todaySlots[0]}`,
      color: 'text-[#ef4444]',
      isOpen: false,
      state: 'closed'
    }
    if (barberId) statusCache.set(barberId, { result, timestamp: Date.now() })
    return result
  }

  // Past all slots for today — check tomorrow
  const tomorrow = new Date()
  tomorrow.setDate(tomorrow.getDate() + 1)
  const tomorrowDate = `${tomorrow.getFullYear()}-` +
    `${String(tomorrow.getMonth() + 1).padStart(2, '0')}-` +
    `${String(tomorrow.getDate()).padStart(2, '0')}`

  const tomorrowSlots = availableSlots[tomorrowDate] || []

  if (tomorrowSlots.length > 0) {
    const result: OpenStatus = {
      label: `🔴 Closed · Opens tomorrow ${tomorrowSlots[0]}`,
      color: 'text-[#ef4444]',
      isOpen: false,
      state: 'closed'
    }
    if (barberId) statusCache.set(barberId, { result, timestamp: Date.now() })
    return result
  }

  const result: OpenStatus = {
    label: '🔴 Closed for today',
    color: 'text-[#ef4444]',
    isOpen: false,
    state: 'closed'
  }
  if (barberId) statusCache.set(barberId, { result, timestamp: Date.now() })
  return result
}

function envFlagOn(): boolean {
  return process.env.NEXT_PUBLIC_TITIZA_PHASE2_ENABLED === 'true';
}

export function isTitizaPhase2Enabled(uid?: string | null): boolean {
  if (TEMP_ENABLE_GLOBALLY) return true;

  if (envFlagOn()) return true;
  if (uid && PHASE2_TEST_UIDS.includes(uid)) return true;
  return false;
}

